INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 174, 'single', '生成式大模型可能会引发内容安全风险,以下哪个选项不属于内容安全风险?', '[{"key":"A","text":"生成违法信息","correct":false},{"key":"B","text":"生成虚假内容","correct":false},{"key":"C","text":"生成不相关内容","correct":true},{"key":"D","text":"生成带有偏见的内容","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
