INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 176, 'single', '关于技术团队在大模型微调项目中的作用,下列哪一项描述不够准确?', '[{"key":"A","text":"确保团队成员掌握深度学习、自然语言处理等相关技术","correct":false},{"key":"B","text":"仅需关注模型训练过程,模型部署与维护由其他部门负责","correct":true},{"key":"C","text":"负责实现模型微调过程中的技术细节调整和优化","correct":false},{"key":"D","text":"参与评估模型性能,根据反馈调整微调策略","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 177, 'single', '在确保计算资源与基础设施满足大模型微调需求时,哪项不是关键考量指标?', '[{"key":"A","text":"GPU的数量和型号,以支持大规模并行计算","correct":false},{"key":"B","text":"存储容量,以保存庞大的预训练模型及训练过程中的中间状态","correct":false},{"key":"C","text":"操作系统的用户界面设计","correct":true},{"key":"D","text":"网络带宽,以便快速传输训练所需的大规模数据集","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 178, 'single', '多Agent系统通过模拟或利用多个交互的智能体来解决复杂问题。如果在一个复杂的金融交易市 场模拟中,使用多Agent系统的优势不包括:', '[{"key":"A","text":"能够模拟多个投资者的独立决策过程,增加市场仿真度","correct":false},{"key":"B","text":"通过Agent间的竞争与合作模型,更准确地反映市场动态","correct":false},{"key":"C","text":"单一Agent即可处理所有市场参与者的策略制定与执行,简化系统设计","correct":true},{"key":"D","text":"利用多Agent的异构性探索更多元化的交易策略","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 179, 'single', '多Agent系统,就是让机器模拟或利用多个AI实例,来协作解决问题。设计巧妙的Agent之间共 享信息的方法,往往能提升多Agent系统的搜索效率。在一个多Agent搜救场景中,若要最大化搜索效 率,以下哪种策略最不合理?', '[{"key":"A","text":"根据已探索区域的信息动态调整各Agent的搜索路径","correct":false},{"key":"B","text":"各Agent独立行动,完全不共享发现的遇险信号信息","correct":true},{"key":"C","text":"设计一种机制,让Agent在遇到困难时能请求附近Agent的协助","correct":false},{"key":"D","text":"利用环境建模预测可能的遇险位置,指导Agent优先搜索","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 180, 'single', '以下描述中错误的是?', '[{"key":"A","text":"优秀的基础模型(大模型)只需要自身庞大的参数规模和计算硬件,对数据量没有太大要求","correct":true},{"key":"B","text":"小明希望做一个企业专有的知识库工程,他可以在基座模型上用微调的形式来实现","correct":false},{"key":"C","text":"生成式人工智能是机器学习中快速增长的子集","correct":false},{"key":"D","text":"深度学习是机器学习的一个分支","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 181, 'single', '如果我们让大模型系统设计一个分阶段、分批次的投资策略,大模型系统需要考虑各种不同的 资产组合、投资策略,综合考虑成本、风险、收益之后,生成最优的投资策略。那么,在设计大模 型系统应对多路径策略规划时,以下哪种方式不能有效避免策略冲突和资源浪费?', '[{"key":"A","text":"建立中心化协调机制,监控并调度各Agent的行动策略","correct":false},{"key":"B","text":"采用博弈论模型预测并解决潜在的策略冲突","correct":false},{"key":"C","text":"强制所有Agent采用相同的决策逻辑和目标函数以保证一致性","correct":true},{"key":"D","text":"开发自适应学习算法,让Agent根据环境反馈自我调整策略","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 182, 'single', 'ModelScope-Agent 的核心优势之一是其高度的可定制性,这主要得益于其:', '[{"key":"A","text":"强大的预训练模型阵容,直接提供最优性能无需调整","correct":false},{"key":"B","text":"简化的Agent实现流程,允许用户仅通过指定角色描述等基本信息即可快速搭建应用","correct":true},{"key":"C","text":"限制性的接口设计,确保了所有组件的严格一致性","correct":false},{"key":"D","text":"集成了固定的工具集,减少了用户选择的复杂度","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 183, 'single', '以下哪项插件功能最可能通过大模型API及百炼应用API结合实现,以辅助日常办公?', '[{"key":"A","text":"高级图像识别与编辑","correct":false},{"key":"B","text":"实时多语言翻译服务","correct":true},{"key":"C","text":"复杂的3D建模与渲染","correct":false},{"key":"D","text":"高精度的物理实验模拟","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 184, 'single', '以下哪个选项属于我们在本教程中介绍的RAG应用范围?', '[{"key":"A","text":"向大模型输入“请介绍一下自己”","correct":false},{"key":"B","text":"向大模型输入“现在几点了?”","correct":false},{"key":"C","text":"上传知识库文件后输入“我如果发表了专利,可以得到公司的什么奖励?”","correct":true},{"key":"D","text":"向大模型输入“请搜索一下今天沪指收盘指数是多少?”","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
