INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 329, 'single', '以下描述中哪一项不属于通过多智能体进行文档质量检测的优势?', '[{"key":"A","text":"可以更专业地针对每种错误类型进行检测","correct":false},{"key":"B","text":"相较于单一模型,可能提高错误识别的覆盖率","correct":false},{"key":"C","text":"做汇总的智能体可以直接将结果拼接在一起输出","correct":true},{"key":"D","text":"减少了大模型因一次性处理过多任务而可能产生的过载","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 330, 'single', '在调用大语言模型对话的API过程中,以下哪个代码片段正确地展示了system、user和assistant三 种角色的交互顺序?', '[{"key":"A","text":"messages=[{\\"role\\": \\"assistant\\", \\"content\\": \\"你好\\"},{\\"role\\": \\"user\\",\\"content\\": \\"我想订一张机票\\"}, {\\"role\\": \\"system\\",\\"content\\":\\"你是一个订票助手\\"}]","correct":false},{"key":"B","text":"messages=[{\\"role\\": \\"system\\", \\"content\\": \\"你是一个订票助手\\"},{\\"role\\": \\"user\\", \\"content\\": \\"我想 订一张机票\\"}, {\\"role\\": \\"assistant\\",\\"content\\": \\"你好,请问你想去哪里?\\"}]","correct":true},{"key":"C","text":"messages=[{\\"role\\": \\"user\\", \\"content\\": \\"我想订一张机票\\"},{\\"role\\":\\"system\\",\\"content\\": \\"你是一个订票助 手\\"}, {\\"role\\": \\"assistant\\",\\"content\\": \\"你好,请问你想去哪里?\\"}]","correct":false},{"key":"D","text":"messages = []","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 331, 'single', '以下哪行代码能够正确调用百炼“qwen-max”模型进行对话补全?', '[{"key":"A","text":"completion = client.chat.create(model=“qwen-max”, messages=[{“role”: “user”,“content”:“你好”}])","correct":false},{"key":"B","text":"completion = client.chat.completions.create(model=“qwen-max”, messages=[{“role”: “user”, “content”:“你好”}])","correct":true},{"key":"C","text":"completion = client.chat.completions.create(model=“qwen-max”, records=[{“role”: “user”, “content”:“你好”}])","correct":false},{"key":"D","text":"completion = client.chat.create(model=“qwen-max”, records=[{“role”: “user”, “content”:“你 好”}])","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
