INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 369, 'single', '你开发了一个专用于医疗场景问答的RAG应用,为了找到优化方向,需要对其进行评测。以下 哪个是参与评测必须不可少的群体?', '[{"key":"A","text":"数据工程师。数据工程师对数据质量、数据管道和检索系统的底层逻辑有深刻理解","correct":false},{"key":"B","text":"医疗专家。医疗专家具备领域专业知识,能够从临床实践和医学指南的角度验证RAG生成答案的 准确性、安全性和实用性。","correct":true},{"key":"C","text":"算法工程师。只有算法工程师才可以更理解RAG应用的设计过程与细节。","correct":false},{"key":"D","text":"前端工程师。只有前端工程师更理解用户的交互逻辑,是最懂用户需要的群体。","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 370, 'single', '用户对你开发的聊天机器人提了反馈:总是要等10s以上才能看到答案。你考虑是否要采取流式输 出策略以下想法正确的是', '[{"key":"A","text":"可以采取流式输出,但是我要修改一下返回层面的代码,比如适配流式输出的数据格式,并且将 return改为yield","correct":true},{"key":"B","text":"不能采取流式输出,我调了好久的prompt在流式输出时效果肯定会下降","correct":false},{"key":"C","text":"不能采取流式输出,将实时返回的结果立刻返回给前端界面是一件很难做到的事情","correct":false},{"key":"D","text":"可以采取流式输出,但是我要在原有基础上调整一下temperature和top_p等参数","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 371, 'single', '你在开发一个内部IT系统,希望能够自动处理员工的请求:“我的投影仪故障了,请安排维修并 通知下午会议改线上”。以下技术方案有效,且能尽量减少人力投入?', '[{"key":"A","text":"通过提示词引导大模型直接生成维修工单和会议调整结果,无需调用现有系统。","correct":false},{"key":"B","text":"通过提示词引导大模型拆解任务为多步骤,然后自动调用维修系统和会议系统API完成操作。","correct":true},{"key":"C","text":"通过大模型判断接单人,自动将任务指派给接单人,通知其创建维修工单并调整会议。","correct":false},{"key":"D","text":"识别请求中的关键字(如“投影仪故障”“会议改线上”),匹配规则系统后调用API完成任务。","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 372, 'single', '某公司更新了组织架构,但知识库里还是旧文档,查询结果经常过时。为避免回答陈旧信息, 最合适的方式是', '[{"key":"A","text":"定期同步最新文档并重建索引","correct":true},{"key":"B","text":"提升大模型温度让其自由生成","correct":false},{"key":"C","text":"调整Node Parser切片长度","correct":false},{"key":"D","text":"对旧知识不做任何处理","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 373, 'single', '你想在面向高中生的技术分享里,用大模型生动地解释阿里云弹性容器实例(ECI)的基本原理。 下列哪种提示词最能实现易懂、形象化的效果?', '[{"key":"A","text":"简短介绍ECI功能即可。","correct":false},{"key":"B","text":"写一篇详尽ECI论文,全部使用专业术语。","correct":false},{"key":"C","text":"仅列出ECI命令和参数列表。","correct":false},{"key":"D","text":"请以高中生能理解的方式,使用生动比喻讲解ECI原理。","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 374, 'single', '在RAG的建立索引过程中,以下哪一点是将知识库文件分割成文本段的主要原因?', '[{"key":"A","text":"减少索引构建时间","correct":false},{"key":"B","text":"减少数据存储空间","correct":false},{"key":"C","text":"让大模型输出更加多样","correct":false},{"key":"D","text":"提高检索精度,更快定位相关段落","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 375, 'single', '你希望大模型客服在处理模糊请求时(如用户说“我想订票”), 能主动追问必要信息(如时间、地 点)。以下那种提示词设计最有效?', '[{"key":"A","text":"你是一个订票客服人员。请根据用户提供的信息来回答问题或进行订票。","correct":false},{"key":"B","text":"你是一个订票客服人员。对于订票问题,如果信息不完整,请向用户主动询问订票相关信息。如 果是其他票务问题,则正常回答。","correct":false},{"key":"C","text":"你是一个细心的订票客服人员。注意每次回复后必须追加一个问题,例如请问需要补充什么信 息?","correct":false},{"key":"D","text":"你是一个订票客服人员。对于订票问题,如果信息不完整,应该向用户提问,直到获取了完整的 出发地、目的地、时间信息。如果是其他票务问题,则正常回答。","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 376, 'single', '在为多轮对话场景设计的RAG应用中,大模型参与了什么步骤?', '[{"key":"A","text":"检索步骤、Query改写步骤","correct":false},{"key":"B","text":"检索步骤、Query改写步骤、生成步骤","correct":true},{"key":"C","text":"Query改写步骤、生成步骤","correct":false},{"key":"D","text":"只有生成步骤","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 377, 'single', '你希望让RAG回答用户问题时,避免用户获取到超出其可访问权限的内容,以下那种方案更合 适?', '[{"key":"A","text":"使用提示词模板,将用户的身份信息(如部门名)拼接在模板合适的位置上","correct":false},{"key":"B","text":"标量+向量混合检索:基于用户身份,在其有权限的文档范围内进行向量检索","correct":true},{"key":"C","text":"为每个用户动态生成并维护一个完全独立的向量索引库,实时更新所有用户索引","correct":false},{"key":"D","text":"通过提示词引导大模型结合用户身份来做出不同的回答","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 378, 'single', '以下那种场景适合使用阿里云百炼上提供的大模型Batch API(批量处理接口) 来优化成本或效 率?', '[{"key":"A","text":"收集一周内的数千条产品用户反馈信息,打包后一次性提交给大模型生成分析总结报告","correct":true},{"key":"B","text":"在实时在线客服对话中,使用Batch API同时处理多个用户的并发请求,以提高响应速度","correct":false},{"key":"C","text":"将Batch API与流式传输(Streaming)结合,逐步返回批量处理中的部分结果给用户","correct":false},{"key":"D","text":"在会议直播场景中,使用Batch API让大模型将主讲人的发言实时翻译成多个语种","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 379, 'single', '在优化检索效果时,若知识库内容充足但召回率低,以下那种方法是合理的?', '[{"key":"A","text":"增加知识库文档","correct":false},{"key":"B","text":"更换embedding模型","correct":true},{"key":"C","text":"增加查询请求的并发量以加快响应速度","correct":false},{"key":"D","text":"提高相似度阈值","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 380, 'single', '某企业需要部署一个大模型,不定期自动地分析现有的产品文档,并产出改进建议。以下哪一 种计费方式可以在满足业务需求的同时最大化降低运行成本?', '[{"key":"A","text":"使用抢占式实例(Spot Instance),同时设计好任务中断的自动恢复机制","correct":true},{"key":"B","text":"通过按量付费方式创建GPU资源","correct":false},{"key":"C","text":"购买显卡并搭建本地服务器","correct":false},{"key":"D","text":"通过预付费(包年包月)方式创建GPU资源","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 381, 'single', '模型微调适合解决哪种任务?', '[{"key":"A","text":"数据分布剧烈漂移的任务","correct":false},{"key":"B","text":"需要模型学习专业领域知识的任务","correct":true},{"key":"C","text":"需要学习庞大知识库的任务","correct":false},{"key":"D","text":"数据量极小的任务","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 382, 'single', '你开发了一个RAG应用,发现用户经常连续提问(多轮对话),但是当前应用还不支持多轮对 话。你应该怎么改造检索步骤来进行适配?', '[{"key":"A","text":"检索时,将用户的问题输入向量数据库进行检索","correct":false},{"key":"B","text":"检索时,先用大模型对历史对话以及用户输入进行总结,生成一个新的query,然后用新query输 入向量数据库进行检索","correct":true},{"key":"C","text":"检索时,由大模型判断哪些文本段是相关的","correct":false},{"key":"D","text":"检索时将历史对话信息输入向量数据库进行检索","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 383, 'single', '有用户使用"找张伟"这类极简搜索,RAG系统经常没能检索到所需文档。最合理的技术改进是什 么?', '[{"key":"A","text":"将所有文档发布成内部Wiki","correct":false},{"key":"B","text":"在检索前先用大模型进行问题改写扩充","correct":true},{"key":"C","text":"在回答时忽视用户的问题","correct":false},{"key":"D","text":"让用户输入更多关键词","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 384, 'single', '某创业公司开发的“AI法律助手”应用,能自动生成合同条款与诉讼风险评估报告。在正式上线 应用商店前,必须完成的最关键合规步骤是哪个?', '[{"key":"A","text":"为AI生成内容申请知识产权保护","correct":false},{"key":"B","text":"通过国家网信部门的大模型算法备案","correct":true},{"key":"C","text":"建立用户投诉赔偿基金","correct":false},{"key":"D","text":"获取信息系统安全等级保护三级认证","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 385, 'single', '你在开发一个旅途规划系统,希望该系统能够帮助用户规划出行交通方式、具体景点行程、以 及住宿安排并且将总预算控制在指定范围内。以下哪种设计方案更为合理', '[{"key":"A","text":"基于工作流,按照常用顺序(交通->景点->住宿)依次调用对应服务API->基于模板汇总子Agent执行 结果","correct":false},{"key":"B","text":"设计一个多Agent系统,主Agent拆分任务-->子Agent独立执行-->基于模板汇总子Agent执行结果","correct":false},{"key":"C","text":"设计一个多Agent系统,规划Agent规划拆分任务-->子Agent并行执行-->汇总Agent校验冲突(如或 酒店与交通预订时间冲突)","correct":true},{"key":"D","text":"设计一个单Agent系统,依次调用对应服务API,在代码中写好预算分配规则,最终基于模板汇总 信息形成规划表格","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 386, 'single', '开发过程中,你注意到系统日志显示大模型对某工具函数调用频率异常高,但调用结果经常出 错。最可能的原因是什么?', '[{"key":"A","text":"该工具函数的描述过于宽泛,导致大模型误以为适用于多种任务","correct":true},{"key":"B","text":"该工具函数的调用接口存在安全漏洞","correct":false},{"key":"C","text":"大模型的计算资源不足","correct":false},{"key":"D","text":"用户输入错误导致大模型误调用该工具","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 387, 'single', '在意图识别中,以下哪种方法不需要修改模型本身的参数?', '[{"key":"A","text":"使用提示词","correct":true},{"key":"B","text":"对模型进行微调","correct":false},{"key":"C","text":"增加模型的训练数据","correct":false},{"key":"D","text":"减少模型的推理时间","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 388, 'single', '在RAG应用的多轮对话中,custom_chat_history的主要作用是什么?', '[{"key":"A","text":"存储历史对话信息","correct":true},{"key":"B","text":"增加模型的训练数据","correct":false},{"key":"C","text":"减少模型的推理时间","correct":false},{"key":"D","text":"增加模型的参数数量","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 389, 'single', 'Ragas 提供的以下哪些指标用于评估生成答案与检索资料的事实一致性?', '[{"key":"A","text":"Faithfulness","correct":true},{"key":"B","text":"Answer Relevancy","correct":false},{"key":"C","text":"Context Precision","correct":false},{"key":"D","text":"Context Recall","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
