INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 409, 'single', '为了让大模型能够回答私域知识问题,以下哪种方法更加简便且高效?', '[{"key":"A","text":"微调模型","correct":false},{"key":"B","text":"训练新模型","correct":false},{"key":"C","text":"通过提示词传递私域知识","correct":true},{"key":"D","text":"使用默认模型","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
