INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 412, 'single', '在 Answer Correctness 的计算过程中,语义相似度是通过什么模型得到的?', '[{"key":"A","text":"Embedding模型","correct":true},{"key":"B","text":"大模型","correct":false},{"key":"C","text":"增加模型的训练数据","correct":false},{"key":"D","text":"减少模型的推理时间","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 413, 'single', '阿里云DTS(数据传输服务)主要用于以下哪种场景?', '[{"key":"A","text":"模型训练加速","correct":false},{"key":"B","text":"数据库迁移与实时同步","correct":true},{"key":"C","text":"加密存储数据","correct":false},{"key":"D","text":"容器镜像管理","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
