INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 415, 'single', '在大模型训练中,以下哪种方法可以缓解梯度消失问题?', '[{"key":"A","text":"使用ReLU激活函数","correct":true},{"key":"B","text":"增大学习率","correct":false},{"key":"C","text":"减少训练数据","correct":false},{"key":"D","text":"关闭正则化","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 416, 'single', '在RAG应用中,以下哪些组件可以用于存储向量化后的文本段?', '[{"key":"A","text":"向量数据库","correct":true},{"key":"B","text":"文档解析工具","correct":false},{"key":"C","text":"文本分段工具","correct":false},{"key":"D","text":"embedding模型","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 417, 'single', '以下哪项是模型训练任务提交到PAI平台的必要步骤?', '[{"key":"A","text":"配置VPC网络","correct":false},{"key":"B","text":"准备OSS数据路径","correct":true},{"key":"C","text":"申请域名备案","correct":false},{"key":"D","text":"购买CDN服务","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 418, 'single', '在RAG应用的多轮对话中,业界常用的解决方法是什么?', '[{"key":"A","text":"增加模型的训练数据","correct":false},{"key":"B","text":"使用大模型将用户问题改写为包含历史对话关键信息的新query","correct":true},{"key":"C","text":"减少模型的推理时间","correct":false},{"key":"D","text":"增加模型的参数数量","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 419, 'single', '在RAG应用的多轮对话中,为什么不能直接将完整历史对话与问题输入到检索系统?', '[{"key":"A","text":"检索系统无法处理长文本","correct":true},{"key":"B","text":"检索速度变慢","correct":false},{"key":"C","text":"模型无法理解用户输入","correct":false},{"key":"D","text":"模型生成内容不完整","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 420, 'single', '你是某金融APP的智能投顾系统负责人,发现用户存在恶意咨询的情况,如涉及“内幕消息”等敏 感词。为了在检测到敏感词时立即返回固定话术,以下哪种方案最能满足需求?', '[{"key":"A","text":"在生成回答后追加合规性二次审核","correct":false},{"key":"B","text":"对知识库文档进行预筛查标记","correct":false},{"key":"C","text":"在用户提问时启用敏感词实时检测","correct":true},{"key":"D","text":"通过模型微调降低风险话题生成概率","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 421, 'single', '你开发智能会议助手时遇到技术选型问题,“需要将会议录音转换为文字记录,并自动生成带有 重点标注的摘要,最后将摘要内容转换为语音播报”。以下技术组合中最合理的是?', '[{"key":"A","text":"cosyvoice->v1语音合成->Qwen-VL视频理解->ComfyUI生图","correct":false},{"key":"B","text":"语音转文本服务->文本生成模型->cosyvoice->v1语音合成","correct":true},{"key":"C","text":"MoviePy视频剪辑->文本生成模型->ComfyUI生成摘要图表","correct":false},{"key":"D","text":"Qwen-VL分析会议录像->MoviePy添加字幕->文本生成摘要","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 422, 'single', '你在开发一个可以自动回答客户问题的客服平台。除了回答产品知识问题外,你希望它还能执 行与账户相关的操作(例如实时查询用户订单状态、修改账户绑定的手机号、提交工单或退款申 请)。你应该考虑引入什么技术来扩展大模型的能力?', '[{"key":"A","text":"RAG(Retrieval Augmented Generation)","correct":false},{"key":"B","text":"Agent(智能体)","correct":true},{"key":"C","text":"大模型微调","correct":false},{"key":"D","text":"数据增强","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 423, 'single', '在测试RAG应用性能时,你发现检索阶段总是出现不太相关的段落。为了提高检索准确度,你 应该怎么做?', '[{"key":"A","text":"尝试增加大模型重复惩罚系数,避免召回不相关内容","correct":false},{"key":"B","text":"尝试使用领域相关知识微调大模型,让其能更好的识别相关段落","correct":false},{"key":"C","text":"尝试调整embedding模型,并使用重排(rerank)","correct":true},{"key":"D","text":"尝试减少模型推理温度","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 424, 'single', '你在优化RAG应用时,检索条件改得非常宽松,相似度很低的文本段也可以被召回。这可能会 导致出现以下哪种情况', '[{"key":"A","text":"Context Recall(文本段召回率)变高","correct":true},{"key":"B","text":"Context Recall(文本段召回率)变低","correct":false},{"key":"C","text":"Context Recall(文本段召回率)基本不变","correct":false},{"key":"D","text":"文本段精度变高","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 425, 'single', '你将PDF文档转成普通文本后,RAG的检索质量变差。下列哪种做法最能提升检索准确度?', '[{"key":"A","text":"将文本转成更结构清晰的Markdown","correct":true},{"key":"B","text":"提前把文档压缩成ZIP再索引","correct":false},{"key":"C","text":"调整大模型输出温度(temperature)","correct":false},{"key":"D","text":"用正则表达式彻底删除停用词","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 426, 'single', '你在开发一个基于RAG的智能客服系统,用于回答用户关于产品功能的技术问题。为了提升回 答的准确性,你调整了检索模块的相似度阈值,从默认的0.7提高到了0.95。然而,测试后发现,部 分用户的提问得不到满意的回答。可能的原因是什么?', '[{"key":"A","text":"检索模块的计算复杂度增加,导致大模型推理速度变慢","correct":false},{"key":"B","text":"用户提问的语言风格与产品文档内容不一致,导致检索失败","correct":false},{"key":"C","text":"回答准确但不全面,因为过于严格的检索条件过滤掉了部分有用的上下文信息","correct":true},{"key":"D","text":"系统成功过滤掉了所有无用数据,回答的准确性和完整度都得到了显著提升","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 427, 'single', '你为教育公司搭建了RAG问答系统,且知识库存储了各部门的机密数据(如财务部的薪资表、 教务部的未公开课件)。为了确保普通员工只能访问自己有权限的数据,以下哪种做法最合适?', '[{"key":"A","text":"预处理用户问题时强制添加“请仅回答我部门数据”的提示词","correct":false},{"key":"B","text":"对大模型进行微调使其主动拒绝跨部门问题","correct":false},{"key":"C","text":"为每个用户单独生成加密密钥用于访问知识库","correct":false},{"key":"D","text":"在检索知识库时,动态筛选出用户有权限访问的文档。","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 428, 'single', '某RAG系统回答“张伟是哪个部门的”时,总是只检索到一个无关切片,导致答案不准确。为改 进检索效果,下列哪种做法有助于改善这个问题?', '[{"key":"A","text":"换用更大参数量的大模型","correct":false},{"key":"B","text":"提高检索时的召回数量(Top K)","correct":true},{"key":"C","text":"放弃知识库,全部“对话式”推理","correct":false},{"key":"D","text":"修改前端界面外观","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 429, 'single', '你所在的医院技术部正在翻译一份医学影像技术手册,包含上千条内部非公开的专业术语与缩 写。如果想在翻译时保证准确性,并减少对大量示例的依赖,以下哪种做法更合适?', '[{"key":"A","text":"仅提供少量缩写翻译示例,如“MRI→磁共振成像”,“CT→计算机断层扫描”,让大模型依照模 仿。","correct":false},{"key":"B","text":"分配“专业医学翻译员”角色,依靠零样本提示直接解决","correct":false},{"key":"C","text":"接入专业术语库,并使用RAG技术,以动态查询并统一术语标准","correct":true},{"key":"D","text":"尽可能增加示例数量,用穷举方式涵盖所有缩写的翻译场景。","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 430, 'single', '假设你正在使用大模型解决以下数学问题:“小明每天存入银行10元钱,但每周末(周六和周 日)会取出20元用于消费。如果小明从某周一(第一天)开始存钱,青问小明需要多少天才能存够 100元?”为了提升大模型解答此类问题的准确率,以下哪种提示方法最能有效引导大模型生', '[{"key":"A","text":"提供少量样例","correct":false},{"key":"B","text":"明确输出要求","correct":false},{"key":"C","text":"思维链方法","correct":true},{"key":"D","text":"提供受众和角色","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 431, 'single', '你开发了一个聊天机器人,用户反馈每次提问后总是要等很久才能看到回复,你应该怎么做?', '[{"key":"A","text":"在生成间隙通过前端界面展示动画,减少用户等待的疲惫感","correct":false},{"key":"B","text":"提醒用户输入尽量少的提示词","correct":false},{"key":"C","text":"降低temperature值","correct":false},{"key":"D","text":"采用流式输出","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 432, 'single', '大模型如何判断什么时候应该停止输出?', '[{"key":"A","text":"需要用户手动打断","correct":false},{"key":"B","text":"只会在输出长度达到阈值时停止","correct":false},{"key":"C","text":"当模型检测到生成内容与输入主题无关时自动停止","correct":false},{"key":"D","text":"在输出长度达到阈值,或输出特殊Token(如,end of sentence,即“句子结束”标记)","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 433, 'single', '公司新发了《远程办公规定》,你想让现有答疑机器人掌握这份规定的内容。基于已经搭建好 的RAG应用,你应该怎么做?', '[{"key":"A","text":"将新文档分块后更新向量数据库","correct":true},{"key":"B","text":"在提示词模板中增加远程办公规定的内容","correct":false},{"key":"C","text":"微调大模型以确保大模型能理解新规定的内容","correct":false},{"key":"D","text":"使用纯规则引擎匹配","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 434, 'single', '你准备为企业内部人事系统搭建一个多轮问答功能,现有历史对话:“张三的办公楼在哪?”, “在A栋一楼”,“他的主管是谁?”。你应该怎么设计检索步骤?', '[{"key":"A","text":"对“主管”进行同义词扩展,包含“领导”、“上级”等,提高召回率","correct":false},{"key":"B","text":"提高检索的相似度阈值,确保不包含无用信息","correct":false},{"key":"C","text":"结合对话历史改写query,再进行检索","correct":true},{"key":"D","text":"混合使用关键词检索与向量检索策略","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 435, 'single', '大模型在处理输入文本时,第一步通常执行的操作是?', '[{"key":"A","text":"Token向量化","correct":false},{"key":"B","text":"对输入文本进行分词(Tokenize)","correct":true},{"key":"C","text":"计算候选Token概率","correct":false},{"key":"D","text":"计算Embedding后的向量","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 436, 'single', '你在调用通义千问API时设置了temperature(温度)参数,以下哪种说法是正确的?', '[{"key":"A","text":"温度参数越高,候选Token的概率值会越接近,从而带来更高的随机性","correct":true},{"key":"B","text":"温度参数越高,候选Token的概率值之间的差距会变大,从而带来更高的随机性","correct":false},{"key":"C","text":"温度参数越高,低概率的候选Token有概率超过高概率的候选Token的概率","correct":false},{"key":"D","text":"温度参数越高,越适合撰写技术报告、代码等有较高确定性需求的场景","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 437, 'single', '你在为一个创意写作工具调整大模型生成内容,以下哪个参数可以用来控制生成内容的多样 性?', '[{"key":"A","text":"temperature","correct":true},{"key":"B","text":"max_token","correct":false},{"key":"C","text":"stream","correct":false},{"key":"D","text":"api_key","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 438, 'single', '你在优化一个多语言翻译系统,发现文学翻译经常“失去原文意境”,而技术文档翻译经常“用词 生硬、难以理解”。现有提示词已包含“保持专业性和语言流畅”要求,并添加了示例。下一步最应优 先尝试的策略是?', '[{"key":"A","text":"要求模型分两次翻译:先直译再人工润色","correct":false},{"key":"B","text":"提高温度参数(Temperature=1.0)增强灵活性","correct":false},{"key":"C","text":"在现有模板中增加更多诗歌和手册的对照示例","correct":false},{"key":"D","text":"为文学和技术翻译分别设计专用提示词模板","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 439, 'single', '你正在使用Qwen-Plus生成商品介绍文档,完整的提示词是“请帮我生成我们公司最新智能手表的 产品介绍”。但你发现生成的内容是介绍其他公司的产品。以下策略中,应首先尝试的是?', '[{"key":"A","text":"调低温度参数(Temperature)以降低随机性","correct":false},{"key":"B","text":"调低Top-p值缩小候选词范围","correct":false},{"key":"C","text":"改进提示词(明确产品信息、文档主题和结构)","correct":true},{"key":"D","text":"提高Top-p值扩大候选词范围","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 440, 'single', '你正在尝试使用大模型Qwen-72B完成一个用户反馈分类任务,但效果不佳。以下选项中,你应 首先考虑的策略是?', '[{"key":"A","text":"微调大模型(Fine-tuning)","correct":false},{"key":"B","text":"换用Qwen-14B模型","correct":false},{"key":"C","text":"改进提示词(Prompt Engineering)","correct":true},{"key":"D","text":"调整模型的温度参数(Temperature)","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 441, 'single', '你需要大模型对用户输入的新闻内容进行分类(体育/经济/娱乐三种)。为提升准确性且便于程 序解析,以下哪个提示词更合理?', '[{"key":"A","text":"请根据下面提供的内容判断其类别(体育/经济/娱乐),只输出判断结果。内容是:...","correct":false},{"key":"B","text":"请根据下面提供的内容判断其类别(体育/经济/娱乐)。以JSON格式输出(“reason”:“原 因”,“type”:“类别”,如:体育|经济|娱乐”)内容是:...","correct":true},{"key":"C","text":"请根据下面提供的内容判断其类别(体育/经济/娱乐)。先输出思考过程,再在最后一行用“结 论:”开头写明类别。内容是:...","correct":false},{"key":"D","text":"请根据下面提供的内容判断其类别(体育/经济/娱乐)。用符号分隔:思考过程|类别结果。内容 是:...","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 442, 'single', '你是某公司IT部门主管,想使用大模型生成符合公司内部编码规范的Java代码模板,请问以下哪 个提示词更合适?', '[{"key":"A","text":"请帮我生成一份java代码,用于...","correct":false},{"key":"B","text":"请帮我生成一份java代码。需求是:...要求是:符合下列编码规范...","correct":true},{"key":"C","text":"请逐步分析需求,然后生成一份java代码。需求是:...","correct":false},{"key":"D","text":"请参考开源社区流行的编码风格,生成一份java代码。需求是:...","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 443, 'single', '你开发了一个RAG应用,发现其在回答内部流程问题(如“报销系统登录方式”)时准确率高, 但回答通识性问题(如“如何修复Excel公式错误”)时质量差。应该优先尝试以下哪个改进方案?', '[{"key":"A","text":"禁用RAG,所有问题依赖大模型回答","correct":false},{"key":"B","text":"扩大RAG检索范围,加入公开技术文档","correct":false},{"key":"C","text":"结合意图识别,公司内部问题才执行检索增强","correct":true},{"key":"D","text":"调整温度参数(Temperature=0.5)平衡回答稳定性","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 444, 'single', '某企业开发了一款面向医疗领域的RAG应用,用户反馈称生成的诊断建议经常不准确,且回答 内容缺乏针对性。经过初步分析,发现检索模块召回的相关文档质量较低,同时生成模块对复杂医 学术语的理解能力不足。作为开发者,你认为以下哪种优化策略最有效?', '[{"key":"A","text":"针对每个用户的反馈逐一调整生成结果,确保满足个性化需求","correct":false},{"key":"B","text":"总结用户反馈中的常见问题,通过多维度评测指标(如准确性、相关性)找到回复质量较低的原 因并进行针对性优化","correct":true},{"key":"C","text":"增加计算资源,提升大模型的推理速度,确保快速生成回答","correct":false},{"key":"D","text":"通过修改prompt模板来引导模型生成更准确的回答","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 445, 'single', '某律所在优化法律问答机器人应用时发现它总是无法准确回答交通法的内容,应优先?', '[{"key":"A","text":"在大模型提示词中强调要准确回答交通法内容","correct":false},{"key":"B","text":"进行query的改写","correct":false},{"key":"C","text":"优化文档切分策略","correct":false},{"key":"D","text":"检查知识库中是否有交通法的知识内容","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 446, 'single', '你开发了一个RAG应用,用户反馈说回复效果不佳。你通过后台日志发现用户的输入有时缺少 信息,如“教研部”、“请假”,你应该优先进行哪方面的优化?', '[{"key":"A","text":"更换检索速度更快的向量数据库","correct":false},{"key":"B","text":"结合历史常见问题,使用大模型对query进行改写","correct":true},{"key":"C","text":"调整大模型的top_p参数","correct":false},{"key":"D","text":"优化文档切分策略","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 447, 'single', 'RAG未检索到相关信息,但模型仍编造回答。下列哪种做法有助于减少这种幻觉?', '[{"key":"A","text":"把所有文档一次性放进模型上下文","correct":false},{"key":"B","text":"提示词要求“若无匹配则回答无法解答”","correct":true},{"key":"C","text":"开启高温度让模型由创造","correct":false},{"key":"D","text":"改回旧版本embedding模型","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 448, 'single', '在优化检索效果时,若知识库内容充足但精确率低,以下哪种方法是合理的?', '[{"key":"A","text":"降低相似度阈值","correct":false},{"key":"B","text":"增加知识库文档","correct":false},{"key":"C","text":"加入rerank的步骤","correct":true},{"key":"D","text":"增加查询请求的并发量以加快响应速度","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 449, 'single', '测试时发现,RAG应用的答案中仍包含大量无用细节,导致阅读困难。哪种做法可以最直接地 减少无关细节?', '[{"key":"A","text":"在检索后用ReRank且设置更小的Top N","correct":true},{"key":"B","text":"增加大模型的“max_tokens”","correct":false},{"key":"C","text":"把索引文件放进Redis数据库","correct":false},{"key":"D","text":"强制用户只提简单问题","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 450, 'single', '你开发了一个专用于医疗场景问答的RAG应用,为了找到优化方向,需要对其进行评测。以下 哪个是参与评测必不可少的群体?', '[{"key":"A","text":"算法工程师。只有算法工程师才可以更理解RAG应用的设计过程与细节。","correct":false},{"key":"B","text":"前端工程师。只有前端工程师更理解用户的交互逻辑,是最懂用户需要的群体。","correct":false},{"key":"C","text":"数据工程师。数据工程师对数据质量、数据管道和检索系统的底层逻辑有深刻理解","correct":false},{"key":"D","text":"医疗专家。医疗专家具备领域专业知识,能够从临床实践和医学指南的角度验证RAG生成答案的 准确性、安全性和实用性。","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 451, 'single', '在优化检索效果时,若知识库内容充足但召回率低,以下哪种方法是合理的?', '[{"key":"A","text":"更换embedding模型","correct":true},{"key":"B","text":"增加知识库文档","correct":false},{"key":"C","text":"提高相似度阈值","correct":false},{"key":"D","text":"增加查询请求的并发量以加快响应速度","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 452, 'single', '向量检索召回了10条切片,但部分切片与问题相关度很低,干扰了大模型答案。哪种方式能更 好地过滤掉低相关度切片?', '[{"key":"A","text":"使用高温度的模型进行生成","correct":false},{"key":"B","text":"在大模型回答后再次让用户手动删除","correct":false},{"key":"C","text":"结合文本重排序模型(ReRank)并只保留Top N","correct":true},{"key":"D","text":"简单把生成结果截断","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 453, 'single', '在qwen2.5-1.5b模型微调时,训练损失快速震荡甚至开始上升,说明模型当前处于?', '[{"key":"A","text":"欠拟合","correct":false},{"key":"B","text":"过拟合","correct":false},{"key":"C","text":"训练失败","correct":true},{"key":"D","text":"训练成功","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 454, 'single', '开发医疗问答系统时发现模型频繁产生“幻觉”,应优先采取哪种优化组合?', '[{"key":"A","text":"降低LoRA秩值+增大学习率","correct":false},{"key":"B","text":"增加训练epoch+提高相似度阈值","correct":false},{"key":"C","text":"RAG增强知识库+LoRA微调领域数据","correct":true},{"key":"D","text":"更换全参数+减少batch_size","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 455, 'single', '为什么我们要在微调中使用早停法?', '[{"key":"A","text":"微调轮次过少可能导致模型欠拟合","correct":false},{"key":"B","text":"微调学习率太小导致模型参数更新太慢","correct":false},{"key":"C","text":"因为模型微调容易出现过拟合现象","correct":true},{"key":"D","text":"因为eval_step设计太大导致过拟合","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 456, 'single', '在qwen2.5-1.5b模型微调时,训练损失和验证损失在同时快速下降,以下说法正确的是?', '[{"key":"A","text":"说明训练策略有效,应继续训练","correct":true},{"key":"B","text":"说明模型开始过拟合,需立即停止","correct":false},{"key":"C","text":"说明模型已收敛,可停止训练","correct":false},{"key":"D","text":"说明学习率设置过高,需调小","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 457, 'single', '梯度下降算法中,如果学习率设置过大可能导致:', '[{"key":"A","text":"在最优解附近震荡","correct":true},{"key":"B","text":"参数更新幅度不足","correct":false},{"key":"C","text":"收敛速度过慢","correct":false},{"key":"D","text":"需要更多迭代次数才能收敛","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 458, 'single', '以下哪项是流式输出的主要优势?', '[{"key":"A","text":"减少服务器计算资源消耗","correct":false},{"key":"B","text":"提升用户感知的响应速度","correct":true},{"key":"C","text":"降低模型推理错误率","correct":false},{"key":"D","text":"避免使用负载均衡","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 459, 'single', '你在开发一个内部IT系统,希望能够自动处理员工的请求:“我的投影仪故障了,请安排维修并 通知下午会议改线上”。以下哪种技术方案有效,且能尽量减少人力投入?', '[{"key":"A","text":"通过大模型判断接单人,自动将任务指派给接单人,通知其创建维修工单并调整会议。","correct":false},{"key":"B","text":"识别请求中的关键字(如“投影仪故障”“会议改线上”),匹配规则系统后调用API完成任务。","correct":false},{"key":"C","text":"通过提示词引导大模型拆解任务为多步骤,然后自动调用维修系统和会议系统API完成操作。","correct":true},{"key":"D","text":"通过提示词引导大模型直接生成维修工单和会议调整结果,无需调用现有系统。","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 460, 'single', '在开发智能餐厅点餐助手时,测试发现用户语音下单(如“来一份宫保鸡丁,数量两份”)时系统 生成错误的调用参数,导致订单出错。经排查,原因在于“下单工具”描述中未明确规定输入参数(如 “菜品名称”和“数量”)的类型、属性及必选项。请问哪项改进最能提高调用参数的准确', '[{"key":"A","text":"在工具描述中详细定义parameters字段,明确说明相关参数的类型、属性描述及必选要求","correct":true},{"key":"B","text":"在工具描述中增加更多辅助说明,如功能介绍和使用场景,增强工具的吸引力","correct":false},{"key":"C","text":"修改工具返回数据格式,使其自动生成标准订单编号","correct":false},{"key":"D","text":"增加调用限制策略,防止同一订单被多次生成","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 461, 'single', '某大学为学生提供一款问答机器人,能回答课程安排和考试时间。学校想新增“自助预定自习室 功能,需要查询并预定教室资源。要使这个功能能与现有问答无缝集成,合适的做法是什么?', '[{"key":"A","text":"在Prompt中写死可预约教室列表","correct":false},{"key":"B","text":"使用一个专门的Agent调用内部预定API","correct":true},{"key":"C","text":"仅通过提示让模型推测当前可用教室","correct":false},{"key":"D","text":"在模型系统消息中提供大量备用数据","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 462, 'single', '你需要借助大模型为小学生写一篇关于“保护环境”的科普短文,但输出的内容过于学术化(如频 繁使用“碳达峰”“生物降解”等术语)。以下哪个提示词优化方向最能直接解决该问题?', '[{"key":"A","text":"补充任务目标:要求文章包含“垃圾分类对社区的影响”案例","correct":false},{"key":"B","text":"扩展上下文:添加背景“当前城市垃圾填埋占比超过60%”","correct":false},{"key":"C","text":"定义角色与受众:以“小学科学老师”身份,用比喻和故事向“6-12岁学生”讲解","correct":true},{"key":"D","text":"提供样例:附上一篇《如何节约用水》的短文(语言平实,包含互动问答)","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 463, 'single', '你希望大模型客服在处理模糊请求时(如用户说“我想订票”),能主动追问必要信息(如时间、 地点)。以下哪种提示词设计最有效?', '[{"key":"A","text":"你是一个细心的订票客服人员。注意每次回复后必须追加一个问题,例如请问需要补充什么信 息?","correct":false},{"key":"B","text":"你是一个订票客服人员。对于订票问题,如果信息不完整,应该向用户提问,直到获取了完整的 出发地、目的地、时间信息。如果是其他票务问题,则正常回答。","correct":true},{"key":"C","text":"你是一个订票客服人员。对于订票问题,如果信息不完整,请向用户主动询问订票相关信息。如 果是其他票务问题,则正常回答。","correct":false},{"key":"D","text":"你是一个订票客服人员。请根据用户提供的信息来回答问题或进行订票。","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 464, 'single', '在ModelScope-Agent中,如何实现对多轮对话中工具参数的有效提取?', '[{"key":"A","text":"静态定义每种工具所需参数,不允许动态调整","correct":false},{"key":"B","text":"利用自然语言理解技术动态分析对话内容,识别并提取参数","correct":true},{"key":"C","text":"仅依赖用户明确指示参数位置,无法自动提取","correct":false},{"key":"D","text":"所有工具调用均预先配置好固定参数,不支持多轮交互调整","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 465, 'single', '多Agent系统通过模拟或利用多个交互的智能体(Agents)来解决复杂问题,具有分布性、适应 性和动态性。以下哪个场景适合采用多Agent系统比单Agent系统效率更高?', '[{"key":"A","text":"简单的垃圾分类机器人,仅需识别并分拣几种固定类型的垃圾","correct":false},{"key":"B","text":"单一目标的军事侦察任务,如无人机监控","correct":false},{"key":"C","text":"大型物流仓库的自动化管理,需要同时调度上千台机器人","correct":true},{"key":"D","text":"个人电脑的资源管理与分配","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 466, 'single', 'ModelScope-Agent的核心优势之一是其高度的可定制性,这主要得益于其', '[{"key":"A","text":"强大的预训练模型阵容,直接提供最优性能无需调整","correct":false},{"key":"B","text":"简化的Agent实现流程,允许用户仅通过指定角色描述等基本信息即可快速搭建应用","correct":true},{"key":"C","text":"限制性的接口设计,确保了所有组件的严格一致性","correct":false},{"key":"D","text":"集成了固定的工具集,减少了用户选择的复杂度","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 467, 'single', '在训练大模型时,为防止信息泄露,可以采取的有效措施是?', '[{"key":"A","text":"数据混杂处理","correct":false},{"key":"B","text":"数据匿名化处理","correct":true},{"key":"C","text":"使用虚拟数据","correct":false},{"key":"D","text":"数据压缩处理","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 468, 'single', '在设计LLM提示词时使用少样本提示,以下哪项不是提高模型性能的建议?', '[{"key":"A","text":"精选代表性样本","correct":false},{"key":"B","text":"保持提示结构一致性","correct":false},{"key":"C","text":"依赖于模型的归纳能力","correct":true},{"key":"D","text":"避免提供过多的示例","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 469, 'single', '在使用大模型API处理调查问卷时,以下哪个步骤不是必要的?', '[{"key":"A","text":"将问卷数据预处理为适合模型输入的格式","correct":false},{"key":"B","text":"通过代码调用大模型API","correct":false},{"key":"C","text":"手动检查每一份问卷的每一个答案","correct":true},{"key":"D","text":"收集大模型处理后的输出并分析结果","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 470, 'single', '在下列应用场景中,哪一个最不适合采用单Agent模式进行处理?', '[{"key":"A","text":"自动驾驶汽车的路径规划与决策","correct":false},{"key":"B","text":"智能家居系统中,控制单个房间的温度与光线","correct":false},{"key":"C","text":"复杂工业生产线上,监控并优化整体生产流程","correct":true},{"key":"D","text":"个人智能助理,管理日程安排与邮件回复","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 471, 'single', '在问题处理策略中,通过将复杂问题拆解为更小、更易管理的部分来改善理解的是哪个方法?', '[{"key":"A","text":"RAG-Fusion问题过滤融合","correct":false},{"key":"B","text":"Multi-Query多路召回","correct":false},{"key":"C","text":"Sentence Sliding句子滑窗","correct":false},{"key":"D","text":"Decomposition问题分解","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 472, 'single', '为了确保与通义千问大模型的交互更加个性化和连续性,下列哪项策略最不推荐?', '[{"key":"A","text":"在每次请求时都提供完整的对话历史","correct":false},{"key":"B","text":"利用上下文管理机制,只保留最近的几轮对话","correct":false},{"key":"C","text":"每次发送新问题时,都将前一次的问答结果清空","correct":true},{"key":"D","text":"设计算法自动摘要长对话,仅传入关键信息点以节省资源","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 473, 'single', '在AI模型的训练过程中,哪一阶段主要旨在通过模拟人类的评价机制,调整模型输出以更贴近 人类偏好和道德标准?', '[{"key":"A","text":"预训练阶段","correct":false},{"key":"B","text":"监督微调阶段","correct":false},{"key":"C","text":"应用部署阶段","correct":false},{"key":"D","text":"基于人类反馈的强化学习(RLHF)阶段","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 474, 'single', '为了加强大语言模型生成内容的信任机制,哪项措施最具有效果?', '[{"key":"A","text":"提高模型参数","correct":false},{"key":"B","text":"增加训练轮数","correct":false},{"key":"C","text":"添加AIGC声明","correct":true},{"key":"D","text":"优化用户界面","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 475, 'single', '某团队需要翻译一份文档,其中包含30条机构内部术语的英文缩写,为了确保翻译的高准确 性,以下哪种方案能解决这一问题?', '[{"key":"A","text":"在提示词中提供30条对应术语缩写与翻译示例","correct":true},{"key":"B","text":"提供前5条翻译示例,要求模型类推理剩余条目","correct":false},{"key":"C","text":"直接让大模型翻译,大模型能够完成这类任务","correct":false},{"key":"D","text":"使用支持联网搜索的大模型API完成此任务","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 476, 'single', '你为某大型企业开发内部问答机器人时,员工A查询“法务接口人”时,机器人总是返回其他部门 的法务接口人信息。以下哪种方案优化该问题最有效?', '[{"key":"A","text":"增加召回片段数量","correct":false},{"key":"B","text":"减少召回片段数量","correct":false},{"key":"C","text":"结合读取的员工部门信息,对query进行改写","correct":true},{"key":"D","text":"对用户query重复检索3次后返回结果","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 477, 'single', '在大语言模型微调的数据准备阶段,哪个操作是为了将文本拆分成单词或词汇单元?', '[{"key":"A","text":"文本翻译","correct":false},{"key":"B","text":"数据去重","correct":false},{"key":"C","text":"分词(Tokenization)","correct":true},{"key":"D","text":"文本摘要","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 478, 'single', '你准备了一批txt格式的公司制度文档,准备将其用于RAG,若要让RAG后续能快速进行相似度 检索,下列哪项是必需的?', '[{"key":"A","text":"手动把txt文件改为JSON格式","correct":false},{"key":"B","text":"对文本进行嵌入(embedding)并将向量存进向量数据库","correct":true},{"key":"C","text":"先对这些txt文件进行加密存储","correct":false},{"key":"D","text":"在检索时把txt文件原样拼给大模型","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 479, 'single', '你想让RAG应用同时支持多种类型的信息查询,有些问“人名信息”,有些问“技术细节”。哪种 “提示词模板”策略更适合?', '[{"key":"A","text":"对所有疑问一概使用相同的通用模板,不区分问题类型","correct":false},{"key":"B","text":"先把所有问题都改成“人事类”,让技术类问题也以人事视角回答","correct":false},{"key":"C","text":"让用户在输入问题时手动指定要用哪种模板","correct":false},{"key":"D","text":"根据问题类型(人事类/技术类)自动选择对应模板","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 480, 'single', '为缩短响应时延,你想在索引前减少切片数量,每个切片包含2-3页内容。结果发现,回答容易 混进无关信息。导致无关信息的根本原因是什么?', '[{"key":"A","text":"文档内没有标题","correct":false},{"key":"B","text":"切片过大,且主题混杂","correct":true},{"key":"C","text":"切片过短,信息量不足","correct":false},{"key":"D","text":"大模型出现故障","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 481, 'single', '你正在开发一款面向客户的智能客服助手,主要功能包括产品咨询、订单查询和售后服务支 持。在初步开发阶段,应该优先针对哪方面进行评测?', '[{"key":"A","text":"大模型对用户的意图理解准确率","correct":true},{"key":"B","text":"客户提问响应的时间","correct":false},{"key":"C","text":"系统对高峰期并发请求的处理能力","correct":false},{"key":"D","text":"界面交互设计的友好程度","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 482, 'single', '以下哪段代码设置了模型训练过程中的学习率?', '[{"key":"A","text":"optimizer = torch.optim.Adam(model.parameters(), lr=learning_rate)","correct":true},{"key":"B","text":"criterion = nn.CrossEntropyLoss()","correct":false},{"key":"C","text":"scheduler = torch.optim.lr_scheduler.StepLR(optimizer, step_size=100, Gamma=0.1)","correct":false},{"key":"D","text":"learning_rate = 0.001","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 483, 'single', '在qwen2.5-1.5b微调训练时,训练损失、验证损失都收敛到较低水平,不再明显波动变化,你应 该?', '[{"key":"A","text":"模型开始过拟合,应终止训练","correct":false},{"key":"B","text":"模型处于欠拟合状态,需要继续训练","correct":false},{"key":"C","text":"训练失败,重新调整训练策略","correct":false},{"key":"D","text":"训练成功,停止训练并进一步评估其效果","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 484, 'single', '在使用AssistantAPI时,如何验证API请求是否成功?', '[{"key":"A","text":"if response.status_code == HTTPStatus.CREATED;","correct":false},{"key":"B","text":"if response.status_code == HTTPStatus.BAD_REQUEST;","correct":false},{"key":"C","text":"if response.status_code == HTTPStatus.OK;","correct":true},{"key":"D","text":"if response.status_code == HTTPStatus.NOT_FOUND;","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 485, 'single', '你维护了一个开发者社区的大模型问答助手,但你发现有人通过上传一些恶意的文章,诱导大 模型生成恶意代码。从长期防护角度,最根本的解决措施是?', '[{"key":"A","text":"输出阶段调用代码静态分析工具","correct":false},{"key":"B","text":"在知识库上传阶段扫描文档安全性","correct":true},{"key":"C","text":"限制模型生成可执行代码","correct":false},{"key":"D","text":"为知识库文档添加数字签名","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 486, 'single', '用户只输入了“张伟部门”这样非常简短的关键词,导致最后给出的答案不够完整,在这种情况 下,若想自动补全或扩充用户的查询意图,以下哪种策略最合适?', '[{"key":"A","text":"增加embedding维度","correct":false},{"key":"B","text":"多步查询(MultiStepQuery)","correct":false},{"key":"C","text":"使用HyDE生成假想文档","correct":false},{"key":"D","text":"问题改写(QuestionRewriting)","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 487, 'single', '本地上传知识库数据时,最大支持单文档大小为?', '[{"key":"A","text":"10 MB","correct":false},{"key":"B","text":"500 MB","correct":false},{"key":"C","text":"100 MB","correct":true},{"key":"D","text":"200 MB","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 488, 'single', '你发现RAG应用召回的切片内容虽然和问题相关,但并不包含真实答案。最优先的排查和改进 方向是什么?', '[{"key":"A","text":"检查Embedding模型的类型及版本","correct":true},{"key":"B","text":"尝试调低top_k,减少召回范围","correct":false},{"key":"C","text":"优先在弱关联层隐藏检索结果,只呈现大模型的最终回答","correct":false},{"key":"D","text":"为每一条切片附详细的前置叙述,希望大模型自动补齐缺失内容","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 489, 'single', '在大语言模型微调的训练循环中,哪个步骤负责计算模型输出与真实标签之间的差异?', '[{"key":"A","text":"梯度更新","correct":false},{"key":"B","text":"参数初始化","correct":false},{"key":"C","text":"反向传播","correct":false},{"key":"D","text":"正向传播","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 490, 'single', '如果answer correctness指标得分较低,而context recall和context precision得分较高,以下哪种优化 措施是可行的?', '[{"key":"A","text":"优化prompt","correct":true},{"key":"B","text":"增加模型的训练数据","correct":false},{"key":"C","text":"减少模型的推理时间","correct":false},{"key":"D","text":"换用性能更好的大模型","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 491, 'single', '以下哪个代码片段能够正确遍历feedback_list并打印每个问题的意图?feedback_list的格式为 [(1,"问题1"),(2,"问题2"),...]', '[{"key":"A","text":"for query in feedback_list: intent = classify_intent(query) print(f\\"Intent: {intent}\\")","correct":false},{"key":"B","text":"for query in feedback_list: intent = classify_intent(query[1]) print(f\\"Intent: {intent}\\")","correct":true},{"key":"C","text":"for item in feedback_list: id = item[0] intent = classify_intent(item[0]) print(f\\"ID: {id}, Intent: {intent}\\")","correct":false},{"key":"D","text":"for i in range(len(feedback_list)): intent = classify_intent(feedback_list[i]) print(f\\"Intent: {intent}\\")","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 492, 'single', '以下哪种方法最适合用于明确指定大模型输出的格式和类型?', '[{"key":"A","text":"仅使用上下文(Context)","correct":false},{"key":"B","text":"仅使用角色(Role)","correct":false},{"key":"C","text":"仅使用任务目标(Object)","correct":false},{"key":"D","text":"结合输出格式(OutputFormat)和样例(Sample)","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 493, 'single', '在提示词构建中,哪个要素用于指定大模型的回应风格或语气?', '[{"key":"A","text":"输出格式","correct":false},{"key":"B","text":"样例","correct":false},{"key":"C","text":"任务目标","correct":false},{"key":"D","text":"上下文","correct":false},{"key":"E","text":"输入数据","correct":false},{"key":"F","text":"角色","correct":true}]', 'F') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 494, 'single', '一家影视制作公司正在开发AI视频生成系统,利用生成式模型自动创作短视频。下哪些措施可 以帮助降低知识产权风险?', '[{"key":"A","text":"使用大语言模型生成剧本初稿,供编剧团队进一步修改和完善。","correct":true},{"key":"B","text":"利用图像理解技术对演员的面部表情进行捕捉,并将其映射到虚拟主播角色上,实现实时互动表 演。","correct":false},{"key":"C","text":"开发一个推荐系统,为观众推荐他们可能感兴趣的直播内容。","correct":false},{"key":"D","text":"使用语音合成技术生成个性化配音,替代人工配音演员完成所有影视作品的配音工作。","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 495, 'single', '以下哪个代码片段能够正确处理classify_intent函数可能抛出的异常,并打印错误信息?', '[{"key":"A","text":"for id, query in feedback_list: try: intent = classify_intent(query) print(f\\"ID: {id}, Intent: {intent}\\") finally: print(\\"Finished processing query.\\")","correct":false},{"key":"B","text":"for id, query in feedback_list: intent = classify_intent(query) print(f\\"ID: {id}, Intent: {intent}\\") except Exception as e: print(f\\"Error: {e}\\")","correct":false},{"key":"C","text":"for id, query in feedback_list: try: intent = classify_intent(query) print(f\\"ID: {id}, Intent: {intent}\\") except Exception as e: print(f\\"Error processing query {id}: {e}\\")","correct":true},{"key":"D","text":"for id, query in feedback_list: if classify_intent(query): intent = classify_intent(query) print(f\\"ID: {id}, Intent: {intent}\\") else: print(\\"Error processing query.\\")","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 496, 'single', '你使用Qwen-Max生成了课程内容,现在需要将其转换为Marp格式的Markdown。以下哪个Qwen- Max的提示词最有效', '[{"key":"A","text":"把这些内容转换成Markdown","correct":false},{"key":"B","text":"用Markdown写个幻灯片","correct":false},{"key":"C","text":"将以下内容转换为适合Marp幻灯片演示的Markdown格式,并包含标题、列表和代码块等元素。","correct":true},{"key":"D","text":"帮我转换成PPT","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 497, 'single', '以下哪种文档切片方法能够更好地保持句子的完整性?', '[{"key":"A","text":"基于语义的切片,通过markdown文档结构进行","correct":false},{"key":"B","text":"基于句子的切片","correct":false},{"key":"C","text":"随机切片","correct":false},{"key":"D","text":"基于语义的切片,通过嵌入模型计算语义断点","correct":true},{"key":"E","text":"基于字符切片","correct":false},{"key":"F","text":"基于固定token长度切片","correct":false}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 498, 'single', '以下哪种情况最适合在“输出的内容安全合规检查”中处理?', '[{"key":"A","text":"用户上传的图片格式不符合要求。","correct":false},{"key":"B","text":"机器人的回答包含公司内部代码片段。","correct":true},{"key":"C","text":"用户输入的问题包含辱骂性词汇。","correct":false},{"key":"D","text":"机器人无法理解用户的问题。","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 499, 'single', '某律所希望开发一个基于RAG的合同审阅系统,已通过POC(Proof of Concept,是针对客户具 体应用的验证性测试)验证了系统对于一些常见问题的准确性和效率。下一步应该优先做什么?', '[{"key":"A","text":"降低相似度阈值,增加召回文本个数","correct":false},{"key":"B","text":"对前端界面进行优化","correct":false},{"key":"C","text":"针对POC测试中的问题进行反复优化","correct":false},{"key":"D","text":"请法律专家参与构建评测集","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 500, 'single', '你作为一名医学检验研究员,需翻译存在大量“NSC”(可能指“神经干细胞”或“非小细胞癌”)缩 写的文献。应如何设计提示词以消除歧义?', '[{"key":"A","text":"分配角色:“作为肿瘤科医生,严格匹配癌症相关术语”","correct":false},{"key":"B","text":"要求输出格式:“所有缩写后需用括号标注全称”","correct":false},{"key":"C","text":"提供少量上下文关联示例:“在‘干细胞培养’段落中,NSC→神经干细胞,在‘肺癌病理’段落中, NSC→非小细胞癌”","correct":true},{"key":"D","text":"直接提问:“请优先将NSC翻译为神经干细胞”","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 501, 'single', '假设你需要统计每种意图出现的次数,以下哪个代码片段实现了这个功能?', '[{"key":"A","text":"intent_counts = {} for i in range(len(feedback_list)): intent = classify_intent(feedback_list[i][0]) intent_counts[intent] += 1 print(intent_counts)","correct":false},{"key":"B","text":"intent_counts = {} for id, query in feedback_list: intent = classify_intent(query) intent_counts[intent] = intent_counts.get(intent, 0) + 1 print(intent_counts)","correct":true},{"key":"C","text":"intent_counts = {} for id, query in feedback_list: intent = classify_intent(id) if intent in intent_counts: intent_counts[intent] = 1 else: intent_counts[intent] = 0 print(intent_counts)","correct":false},{"key":"D","text":"intent_counts = [] for query in feedback_list: intent = classify_intent(query[1]) intent_counts.append(intent) print(intent_counts)","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 502, 'single', '用户只说“想了解工作职责”,但没说明具体岗位。RAG检索到多个岗位职责信息都可能匹配。 最合理的做法是?', '[{"key":"A","text":"使用HyDE生成假想文档","correct":false},{"key":"B","text":"将问题改写为多步查询","correct":false},{"key":"C","text":"提示词中设定用户提供信息不足时,向用户反问需要哪个岗位","correct":true},{"key":"D","text":"返回所有岗位的职责","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 503, 'single', '在进行RAG应用评测时,应该如何获取测试集中的正确答案(ground_truth)?', '[{"key":"A","text":"由性能最强的大模型进行编写","correct":false},{"key":"B","text":"由该领域的专家进行编写","correct":true},{"key":"C","text":"由数据工程师进行编写","correct":false},{"key":"D","text":"由算法工程师进行编写","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 504, 'single', '你想针对一篇两栏性的论文对RAG应用进行提问,可回答效果不好,你发现后台日志中召回的 文本段出现一句话没有说完就被另一句话截断的现象,问题可能出在哪里了?', '[{"key":"A","text":"embedding模型在检索过程中将解析好的文本打乱顺序","correct":false},{"key":"B","text":"rerank模型对字符进行重排序导致语义不通","correct":false},{"key":"C","text":"文档解析模块未正确处理分栏式PDF的版面结构,导致文本流顺序错乱","correct":true},{"key":"D","text":"大模型无法准确还原论文的原本内容","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 505, 'single', '分词(Tokenization)的主要作用是什么?', '[{"key":"A","text":"将文本转换为固定长度的向量","correct":false},{"key":"B","text":"将输入文本分割成单词、子词或字符等更小的语义单元","correct":true},{"key":"C","text":"提取文本的语义特征以计算情感值","correct":false},{"key":"D","text":"为模型提供上下文信息","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 506, 'single', 'def set_default_model(): EMBED_MODEL = DashScopeEmbedding( model_name = DashScopeTextEmbeddingsModels.TEXT_EMBEDDING_V2, type_name = DashScopeTextEmbeddingType.TEXT_TYPE_DOCUMENT, ) LLM_MODEL = DashScope(model_name="qwen-plus") Settings.embed_model = EMBED_MODEL Settings.llm = LLM_MODEL', '[{"key":"A","text":"使得llm可以流式输出","correct":false},{"key":"B","text":"使得embedding模型可以参与llm的生成过程中","correct":false},{"key":"C","text":"使得有关LlamaIndex的后续步骤中无需再次指定llm与embed_model","correct":true},{"key":"D","text":"定义了EMBED_MODEL与LLM_MODEL","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 507, 'single', '你正在基于某视觉理解大模型开发一个门店巡检系统(检查垃圾桶是否盖好、操作是否整洁、 水池是否洗干净等),但发现用大模型同时识别判断场景、给出判断结果的效果总是不好,以下哪 种改进方案能更低成本地解决这一问题?', '[{"key":"A","text":"增加更多的监控摄像头,给大模型更多的输入信息","correct":false},{"key":"B","text":"收集一批高质量的监控画面数据,面向巡检任务微调大模型","correct":false},{"key":"C","text":"改进当前的数据输入,减少监控画面的分辨率,避免引入干扰信息","correct":false},{"key":"D","text":"用物体分割小模型圈出识别区域,然后抠图输入给大模型检测状态","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 508, 'single', '你在需要构建公文智能处理系统,用户上传PDF文件,系统需自动识别文本内容并生成摘要。以 下哪种架构设计比较合理?', '[{"key":"A","text":"前端上传文件至FC,FC调用OCR服务提取文本并存入OSS,再由百炼模型提供结果链接","correct":false},{"key":"B","text":"前端直接调用百炼模型解析PDF,模型将原始文件和分析结果存入OSS,通过访问链接提供结果的 访问","correct":false},{"key":"C","text":"OSS仅存储最终摘要文件,原始PDF通过FC直传至百炼模型服务进行全流程处理","correct":false},{"key":"D","text":"前端上传PDF至OSS,触发FC解析文本,FC调用百炼模型生成摘要,结果存入OSS并前端下载","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 509, 'single', '以下哪种情况更适合使用代码解释器插件而不是直接使用大模型?', '[{"key":"A","text":"将一组文档按主题分类","correct":false},{"key":"B","text":"分析一段文本的情感","correct":false},{"key":"C","text":"从用户评论中提取关键信息","correct":false},{"key":"D","text":"计算两组数据之间的皮尔逊相关系数","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 510, 'single', '某大模型客服系统被攻击者通过提示词注入获取知识库元数据,以下哪个措施能更有效防范这 一问题?', '[{"key":"A","text":"改进提示词,确保模型在回答问题时避免回答列表形式的内容","correct":false},{"key":"B","text":"改进提示词,让大模型避免回答这类问题","correct":false},{"key":"C","text":"改进提示词,并且在输入阶段过滤无数据“关键词”","correct":false},{"key":"D","text":"在知识库检索前严格限制应用的数据访问权限,避免泄露公开信息","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 511, 'single', '以下哪段代码实现了模型训练过程中的损失函数计算?', '[{"key":"A","text":"for epoch in range(num_epochs):","correct":false},{"key":"B","text":"optimizer.zero_grad()","correct":false},{"key":"C","text":"with torch.no_grad(): correct += (predicted == labels).sum().item()","correct":false},{"key":"D","text":"loss = F.nll_loss(output, target, reduction=''sum'')","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 512, 'single', '实现早停法(early stopping)时,通常在哪种情况下停止训练?', '[{"key":"A","text":"验证集损失连续n轮不再下降","correct":true},{"key":"B","text":"验证集准确率达到100%","correct":false},{"key":"C","text":"训练集损失达到最小值","correct":false},{"key":"D","text":"训练集准确率连续n轮上升","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 513, 'single', '通过LlamaIndex创建RAG应用时,rerank的作用是?', '[{"key":"A","text":"替换embedding model","correct":false},{"key":"B","text":"设置召回文本段个数","correct":false},{"key":"C","text":"根据用户的输入去向量数据库进行检索","correct":false},{"key":"D","text":"对向量数据库的检索结果进行重新排序","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 514, 'single', '构建微调数据集时最重要的原则是?', '[{"key":"A","text":"包含丰富的问题场景","correct":true},{"key":"B","text":"数据尽量由大模型生成","correct":false},{"key":"C","text":"数据量越大越好","correct":false},{"key":"D","text":"使用单一的问题模板","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 515, 'single', '同一份文档,使用百炼上的text-embedding-v2与text-embedding-v3进行索引。实际测试发现v3的 检索效果更佳。哪项最合理解释了这种现象?', '[{"key":"A","text":"v3模型版本号更大A","correct":false},{"key":"B","text":"v2模型只支持英文语料","correct":false},{"key":"C","text":"v3版本对相似度表示更精细","correct":true},{"key":"D","text":"v3无法适应长文本","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 516, 'single', '在检索阶段,一般是如何找到知识库中最相关的文本段的?', '[{"key":"A","text":"通过embedding模型比较用户输入与各文本段的语义相似度","correct":true},{"key":"B","text":"找出过往历史对话经常涉及的文本段,每次回复时都输入给大模型","correct":false},{"key":"C","text":"比较用户输入与各文本段的重合字数","correct":false},{"key":"D","text":"由大模型来判断哪个文本段最相关","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 517, 'single', '以下代码片段中,哪一个是用于计算模型预测结果(前向传播)的?', '[{"key":"A","text":"optimizer.zero_grad()","correct":false},{"key":"B","text":"outputs = model(inputs)","correct":true},{"key":"C","text":"loss = criterion(outputs, labels)","correct":false},{"key":"D","text":"optimizer.step()","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 518, 'single', '在qwen2.5-1.5b模型训练时,当训练损失持续下降但验证损失开始上升时,说明模型处于什么状 态?', '[{"key":"A","text":"欠拟合","correct":false},{"key":"B","text":"过拟合","correct":true},{"key":"C","text":"训练失败","correct":false},{"key":"D","text":"训练成功","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 519, 'single', '关于输入数据的描述,以下哪项是正确的?', '[{"key":"A","text":"输入数据应当明确具体含义及其用途","correct":true},{"key":"B","text":"输入数据不影响模型输出格式","correct":false},{"key":"C","text":"输入数据是可选的","correct":false},{"key":"D","text":"输入数据仅用于生成样例","correct":false},{"key":"E","text":"输入数据无需说明","correct":false},{"key":"F","text":"输入数据可以通过模糊的引导词来定义其作用","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 520, 'single', '使用模型检查点(checkpointing)保存模型时,一般会保存哪种情况下的模型?', '[{"key":"A","text":"验证集性能最好的模型","correct":true},{"key":"B","text":"训练结束时的模型","correct":false},{"key":"C","text":"每次迭代后的模型","correct":false},{"key":"D","text":"训练初期的模型","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 521, 'single', '以下哪个用户查询语句无法有效地指导大模型进行文本摘要?', '[{"key":"A","text":"请总结以下文章的主要内容:...","correct":false},{"key":"B","text":"提取以下文本的关键词:...","correct":false},{"key":"C","text":"请翻译以下文章:...","correct":true},{"key":"D","text":"将以下文章压缩到100字以内:...","correct":false},{"key":"E","text":"用一句话概括以下文字:","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 522, 'single', '请问这个函数的主要作用是 def set_default_model(): EMBED_MODEL = DashScopeEmbedding(model_name=DashScopeTextEmbeddingModels.TEXT_EMBEDDING_V2, text_type=DashScopeTextEmbeddingType.TEXT_TYPE_DOCUMENT) LLM_MODEL = DashScope(model_name="qwen-plus") Settings.embed_model = EMBED_MODEL Settings.Ilm = LLM_MODEL', '[{"key":"A","text":"定义了EMBED_MODEL与LLM_MODEL","correct":false},{"key":"B","text":"使得embedding模型可以参与LLM的生成过程中","correct":false},{"key":"C","text":"使得LLM可以流式输出","correct":false},{"key":"D","text":"使得有关LlamaIndex的后续步骤中无需再次指定LLM与embed_model","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 523, 'single', '你需要大模型输出“公式化、格式固定”的答案,不希望因随机因素导致格式或内容风格频繁变 化。为此此场景下控制大模型的输出“一致性”,以下哪种做法更合适?', '[{"key":"A","text":"调高temperature并增大presence_penalty","correct":false},{"key":"B","text":"将temperature调低并设置固定seed","correct":true},{"key":"C","text":"将temperature、top_k调高","correct":false},{"key":"D","text":"将temperature、top_p调高","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 524, 'single', '如果想要自定义langchain的LLM对象,理论上只需要准备以下哪个要素?', '[{"key":"A","text":"一个API Key","correct":false},{"key":"B","text":"一个Model name","correct":false},{"key":"C","text":"一个JSON,直接加载即可","correct":false},{"key":"D","text":"一个输入为字符串,输出为字符串的函数","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 525, 'single', '在RAGAS评分之后,你对其中一些指标有些疑问,你可以查看哪个字段来追溯大模型评分的原 因?', '[{"key":"A","text":"source","correct":false},{"key":"B","text":"reason","correct":true},{"key":"C","text":"json_object","correct":false},{"key":"D","text":"source_node","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 526, 'single', '你开发了一个专用于医疗场景问答的RAG应用,许多用户都反馈说关于疾病症的回答总是得不 到正确答案,你应该首先检查哪一环节?', '[{"key":"A","text":"检查检索环节的embedding模型是否能分辨相似的文本段","correct":true},{"key":"B","text":"检查训练集的内容是否存在于知识集中","correct":false},{"key":"C","text":"检查计算资源是否充足","correct":false},{"key":"D","text":"检查大模型是否能根据知识内容对问题进行正确解答","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 527, 'single', '你想使用Qwen-Max从一段冗长的课程文本中提炼出关键信息,用于创建PPT脚本。以下哪个提 示词最合适?', '[{"key":"A","text":"用更少的字概括这段文字","correct":false},{"key":"B","text":"缩短这段文字","correct":false},{"key":"C","text":"从以下课程文本中提取关键信息,生成一个简洁的PPT脚本大纲,突出重点内容,并控制在5个要 点以内。","correct":true},{"key":"D","text":"把这段文字变成PPT","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 528, 'single', '以下哪种用法不能有效利用system角色提示词?', '[{"key":"A","text":"限制模型的输出行为","correct":false},{"key":"B","text":"设定对话的背景和目标","correct":false},{"key":"C","text":"直接回答用户问题","correct":true},{"key":"D","text":"提供特定领域的知识","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 529, 'single', '用户向基于RAG的智能答疑机器人提交了一张包含敏感信息的图片进行咨询。根据最佳实践, 最早应该在哪个阶段进行内容安全合规检查以阻止敏感信息泄露?', '[{"key":"A","text":"机器人根据用户图片检索时","correct":false},{"key":"B","text":"机器人响应返回答案之后检查","correct":false},{"key":"C","text":"在机器人处理图片之前检查","correct":true},{"key":"D","text":"将答案返回给用户之前检查","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 530, 'single', '如果想要发送“你好,请介绍一下你自己”给大模型,应该修改以下代码的哪一行? messages = [{"role": "user", "content": "你是谁?"}] api_key = os.getenv("DASHSCOPE_API_KEY") base_url = "https://dashscope.aliyuncs.com/compatible-mode/v1" model = "qwen-max"', '[{"key":"A","text":"messages = [{\\"role\\": \\"user\\", \\"content\\": \\"你是谁?\\"}]","correct":true},{"key":"B","text":"api_key = os.getenv(\\"DASHSCOPE_API_KEY\\")","correct":false},{"key":"C","text":"base_url = \\"https://dashscope.aliyuncs.com/compatible-mode/v1\\"","correct":false},{"key":"D","text":"model = \\"qwen-max\\"","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 531, 'single', '下面哪个Python库函数常用于计算F1分数?', '[{"key":"A","text":"sklearn.metrics.recall_score","correct":false},{"key":"B","text":"sklearn.metrics.accuracy_score","correct":false},{"key":"C","text":"sklearn.metrics.f1_score","correct":true},{"key":"D","text":"sklearn.metrics.precision_score","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 532, 'single', '在以下哪个场景中,大模型最能发挥其独特优势?', '[{"key":"A","text":"精确计算过去一年公司财务报表的总利润。","correct":false},{"key":"B","text":"计算两组实验数据的相关系数,以确定变量间的关系强度。","correct":false},{"key":"C","text":"预测下个季度股票市场的具体收盘价格","correct":false},{"key":"D","text":"对用户评论进行情感分析,判断正面评价与负面评价的比例。","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 533, 'single', '在构建微调数据集时,以下哪个方面的考量是错误的?', '[{"key":"A","text":"数据集要根据微调效果持续迭代","correct":false},{"key":"B","text":"要包括任务全场景","correct":false},{"key":"C","text":"测试集内容要包含在训练集中","correct":true},{"key":"D","text":"要确保数据集准确、内容相关","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 534, 'single', '某企业的文档(Markdown格式)中,部门职责常落在多段文字里,检索时想精准定位,哪种切 片策略最能减少“职责信息”被拆散的问题?', '[{"key":"A","text":"Token切片","correct":false},{"key":"B","text":"随机分段","correct":false},{"key":"C","text":"句子切片","correct":false},{"key":"D","text":"Markdown结构化切片","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 535, 'single', '在切片向量化与存储阶段,以下哪种方法用于比较不同Embedding模型的文本相似度?', '[{"key":"A","text":"compare_embeddings 函数","correct":true},{"key":"B","text":"增加模型的训练数据","correct":false},{"key":"C","text":"减少模型的推理时间","correct":false},{"key":"D","text":"增加模型的参数数量","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 536, 'single', '以下哪个代码片段最适合将文本片段转换为向量表示?', '[{"key":"A","text":"from sentence_transformers import SentenceTransformer model = SentenceTransformer(''all- mpnet-base-v2'') def embed_text(text): return model.encode(text)","correct":true},{"key":"B","text":"def embed_text(text): return len(text)","correct":false},{"key":"C","text":"import hashlib def embed_text(text): return hashlib.sha256(text.encode()).hexdigest()","correct":false},{"key":"D","text":"import numpy as np def embed_text(text): return np.random.rand(100)","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 537, 'single', '在一个电商客服RAG系统中,如果过度追求召回率,可能会导致哪些问题?', '[{"key":"A","text":"检索结果数量不足,用户无法获得足够推荐。","correct":false},{"key":"B","text":"检索结果过少,用户找不到相关商品。","correct":false},{"key":"C","text":"检索条件过于严格,用户查询失败率增加。","correct":false},{"key":"D","text":"检索结果包含大量无关商品信息,影响用户体验。","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 538, 'single', '在大语言模型微调训练中,哪一步骤涉及到计算损失函数关于模型参数的梯度?', '[{"key":"A","text":"正向传播","correct":false},{"key":"B","text":"批标准化","correct":false},{"key":"C","text":"优化算法选择","correct":false},{"key":"D","text":"反向传播","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 539, 'single', '相比直接使用大模型的API,使用百炼的AssistantAPI构建Agent的主要优势是什么?', '[{"key":"A","text":"能够绕过一些API调用限制,使得开发出的Agent功能更强大","correct":false},{"key":"B","text":"能够完全控制模型底层训练过程","correct":false},{"key":"C","text":"自带了会话管理和联网搜索等工具,简化Agent开发工作","correct":true},{"key":"D","text":"能够修改一些大模型API不直接提供的参数,使得开发Agent的过程更灵活","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 540, 'single', '小王开发了一个AI音乐创作工具,在用户协议中声明对用户使用该工具创作的音乐作品享有所 有权。这种做法是否合规?', '[{"key":"A","text":"合规,开发者有权决定作品的版权归属","correct":false},{"key":"B","text":"不合规,用户拥有其创作作品的版权,开发者不能随意剥夺","correct":true},{"key":"C","text":"合规,只要在用户协议中明确声明即可","correct":false},{"key":"D","text":"不合规,建议咨询法律专业人士,制定更合理的版权归属方案","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 541, 'single', 'StorageContext.from_defaults(persist_dir=PERSIST_DIR)的作用是什么?', '[{"key":"A","text":"创建一个新的StorageContext对象,并使用默认配置,但指定持久化目录。","correct":true},{"key":"B","text":"将StorageContext对象保存到PERSIST_DIR。","correct":false},{"key":"C","text":"从PERSIST_DIR加载StorageContext对象。","correct":false},{"key":"D","text":"创建一个默认的StorageContext对象,并忽略PERSIST_DIR。","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 542, 'single', '以下哪个向量数据库不适合用于存储和检索文本向量?', '[{"key":"A","text":"Milvus","correct":false},{"key":"B","text":"FAISS","correct":false},{"key":"C","text":"MySQL","correct":true},{"key":"D","text":"Pinecone","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 543, 'single', '你开发了一个用药咨询应用,因图片OCR错误将“药品副作用:轻微头痛”误识别为“严重头痛”, 导致生成误导性回答。以下哪种方案更能系统性减少这类问题?', '[{"key":"A","text":"在识别结果旁添加“可能存在误差”的免责声明","correct":false},{"key":"B","text":"对视觉理解结果添加人工复核,避免图片不清晰导致的识别错误","correct":false},{"key":"C","text":"禁止用户输入图片,要求用户用文字输入药物信息","correct":false},{"key":"D","text":"从图像中提取药物信息后,结合药品知识库校验提取的信息","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 544, 'single', '你想通过语音命令操作网页,例如,用户说“我想煮2杯咖啡”,系统转译语音后,根据用户位置 和互动意图确定位置并点击“下单”按钮。由于UI复杂,哪项技术最适合精准锚点点击目标按钮?', '[{"key":"A","text":"引入安全审核机制,对所有操作进行预先校验,确保操作前先确定UI元素的合法性。","correct":false},{"key":"B","text":"标注页面上的可交互元素,然后结合视觉理解大模型识别并构建应该做出的点击动作。","correct":true},{"key":"C","text":"利用RAG(检索增强生成)技术,动态检索界面说明文档来辅助识别目标按钮。","correct":false},{"key":"D","text":"采用提示词工程技术,通过优化语言描述指导模型从文本中推断出应操作的UI元素。","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 545, 'single', '下面的Python代码执行了哪种文本预处理操作? import re cleaned_text = re.sub(r''\\W+'', '''', text)', '[{"key":"A","text":"词形还原","correct":false},{"key":"B","text":"文本去噪(正则表达式清洗)","correct":true},{"key":"C","text":"文本分类","correct":false},{"key":"D","text":"文本翻译","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 546, 'single', '你计划开发法律咨询AI助手,需平衡专业性与可解释性。以下最佳方案是:', '[{"key":"A","text":"仅输出法律条款原文,用高亮标注相关段落","correct":false},{"key":"B","text":"生成通俗解释后,附加相似案例做对比,并在关键结论处显示法条依据及置信度","correct":true},{"key":"C","text":"用流程图展示法律程序,拒绝提供明确的文字结论以避免责任风险","correct":false},{"key":"D","text":"支持多轮对话形式,但为了直奔主题,要求模型每轮回答不超过20个汉字","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 547, 'single', '在Python中,用于计算精确度(Precision)的公式是什么?', '[{"key":"A","text":"(TP+TN)/(TP+FP+TN+FN)","correct":false},{"key":"B","text":"TP/(TP+FN)","correct":false},{"key":"C","text":"TP/(TP+FP)","correct":true},{"key":"D","text":"TP/(FN+TN)","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 548, 'single', '你需要使用Qwen-Max生成一个关于“Python基础”的课程脚本。以下哪种请求方式最合适?', '[{"key":"A","text":"向Qwen-Max发送一条包含“Python基础课程脚本”的请求,并附加一些示例代码。","correct":false},{"key":"B","text":"向Qwen-Max发送一条详细描述课程目标和内容的请求,例如:“请生成一个Python基础课程脚 本,包含变量、数据类型、运算符、控制流等内容。”","correct":true},{"key":"C","text":"向Qwen-Max发送多条分别包含“Python变量”、“Python数据类型”、“Python运算符”等关键词的请 求。","correct":false},{"key":"D","text":"向Qwen-Max发送一条包含“Python”关键字的请求。","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 549, 'single', '你希望用户在向你的大模型应用提问“我想预约医生”时,能主动追问必要信息(如科室、时 间),以下哪种提示词设计能更好地实现这一效果?', '[{"key":"A","text":"你是一个细心的医疗客服。注意每次回复后必须追加一个问题,例如请问需要补充什么信息?","correct":false},{"key":"B","text":"你是一个医疗客服。对于预约就诊类问题,如果用户未说明就诊科室、预约时间,应向用户追 问,如果是其他咨询,则正常回答。","correct":true},{"key":"C","text":"你是一个医疗客服。如果用户的请求不完整,请追问所有可能缺失的信息(如科室、时间、症状 描述、保险类型等)。","correct":false},{"key":"D","text":"你是一个医疗客服。如果用户的请求不足以完成预约,请主动追问。","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 550, 'single', '在RAGAS的这行代码中,data_samples可能是什么格式? python dataset = Dataset.from_dict(data_samples)', '[{"key":"A","text":"data_samples = {\\"question\\": \\"sample_question\\", \\"answer\\": \\"sample_answer\\", \\"contexts\\": \\"sample_contexts\\"}","correct":false},{"key":"B","text":"data_samples = {\\"question\\": \\"sample_question\\", \\"answer\\": \\"sample_answer\\", [\\"sample_context1\\", \\"sample_context2\\"], \\"ground_truth\\": [\\"sample_ground_truth1\\", \\"sample_ground_truth2\\"]}","correct":false},{"key":"C","text":"data_samples = {\\"question\\": \\"sample_question\\", \\"answer\\": \\"sample_answer\\", [\\"sample_context1\\", \\"sample_context2\\"]}","correct":true},{"key":"D","text":"data_samples = DataFrame(question=\\"sample_question\\", answer=\\"sample_answer\\", contexts=\\"sample_contexts\\")","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 551, 'single', '在文档审阅中,为什么不建议一次输出所有的结果?', '[{"key":"A","text":"只需关注营销表达","correct":false},{"key":"B","text":"大模型可能会漏掉一些错误","correct":false},{"key":"C","text":"内容错误不需要处理","correct":false},{"key":"D","text":"信息量过大,难以理解","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 552, 'single', '你已经开发了可以用于聊天的大模型应用,可以实现多轮对话、流式输出等功能。用户反馈希 望在回答特定领域问题时参考内部知识库,其他情况下不用。你应该怎么满足这个需求?', '[{"key":"A","text":"首先在检索功能中融入多轮对话改写机制,然后加入意图识别功能,判断该轮对话是否需要进 RAG","correct":true},{"key":"B","text":"需要从0到1实现文档加载、内容分割、文本向量化、索引存储等复杂的功能","correct":false},{"key":"C","text":"调整代码,在每一轮对话时检索相关内部知识文档片段,并组装到提示词模板中","correct":false},{"key":"D","text":"要求用户在输入问题之外,还需要输入相关的文本段","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 553, 'single', '你希望用阿里云百炼平台的通义千问大模型生成商品描述,但要求不同用户看到的内容略有差 异,应如何实现?', '[{"key":"A","text":"启用enable_search参数","correct":false},{"key":"B","text":"保持temperature=0.9且不固定seed","correct":true},{"key":"C","text":"设置temperature=0.0","correct":false},{"key":"D","text":"使用完全相同的提示词","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 554, 'single', '以下哪个提示词框架要素用于提供参考案例,帮助大模型理解预期输出?', '[{"key":"A","text":"输入数据(Input Parameters)","correct":false},{"key":"B","text":"样例(Sample)","correct":true},{"key":"C","text":"任务目标(Object)","correct":false},{"key":"D","text":"角色(Role)","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 555, 'single', '以下哪个提示词示例最有效地利用了分隔符来区分不同的要素?', '[{"key":"A","text":"...##任务目标 写一首关于春天的诗 ##受众 儿童 ##输出格式 四行诗","correct":true},{"key":"B","text":"...任务目标是写一首关于春天的诗,受众是儿童,输出格式是四行诗。","correct":false},{"key":"C","text":"...任务目标,写一首关于春天的诗,受众,儿童,输出格式,四行诗","correct":false},{"key":"D","text":"...任务目标写一首关于春天的诗受众儿童输出格式四行诗","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 556, 'single', '某公司推出了一款“大小模型协同”系统,使用小模型处理常规问答、大模型处理复杂推理或文档 分析。系统还采用了多智能体架构,然而系统经常把一些简单FAQ也交给大模型处理,浪费了算力。 为了解决该问题,以下哪种做法最有效?', '[{"key":"A","text":"在Planner Agent中增加任务复杂度判断逻辑,优先调用小模型处理简单FAQ","correct":true},{"key":"B","text":"对小模型进行额外训练,提升其对更多类型问题的处理能力,从而减轻大模型负担","correct":false},{"key":"C","text":"在工具函数描述中添加更多示例,让大模型能更准确区分不同请求的复杂度","correct":false},{"key":"D","text":"为Summary Agent提供更多训练数据,确保最终回答更加全面","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 557, 'single', '你开发了一个专用于医疗场景问答的RAG应用,许多用户都反馈说关于渐冻症的问答总是得不 到正确答案,你应该首先检查哪一环节?', '[{"key":"A","text":"检查检索环节的embedding模型是否能分辨相似的文本段","correct":false},{"key":"B","text":"检查大模型是否能根据知识内容对问进行正确解答","correct":false},{"key":"C","text":"检查渐冻症的内容是否存在于知识库中","correct":true},{"key":"D","text":"检查计算资源是否充足","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 558, 'single', '在一次评审会上,大家针对同一条问答的准确性产生分歧,工程师认为回答和问题语义相似度 高,业务负责人则认为回答中有错误细节。该争议主要反映了什么?', '[{"key":"A","text":"词法分析不完善","correct":false},{"key":"B","text":"纯粹的向量相似度不足以衡量业务正确性","correct":true},{"key":"C","text":"检索速度过慢","correct":false},{"key":"D","text":"大模型对中文支持度不足","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 559, 'single', '假设你正在使用一个大语言模型开发智能客服系统,希望生成的回复尽量简短,以适应短信通 知的长度限制,要求短信语义完整。以下哪种方式更有可能实现这一目标?', '[{"key":"A","text":"通过明确提示词引导,在提示词中写明“请将答案控制在100字以内”。","correct":true},{"key":"B","text":"通过模型微调优化,对模型进行专门训练,使其具备生成短文本的能力。","correct":false},{"key":"C","text":"通过API参数限制,设置max_token=100以约束生成文本的长度。","correct":false},{"key":"D","text":"在后端逻辑中使用正则表达式方法对生成结果进行后处理。","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 560, 'single', '以下代码片段中,temperature参数设置为0.6,其主要作用是什么?', '[{"key":"A","text":"控制模型使用的GPU数量。","correct":false},{"key":"B","text":"控制模型加载的权重数量。","correct":false},{"key":"C","text":"控制模型生成文本的多样性。","correct":true},{"key":"D","text":"控制模型生成文本的长度。","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 561, 'single', '如果你基于网页版的大模型写了以下提示词。(请你生成一份一季度财务报告)。以下哪些建 议是合理的,可以帮助改进这个提示词?', '[{"key":"A","text":"提供公司特有的财务报告格式模板或示例,以确保生成的报告符合格式要求。","correct":false},{"key":"B","text":"提供具体的财务数据和关键指标,以便模型能够准确地填充报告。","correct":false},{"key":"C","text":"指定该报告的期望长度。","correct":false},{"key":"D","text":"以上所有","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 562, 'single', '在创建一个消息(Message)时,需要传递哪个参数来指定线程ID?', '[{"key":"A","text":"thread.id","correct":true},{"key":"B","text":"message.id","correct":false},{"key":"C","text":"content","correct":false},{"key":"D","text":"assistant.id","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 563, 'single', '在模型训练循环中,哪段代码用于更新模型权重(梯度更新)?', '[{"key":"A","text":"loss = criterion(outputs, labels)","correct":false},{"key":"B","text":"optimizer.step()","correct":true},{"key":"C","text":"model.train()","correct":false},{"key":"D","text":"loss.backward()","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 564, 'single', '某企业计划通过阿里云百炼平台构建一个大模型应用,用于处理对实时性要求不高的任务(如 离线招生生成、批量内容摘要提取等)。为了在满足业务需求的同时降低运行成本,以下哪种措施 可以最有效地优化成本?', '[{"key":"A","text":"引入流式输出,降低模型推理成本","correct":false},{"key":"B","text":"调用最新且参数大的模型(如Qwen-max)通过更好的技术降低计算成本","correct":false},{"key":"C","text":"使用批量推理服务,离线方式处理数据","correct":true},{"key":"D","text":"调用支持上下文缓存(ContextCache)的模型减少重复请求的计算开销","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 565, 'single', '以下哪个选项最适合作为系统角色提示词,用于构建一个可以进行代码审查的AI助手?', '[{"key":"A","text":"{\\"role\\":\\"system\\",\\"content\\":\\"你是一个资深代码审查专家,专注于发现代码中的潜在问题,例如 bug、性能瓶颈和代码风格问题。请提供详细的修改建议和解释。\\"}","correct":true},{"key":"B","text":"{\\"role\\":\\"user\\",\\"content\\":\\"这是我的代码,请帮我审查。\\"}","correct":false},{"key":"C","text":"{\\"role\\":\\"assistant\\",\\"content\\":\\"请提交需要审查的代码。\\"}","correct":false},{"key":"D","text":"{\\"role\\":\\"system\\",\\"content\\":\\"你是一个初级程序员,正在学习代码审查。\\"}","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 566, 'single', '在大模型调用外部API工具时,工具函数的描述(description)起到的关键作用是什么?', '[{"key":"A","text":"帮助大模型理解何时以及如何调用该函数","correct":true},{"key":"B","text":"减少API调用过程中的内存占用","correct":false},{"key":"C","text":"加密API请求中的敏感数据","correct":false},{"key":"D","text":"提高API调用的速度","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 567, 'single', '以下哪种参数组合会使得模型生成结果最具多样性?', '[{"key":"A","text":"temperature=0.1, top_p=0.9","correct":false},{"key":"B","text":"temperature=0.1, top_p=0.1","correct":false},{"key":"C","text":"temperature=0.9, top_p=0.1","correct":false},{"key":"D","text":"temperature=0.9, top_p=0.9","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 568, 'single', '在调用百炼大模型接口时,如何指定用户的输入内容?', '[{"key":"A","text":"将用户输入内容作为''messages''列表中字典的''content''字段的值传入","correct":true},{"key":"B","text":"将用户输入内容作为model参数的值传入","correct":false},{"key":"C","text":"将用户输入内容作为api_key参数的值传入","correct":false},{"key":"D","text":"将用户输入内容作为base_url参数的值传入","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 569, 'single', '你希望你所构建的大模型客服应用能保障合规性的同时,也要确保用户使用体验,以下哪个技 术方案更可靠且不明显影响体验?', '[{"key":"A","text":"在大模型生成答案后,使用正则表达式过滤器,检测并替换敏感关键词","correct":false},{"key":"B","text":"结合内容安全服务,对大模型流式输出实施实时合规扫描,违规片段内容进行替换","correct":true},{"key":"C","text":"基于关键词实时匹配触发拦截机制,高危内容直接终止响应并提示用户","correct":false},{"key":"D","text":"部署混合模型架构:大模型生成回答后,立即调用专用小模型进行合规性重写","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 570, 'single', '以下哪个代码片段展示了正确的用户(user)提问方式?', '[{"key":"A","text":"messages = [{\\"role\\": \\"user\\", \\"content\\": \\"你是一个诗歌生成器。\\"}, {\\"role\\": \\"assistant\\", \\"content\\": \\"我想 写一首关于秋天的诗。\\"}]","correct":false},{"key":"B","text":"messages = [{\\"role\\": \\"system\\", \\"content\\": \\"你是一个诗歌生成器。\\"}, {\\"role\\": \\"assistant\\", \\"content\\": \\"请 告诉我你想写一首关于什么的诗。\\"}]","correct":false},{"key":"C","text":"messages = [{\\"role\\": \\"system\\", \\"content\\": \\"你是一个诗歌生成器。\\"}, {\\"role\\": \\"user\\", \\"content\\": \\"我想写一首关于秋天的诗。\\"}]","correct":true},{"key":"D","text":"messages = [{\\"role\\": \\"system\\", \\"content\\": \\"你是一个诗歌生成器。\\"}, {\\"role\\": \\"system\\", \\"content\\": \\"我 想写一首关于秋天的诗。\\"}]","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 571, 'single', '在大模型对话的API中,assistant角色的作用是什么?', '[{"key":"A","text":"提供用户输入","correct":false},{"key":"B","text":"监控对话的安全性","correct":false},{"key":"C","text":"设定对话的背景信息","correct":false},{"key":"D","text":"代表模型本身,返回生成的回复","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 572, 'single', '数据预处理中,将分类任务的标签转化为模型可理解的数字形式称为什么?', '[{"key":"A","text":"文本标准化","correct":false},{"key":"B","text":"词嵌入(Word Embedding)","correct":false},{"key":"C","text":"特征缩放","correct":false},{"key":"D","text":"标签编码(Label Encoding)","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 573, 'single', '当我们发现使用的模型在大数计算时表现不佳,哪个措施提升最大?', '[{"key":"A","text":"改进提示词","correct":false},{"key":"B","text":"微调模型,让它学会在大数计算时使用计算器插件","correct":true},{"key":"C","text":"提供大数计算样例","correct":false},{"key":"D","text":"使用微调提高模型的逻辑推理能力","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 574, 'single', '你在阿里云百炼上搭建了一个智能应用,为用户提供美食推荐服务,你希望智能体记住用户的 喜好、避免推荐之前用户提及过的忌口食物。以下哪个方案能以低成本满足这一诉求?', '[{"key":"A","text":"构建独立的历史对话知识库,通过RAG在每次请求时检索用户全部聊天记录并持续维护知识库更 新与索引优化","correct":false},{"key":"B","text":"在应用侧硬编码用户提供忌口信息","correct":false},{"key":"C","text":"构建基于向量数据库的实时对话语义检索系统,检索常见忌口信息","correct":false},{"key":"D","text":"使用长期记忆功能,让智能体不断积累用户偏好信息","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 575, 'single', '以下哪种做法不符合利用大模型提升开发效率的思路?', '[{"key":"A","text":"对于所有类型的图片,都使用视觉模型进行深层次解析,以确保信息的完整性。","correct":true},{"key":"B","text":"使用DashScopeParse解析文档,而不是自己编写复杂的解析逻辑。","correct":false},{"key":"C","text":"将复杂的文档处理任务拆分成多个子任务,分别使用不同的模型或工具处理。","correct":false},{"key":"D","text":"对于简单的文本替换操作,使用正则表达式而不是调用大模型API。","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 576, 'single', '你在开发公司内部制度问答机器人时,将所有制度文件都输入到大模型中,导致输入超长报 错,应优先采用哪种方案?', '[{"key":"A","text":"使用RAG,检索最相关的文本后再输入到大模型","correct":true},{"key":"B","text":"增加生成Token的数量","correct":false},{"key":"C","text":"降低temperature值","correct":false},{"key":"D","text":"通过参数调大模型的最大输入长度","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 577, 'single', '如果将top_p设置为一个非常小的值,例如0.1,模型的生成结果会有什么特点?', '[{"key":"A","text":"生成结果长度会变短。","correct":false},{"key":"B","text":"生成结果更加保守,倾向于选择概率最高的少数几个词,多样性降低。","correct":true},{"key":"C","text":"生成结果长度会变长。","correct":false},{"key":"D","text":"生成结果更加多样化。","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 578, 'single', 'RAG系统在回答时,返回了多位同名员工的信息,无法区分他们,最合理的改进方式是什么?', '[{"key":"A","text":"在检索前自动补充标签,例如“姓名:张伟(IT部)”","correct":true},{"key":"B","text":"简单将“张伟”替换成“张伟唯一”","correct":false},{"key":"C","text":"大幅提高大模型的温度","correct":false},{"key":"D","text":"默认检索100条切片,手动让用户筛选","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 579, 'single', '你需要大模型对用户输入的新闻内容进行分类(体育/经济/娱乐三种),为提升易懂性且便于程 序解析,以下哪个提示词更合理?', '[{"key":"A","text":"请根据下面提供的内容判断其类别(体育/经济/娱乐),只输出判断结果。内容是","correct":false},{"key":"B","text":"请根据下面提供的内容判断其类别(体育/经济/娱乐)。先输出思考过程,再在最后一行用“结 论.”开头写明类别。内容是","correct":false},{"key":"C","text":"请根据下面提供的内容判断其类别(体育/经济/娱乐),以JSON格式输出,“reason”原 因,“type”类别。如[体育/经济/娱乐]内容是","correct":true},{"key":"D","text":"请根据下面提供的内容判断其类别(体育/经济/娱乐),用符号分隔。思考过程类别结果。内容 是...","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 580, 'single', '在使用Qwen-Max辅助内容生成的过程中,以下哪个操作是正确的?', '[{"key":"A","text":"让Qwen-Max执行编程代码","correct":false},{"key":"B","text":"利用Qwen-Max生成课程脚本","correct":true},{"key":"C","text":"应用Qwen-Max进行视频剪辑任务","correct":false},{"key":"D","text":"直接使用Qwen-Max进行图像设计","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 581, 'single', '在检测文档内容中是否存在营销性表达时,下列哪种方法可以更全面地识别问题?', '[{"key":"A","text":"识别所有内容错误的部分","correct":false},{"key":"B","text":"让大模型自动修改内容","correct":false},{"key":"C","text":"逐条单独识别营销词汇","correct":false},{"key":"D","text":"一次性生成所有类型的识别结果","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 582, 'single', '在RAG的建立索引过程中,以下哪一点是将源知识文件分割成文本段的主要原因?', '[{"key":"A","text":"让大模型输出更加多样","correct":false},{"key":"B","text":"提高检索精度,更快地定位相关段落","correct":true},{"key":"C","text":"减少数据存储空间","correct":false},{"key":"D","text":"减少索引构建时间","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 583, 'single', '在监控模型训练性能时,以下哪段代码可用于计算并打印准确率?', '[{"key":"A","text":"loss.backward()","correct":false},{"key":"B","text":"optimizer.step()","correct":false},{"key":"C","text":"correct /= total; print(f''Accuracy: {100 * correct:.2f}%'')","correct":true},{"key":"D","text":"running_loss += loss.item() * inputs.size(0)","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 584, 'single', '在一个电商问答系统中,用户提问“百炼X1手机的电池容量是多少?”后又问“充电器支持快充 吗?”。如果直接用第二轮的问题进行检索,可能会出现什么现象?', '[{"key":"A","text":"由于embedding擅长处理短文本,因此检索结果更为精确","correct":false},{"key":"B","text":"embedding模型不擅长处理短文本,导致检索精度下降","correct":false},{"key":"C","text":"向量数据库自带上下文记忆功能,可以准确判断第二轮的问题是关于“百炼X1手机”的","correct":false},{"key":"D","text":"检索结果不准确,丢失“百炼X1手机”这一历史对话信息","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 585, 'single', '你在用大模型解答这个题:“一口10米的井,蜗牛从井底向上爬,每个白天向上爬3米,每晚滑 下2米。请问蜗牛需要多少天能爬出这口井?”。以下哪种提示方法可以提升大模型的解答准确率?', '[{"key":"A","text":"要求大模型使用平均速度计算总天数","correct":false},{"key":"B","text":"要求大模型在生成时解释逻辑推导过程","correct":true},{"key":"C","text":"要求大模型直接输出最终结果","correct":false},{"key":"D","text":"要求大模型面临陷阱时进行解答","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 586, 'single', '以下代码片段实现了哪种文本合规检查方法? python ... import re def check_text(text): pattern = r"假货|劣质|骗子" if re.search(pattern, text): return "包含敏感词" else: return "文本安全" text = "这个产品质量很好,不像其他假货" result = check_text(text) print(result) # 输出:包含敏感词', '[{"key":"A","text":"语义分析","correct":false},{"key":"B","text":"模式匹配","correct":true},{"key":"C","text":"机器学习","correct":false},{"key":"D","text":"词性匹配","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 587, 'single', '运行以下代码等待任务结束时,不属于终止状态的是哪一项?', '[{"key":"A","text":"completed","correct":false},{"key":"B","text":"failed","correct":false},{"key":"C","text":"cancelled","correct":false},{"key":"D","text":"in_progress","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 588, 'single', '你在开发RAG应用时,发现召回的文本段包含了回答所需的必要信息,但是回答效果很差,你 可以怎么做?', '[{"key":"A","text":"更换向量数据库的选型","correct":false},{"key":"B","text":"更换性能更好的大模型","correct":true},{"key":"C","text":"更换性能更好的embedding模型","correct":false},{"key":"D","text":"尝试使用LlamaIndex外的其它RAG开发框架","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 589, 'single', '为了将不同长度的文本序列调整为统一长度以便模型处理,通常会采取哪种措施?', '[{"key":"A","text":"删除过长的句子","correct":false},{"key":"B","text":"忽略长度差异","correct":false},{"key":"C","text":"截断过短的句子","correct":false},{"key":"D","text":"填充序列到固定长度(Padding)","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 590, 'single', '某团队想用RAG做“分步骤查询”,先找出人员名单,再分别查询每人的部门信息,以下哪项功 能最适合?', '[{"key":"A","text":"ReRank(重排序)","correct":false},{"key":"B","text":"MultiStepQueryEngine(多步查询)","correct":true},{"key":"C","text":"SimpleDirectoryReader(读取本地文档)","correct":false},{"key":"D","text":"HyDE(假想文档生成)","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 591, 'single', 'LoRA微调对数据量要求的说法错误的是?', '[{"key":"A","text":"微调数据量较小时,应增大LoRA的秩以提升模型表达能力","correct":true},{"key":"B","text":"在数据质量有保障时,增大数据量、多样化通常能提升微调效果","correct":false},{"key":"C","text":"LoRA微调需求数据量比预训练要小","correct":false},{"key":"D","text":"同等数据量下(1000条),LoRA微调效果接近全参微调","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 592, 'single', '设计程序时,一般不会设计为调用一次大模型就处理完所有任务。下列关于如上说法的分析 中,错误的是哪一项?', '[{"key":"A","text":"单个大模型无法处理多种格式的文件。","correct":true},{"key":"B","text":"可以根据任务特点选择合适的模型和参数。","correct":false},{"key":"C","text":"难以同时保证每项工作的质量。","correct":false},{"key":"D","text":"可以分步优化,提高整体处理效率和成本。","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 593, 'single', '你需要在资源受限的环境下部署一个大模型,以下哪种方案有助于你减少对显存的需求?', '[{"key":"A","text":"知识蒸馏,训练一个更小参数量的模型","correct":true},{"key":"B","text":"扩大允许的输入Token长度","correct":false},{"key":"C","text":"微调现有模型,改善其效果","correct":false},{"key":"D","text":"提高模型批量任务的数量","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 594, 'single', '下列哪项不是向量数据库的主要作用?', '[{"key":"A","text":"检索向量数据","correct":false},{"key":"B","text":"为向量数据结构索引","correct":false},{"key":"C","text":"训练Embedding模型","correct":true},{"key":"D","text":"存储向量数据","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 595, 'single', '下列代码片段的作用是? from keras.preprocessing.sequence import pad_sequences padded_seq = pad_sequences(sequences, maxlen=max_len, padding=''post'', truncating=''post'')', '[{"key":"A","text":"序列填充到固定长度","correct":true},{"key":"B","text":"文本摘要生成","correct":false},{"key":"C","text":"特征缩放","correct":false},{"key":"D","text":"文本向量化","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 596, 'single', '检查以下代码,如果需要添加一个新的意图类别,例如“入职流程”,需要修改哪一部分代码? python # 获取用户意图的核心算法 def get_purpose(document): prompt_template="【角色背景】 你是一个专业的管理者,你将阅读一条用户的问题并进行用户意图分类 【任务要求】 我们需要将用户的意图分成如下几类: 请假政策、福利待遇、绩效考核、工作职责、开发规范 【输出要求】 请以 json 格式输出,不要输出其他内容 格式如{"purpose":"请假政策","query":"请假流程是怎样的,需要提前多久申请?"} 其中,purpose 是你识别出的意图,query 是用户输入的原始文本 【用户输入】 以下是用户输入,请审阅: """ query = prompt_template + document', '[{"key":"A","text":"只需要修改输入的用户 query 列表","correct":false},{"key":"B","text":"需要修改输出格式要求。","correct":false},{"key":"C","text":"需要修改prompt_template中的【任务要求】部分,以及可能需要更新get_purpose函数中的逻 辑。","correct":true},{"key":"D","text":"只需要修改大模型query函数Q_S_Line","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 597, 'single', 'APIAssistantAgent示例代码verify_status_code函数的作用是什么? python def verify status code(res): if res.status code != HTTPStatus.OK: print("Failed:") print(res) sys.exit(res.status code)', '[{"key":"A","text":"验证function call的参数是否正确","correct":false},{"key":"B","text":"验证用户输入的query是否合法","correct":false},{"key":"C","text":"验证Assistant是否成功创建","correct":false},{"key":"D","text":"验证Thread是否成功创建","correct":false},{"key":"E","text":"验证模型返回的答案是否符合预期","correct":false},{"key":"F","text":"验证API调用的返回状态码是否为200","correct":true}]', 'F') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 598, 'single', '以下哪个分隔符形式不常用于提示词中?', '[{"key":"A","text":"&&& Part1 &&& Part2","correct":false},{"key":"B","text":"##Title Content","correct":false},{"key":"C","text":"... Section1 ... Section2","correct":true},{"key":"D","text":"...","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 599, 'single', '你使用阿里云百炼平台的通义千问API开发了聊天机器人,用户反馈:提问某地天气时模型总是 无法回答。如何快速解决这个问题?', '[{"key":"A","text":"提前设置话术,在面对类似问题时可以直接将话术返回给用户","correct":false},{"key":"B","text":"通过复杂的工程手段,对用户的输入提取关键词,集成第三方搜索引擎,并将搜索结果返回给大 模型","correct":false},{"key":"C","text":"设置enable_search(联网搜索)参数,为通义千问API引入联网能力","correct":true},{"key":"D","text":"在聊天界面显眼位置标注限制,不建议用户输入类似问题","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 600, 'single', '如果一款大模型无法理解复杂图片中的信息,应该采取什么策略?', '[{"key":"A","text":"手动提取图片信息。","correct":false},{"key":"B","text":"使用其他开源OCR工具再次尝试识别。","correct":false},{"key":"C","text":"放弃使用该图片。","correct":false},{"key":"D","text":"使用语义空间API的视觉理解模型对图片进行更深层次的分析。","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 601, 'single', '大语言模型微调相比重头训练的主要优势是什么?', '[{"key":"A","text":"训练时间更长","correct":false},{"key":"B","text":"可以利用预训练学到的通用知识","correct":true},{"key":"C","text":"需要更多计算资源","correct":false},{"key":"D","text":"对特定任务的表现不如从头训练的模型","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 602, 'single', '在RAG应用中,为什么需要将文本转化为向量表示?', '[{"key":"A","text":"提高向量在前端界面的显示效果","correct":false},{"key":"B","text":"减少存储空间","correct":false},{"key":"C","text":"方便人工阅读","correct":false},{"key":"D","text":"便于计算语义相似度","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 603, 'single', '某电商平台计划使用RAG模型构建智能客服系统,帮助用户查询商品信息。以下关于该系统的 评测方法,哪一项是正确的?', '[{"key":"A","text":"生成模块是系统的核心,应优先优化生成阶段的知识总结能力。","correct":false},{"key":"B","text":"应重点评估检索模块的表现,因为商品信息的准确性和相关性直接影响最终生成的结果。","correct":false},{"key":"C","text":"应对检索阶段和生成阶段分别进行评测,以便全面优化系统性能。","correct":true},{"key":"D","text":"评测时只需关注最终回答的准确性,因为用户的满意度主要取决于答案是否正确。","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 604, 'single', '在设定大语言模型的训练参数时,哪个参数可以影响模型每次更新时所考虑的数据量,并间接 影响到模型收敛速度和内存使用?', '[{"key":"A","text":"学习率","correct":false},{"key":"B","text":"正则化","correct":false},{"key":"C","text":"批大小","correct":true},{"key":"D","text":"动态学习率策略","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 605, 'single', '请问这段代码的主要作用是? python node_parser = SentenceWindowNodeParser.from_defaults( window_size=3, window_metadata_key="window", original_text_metadata_key="original_text", ) nodes = node_parser.get_nodes_from_documents([document]) window_text_replace = MetadataReplacementPostProcessor( target_metadata_key="window" )', '[{"key":"A","text":"对召回的文本段进行rerank后,输入大模型进行回复","correct":false},{"key":"B","text":"在句子窗口检索中,将扩展后的句子传入上下文并进行回复","correct":true},{"key":"C","text":"在自动合并检索中,判断父节点是否有超过半数的子节点被召回","correct":false},{"key":"D","text":"加载本地索引,对query进行回复","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 606, 'single', '在RAG流程中,如何提高检索的效率?', '[{"key":"A","text":"增加embedding的维度","correct":false},{"key":"B","text":"使用更大的预训练语言模型","correct":false},{"key":"C","text":"对向量数据库中的向量构建索引","correct":true},{"key":"D","text":"增加文档切片的粒度(例如将段落切成更小的片段)","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
