INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 613, 'single', '游戏公司开发AI数字人NPC时,以下哪项技术要求目前最难实现?', '[{"key":"A","text":"根据玩家情绪调整对话语气","correct":false},{"key":"B","text":"识别语音指令执行简单任务","correct":false},{"key":"C","text":"实时生成符合角色设定的剧情分支","correct":true},{"key":"D","text":"通过动作捕捉复现预设舞蹈动作","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 614, 'single', '你让大模型为科技新闻生成标题,但输出标题过于平淡(如“某公司发布新产品”)。以下哪种方 法,更有助于生成你想要的标题:', '[{"key":"A","text":"调整输出格式:要求标题全部大写","correct":false},{"key":"B","text":"通过多轮对话,明确告诉大模型不满意:“我觉得不好,再改改”","correct":false},{"key":"C","text":"先增加上下文,补充产品关键信息,如果不好再尝试增加一些样例","correct":true},{"key":"D","text":"补充新闻稿中的发布会日期、会场地址和与会者人数","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 615, 'single', '构建RAG应用时,建立索引阶段的正确顺序是?', '[{"key":"A","text":"文档加载-文本向量化-向量分割-索引存储","correct":false},{"key":"B","text":"内容分割-文本向量化-索引存储","correct":false},{"key":"C","text":"文档加载-文本向量化-索引存储","correct":false},{"key":"D","text":"文档加载-内容分割-文本向量化-索引存储","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 616, 'single', '句子窗口检索的优势在于:', '[{"key":"A","text":"提高检索阶段的精确性同时,保证了生成阶段的信息完整性","correct":true},{"key":"B","text":"对大模型的注意力机制进行了针对性改善","correct":false},{"key":"C","text":"提高大模型生成的速度","correct":false},{"key":"D","text":"可以降低对数据库存储空间要求","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 617, 'single', 'replacements的作用是:', '[{"key":"A","text":"使得文本更有层级","correct":false},{"key":"B","text":"Llamalndex按照英文标点切分句子,这么做保证每个句子不会太大","correct":true},{"key":"C","text":"提高大模型对标点符号的识别准确率","correct":false},{"key":"D","text":"降低召回文本段的中文含量","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
