INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 619, 'single', '在开发过程中,你发现大模型调用某工具函数时常因输入参数格式错误而失败,最可能的原因 是?', '[{"key":"A","text":"大模型运行时受到系统资源限制(如内存或处理延迟)影响,导致在处理复杂输入文本时发生数 据截断或错误,生成错误的参数格式。","correct":false},{"key":"B","text":"用户输入中可能包含非标准符号或格式不规范的内容,误导大模型在调用参数时产生偏差。","correct":false},{"key":"C","text":"工具函数发生了变化,造成数据传输时自动转换格式出现问题,从而影响参数的正确生成。","correct":false},{"key":"D","text":"工具函数的参数描述信息不足,未明确规定输入参数的具体格式,导致大模型生成调用参数时出 现偏差。","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 620, 'single', '以下哪个代码片段正确地使用了system角色来指示模型扮演一个友好的客服代表?', '[{"key":"A","text":"messages = [{\\"role\\": \\"system\\", \\"content\\": \\"你是一位友好的客服代表,随时准备帮助客户解决问 题。\\"}]","correct":true},{"key":"B","text":"messages = [{\\"role\\": \\"assistant\\", \\"content\\": \\"您好,请问有什么可以帮您的?\\"}]","correct":false},{"key":"C","text":"messages = [{\\"role\\": \\"user\\", \\"content\\": \\"我想咨询一下退货流程。\\"}]","correct":false},{"key":"D","text":"messages = [{\\"role\\": \\"system\\", \\"content\\": \\"用户想咨询退货流程。\\"}]","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
