INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 625, 'single', '作为应用开发者,如果想要让大模型避免回答与个人隐私相关的问题,最推荐在哪个角色中设 置相应的限制?', '[{"key":"A","text":"user","correct":false},{"key":"B","text":"assistant","correct":false},{"key":"C","text":"任何角色都可以","correct":false},{"key":"D","text":"system","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 626, 'single', '以下哪种方式有助于在大模型多轮对话场景中,保障生成内容质量的同时,降低成本,并提升 响应速度?', '[{"key":"A","text":"使用BatchAPI","correct":false},{"key":"B","text":"并行调用大模型API","correct":false},{"key":"C","text":"使用支持上下文缓存的大模型API","correct":true},{"key":"D","text":"使用经过量化的模型","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 627, 'single', 'RAG应用在处理IT技术文档时表现不错,但在公司内部人事流程的问答中经常答非所问。最先 应该检查哪方面?', '[{"key":"A","text":"问题必须拆成多次检索","correct":false},{"key":"B","text":"大模型温度过高","correct":false},{"key":"C","text":"是否缺少人事流程相关文档或索引","correct":true},{"key":"D","text":"大模型计算资源不足","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 628, 'single', '在大模型调用外部API工具时,你发现agent经常调用错误的工具。经过调查,最可能的原因是什 么?', '[{"key":"A","text":"大模型缺乏足够的并行处理能力","correct":false},{"key":"B","text":"网络延迟导致工具调用超时","correct":false},{"key":"C","text":"工具函数调用过程中存在严重的内存泄漏","correct":false},{"key":"D","text":"工具函数描述信息不够明确,未能准确说明调用时机和用途","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 629, 'single', '下列哪项不属于大语言模型微调可能带来的挑战?', '[{"key":"A","text":"需要足够高质量的特定领域数据","correct":false},{"key":"B","text":"微调过程可能引入偏见","correct":false},{"key":"C","text":"模型大小和复杂度降低","correct":true},{"key":"D","text":"过拟合特定任务,泛化能力下降","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 630, 'single', '在开发一个需要调用大模型API的应用时,为了保护敏感信息不被泄露,以下哪种方式是处理 APIKey的安全做法?', '[{"key":"A","text":"在代码中写入APIKey","correct":false},{"key":"B","text":"将APIKey存储到环境变量中","correct":true},{"key":"C","text":"在代码注释中记录APIKey","correct":false},{"key":"D","text":"将APIKey保存在公开的配置文件中","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 631, 'single', '以下关于基于规则的文本合规检查方法的描述,哪一项是不正确的?', '[{"key":"A","text":"对于特定高风险场景效果显著。","correct":false},{"key":"B","text":"需要维护一个规则库,例如包含正则表达式、敏感词或模式。","correct":false},{"key":"C","text":"规则更新可能不及时,人工维护成本较高。","correct":false},{"key":"D","text":"具有很强的数据泛化能力,可以有效识别新的变种。","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 632, 'single', '一家律所的 AI 助手在分析合同风险时,频繁引用一个已被新司法解释推翻的相似案例。系统目 前仅采用向量检索召回 top-k 内容。为了更好地解决此问题,应采取哪项措施?', '[{"key":"A","text":"从向量索引中定期清除所有已被新司法解释覆盖的案例","correct":false},{"key":"B","text":"切换到多向量检索,为文档内容和法律实体分别创建嵌入","correct":false},{"key":"C","text":"增强提示词,指令模型在生成摘要时优先采信最新日期的文档","correct":false},{"key":"D","text":"生成前先结合“时效性”等业务字段进一步重排和过滤","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 633, 'single', '一家重型设备制造商,为现场技术员提供 AI 维修指南,但架构师要求所有历史规范都必须保留 用于合规审计。你担心如果 RAG 系统引用已废弃的设计规范,可能导致维修错误。你应如何解决这 个问题?', '[{"key":"A","text":"优化系统提示词,指令模型忽略旧版本并解释其选择","correct":false},{"key":"B","text":"建立与原有业务系统的实时数据同步,确保数据源的唯一性。","correct":false},{"key":"C","text":"获取知识块时附加版本与元数据标签,并在检索时过滤","correct":true},{"key":"D","text":"在应用层过滤,输出回答前,过滤掉过期文档索引","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 634, 'single', '你在设计儿童教育类智能应用,客户要求需同时满足安全性和趣味性。以下哪种交互方案最合 理?', '[{"key":"A","text":"所有教学内容仅以全屏视频展示,观看期间禁用物理按键,视频结束后弹出知识测验","correct":false},{"key":"B","text":"采用卡通语音陪伴助手,敏感操作需家长手机端二次验证,错误操作时用震动+彩色光带提示","correct":true},{"key":"C","text":"主界面设置 20 个高亮功能导航按钮,点击任意区域即时播放提示音,夜间自动切换深色模式","correct":false},{"key":"D","text":"内置家长监控摄像头,孩子使用超过1小时自动锁屏并通过人脸识别判断是否成年用户","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 635, 'single', '某团队使用通义千问 API 开发智能问答应用,为了快速实现回答实时外部问题(如“今天的天 气”)的能力,可以首先使用哪种方案?', '[{"key":"A","text":"指派资源,手动开发一个天气查询插件","correct":false},{"key":"B","text":"升级到最新发布的更大参数规模的模型","correct":false},{"key":"C","text":"启用平台提供的联网搜索功能","correct":true},{"key":"D","text":"通过多轮对话设计,引导模型回答实时问题","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 636, 'single', '你用多模态技术开发短视频智能剪辑工具时,提出以下四个方案步骤,其中不合理的步骤是?', '[{"key":"A","text":"用 RAG 增强技术提升视频的饱和度对比度","correct":true},{"key":"B","text":"用视频理解模型分析视频中的人物动作","correct":false},{"key":"C","text":"用语音合成模型为合成视频添加官方解说","correct":false},{"key":"D","text":"用文生图模型将新场景与原视频人物合成","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 637, 'single', '一家智能客服系统初期采用了昂贵的旗舰大模型(如GPT-N),虽然效果很好,但运营发现70% 的用户问题都是“如何登录”“忘记密码”这类高频简单问题。为了节约API调用成本,团队应该优先采 用哪种架构调整?', '[{"key":"A","text":"微调整旗舰大模型,使其能更快地回答这些高频问题","correct":false},{"key":"B","text":"先用轻量级模型识别意图按任务路由,对复杂问题调用旗舰模型","correct":true},{"key":"C","text":"选择价格更低的API服务套餐","correct":false},{"key":"D","text":"限制每位用户的日均提问次数,并对超出部分进行收费","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 638, 'single', '你开发的AI客服系统出现以下异常:用户发送“我想看红色连衣裙的3D展示”时,系统返回文字 描述但无图像,当用户发送产品视频时,系统无法提取关键参数,语音回复存在机械音且断句不自 然,上述异常对应的技术缺陷依次是?', '[{"key":"A","text":"3D渲染超时→OCR识别失败→语音克隆失真","correct":false},{"key":"B","text":"文本生成错误→视频合成中断→音频采样率异常","correct":false},{"key":"C","text":"文生图失败→视频理解异常→语音合成缺陷","correct":true},{"key":"D","text":"多模态融合故障→抽帧算法错误→TTS模型过拟合","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 639, 'single', '你负责的短视频平台计划优化内容审核系统,需要实现:1. 自动识别视频中出现的违禁物品,2. 对识别出的违禁画面自动生成马赛克覆盖,正确的技术路线是?', '[{"key":"A","text":"视频抽帧后用多模态大模型分析内容→文生图生成马赛克图案→合成新视频","correct":true},{"key":"B","text":"使用语音合成分析音频→文本生成警告信息→视频编辑添加水印","correct":false},{"key":"C","text":"文生图模型生成安全提示图→使用语音合成生成警告音频→自动下架视频","correct":false},{"key":"D","text":"通过视频编辑手动提取关键帧→文本生成模型标注违禁词","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 640, 'single', '构建AI智能体时,以下哪种技术方案最适合实现“以自然流畅的方式与终端用户进行实时音视频 通话”的需求?', '[{"key":"A","text":"引入语音识别模型,并结合文本生成模型生成文本回复内容,但仅输出文本回答","correct":false},{"key":"B","text":"利用多模态大语言模型,结合实时音视频处理框架,实现端到端的交互能力","correct":true},{"key":"C","text":"部署视频分析平台,支持文字聊天并允许用户手动上传图片或视频供分析","correct":false},{"key":"D","text":"使用传统的基于规则的对话系统,结合预录制的音频和视频片段来模拟互动","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 641, 'single', '一家影视制作公司计划推出一款虚拟主播,用于直播带货和互动娱乐场景。以下哪一种描述了 实现虚拟主播的一种方法?', '[{"key":"A","text":"使用大语言模型生成剧本初稿,供编剧团队进一步修改和完善。","correct":false},{"key":"B","text":"开发一个推荐系统,为观众推荐他们可能感兴趣的直播内容。","correct":false},{"key":"C","text":"使用语音合成技术生成个性化配音,替代人工配音演员完成所有影视作品的配音工作。","correct":false},{"key":"D","text":"利用图像理解技术对演员的面部表情进行捕捉,并将其映射到虚拟主播角色上,实现实时互动表 演。","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 642, 'single', '某智能客服系统,同时接入了多个不同来源的大模型(如通义、文心等),并通过多种渠道 (App、微信等)对外提供服务。目前,安全团队通过为每个模型的每个渠道分别定制系统提示词 (System Prompt)来实施安全策略。随着模型和渠道的增加,安全策略的同步和维护工作量呈指数 级增长,一个新漏洞需要在所有组合上重复修复,极易出现遗漏。为了建立一个更健壮、可扩展且 易于维护的防御体系,下一步应优先考虑哪种做法?', '[{"key":"A","text":"持续投入更多人力,对系统提示词进行更精细化的“雕刻”。","correct":false},{"key":"B","text":"引入独立的AI安全中间件,将安全逻辑与业务逻辑解耦。","correct":true},{"key":"C","text":"建立一个内部漏洞悬赏平台,激励员工寻找越狱方法。","correct":false},{"key":"D","text":"暂停功能开发,集中资源对大模型本身进行为期半年的对抗性训练。","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 643, 'single', '一家初创公司的AI客服,在安全审计中发现会泄露其他用户的个人信息(PII)。根因是其RAG 知识库的数据源包含未经处理的生产工单数据库。在预算有限的约束下,以下哪个优化方案的成本 效益最高?', '[{"key":"A","text":"要求运营团队手动标注工单,ETL流程仅抽取标记为“不含PII”的数据。","correct":false},{"key":"B","text":"在模型回复的API出口处,部署一个基于规则的PII内容过滤器。","correct":false},{"key":"C","text":"采购并部署商业级数据库防火墙,在数据查询时进行实时动态脱敏。","correct":false},{"key":"D","text":"改造数据摄入流程,在数据向量化前进行自动化的PII识别与脱敏。","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 644, 'single', '你在需要构建公文智能处理系统,用户上传PDF文件后,系统需自动识别文本内容并生成摘要。 以下哪种架构设计比较合理?', '[{"key":"A","text":"用户前端将图片上传至OSS,触发函数计算FC执行预处理,FC调用百炼模型服务生成描述文本, 最终结果返回前端","correct":true},{"key":"B","text":"用户前端直接调用百炼模型服务生成文本,模型服务将原始图片存入OSS,函数计算FC只负责最 终结果缓存","correct":false},{"key":"C","text":"用户前端上传图片至OSS,函数计算FC直接读取图片内容进行分析,通过数字编解码技术解析文 字信息,保存到OSS","correct":false},{"key":"D","text":"用户前端上传图片至函数计算FC,FC调用百炼模型服务生成文本,并将图片和结果统一存入OSS","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 645, 'single', '一家SaaS公司提供LLM推理服务。为满足高级别安全合规,必须技术性地阻止拥有主机root权限 的员工访问运行时数据,并向客户提供一份由硬件生成的、可远程验证的加密报告以证明环境完整 性。要实现此目标,哪项技术是不可或缺的?', '[{"key":"A","text":"使用eBPF等内核技术监控容器内所有系统调用","correct":false},{"key":"B","text":"对所有LLM计算任务采用全同态加密(FHE)技术","correct":false},{"key":"C","text":"基于硬件的可信执行环境(TEE)及其远程证明机制","correct":true},{"key":"D","text":"采用硬件内存加密技术(如AMD SEV)加密整个虚拟机","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 646, 'single', '你在帮跨境电商平台改造商品推荐系统,对方要求你做到:用户上传商品图片后,10秒内返回 对应语言的商品描述和相似商品推荐。最合理的组件协作流程是?', '[{"key":"A","text":"前端上传图像到OSS→函数计算FC调用百炼生成多模态描述→函数计算FC调用商品推荐算法→结 果聚合返回","correct":true},{"key":"B","text":"前端直传图片到百炼模型→百炼生成描述后存入OSS→函数计算FC生成推荐商品列表","correct":false},{"key":"C","text":"OSS保存图像后发送消息到Kafka→通过Flink实时计算推荐结果→再通过百炼上的模型服务补全图 像描述","correct":false},{"key":"D","text":"函数计算FC接收图片后通过图像处理算法提取特征→图像特征存入OSS→启动定时任务批量生成 推荐结果","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 647, 'single', '某连锁咖啡品牌采用视觉理解模型巡检门店以节约成本,但任务完成率不理想。升级为大小模 型+智能体协同方案:小模型负责图像定位与抠图,大模型负责状态判定。但监测发现大模型仍频繁 处理原始图像(导致资源浪费),应重点优化哪项?', '[{"key":"A","text":"为大模型添加更多低价值任务(区域定位)的训练数据,提升其对定位任务的专用性","correct":false},{"key":"B","text":"扩展GPU服务器集群规模,提升大模型运算速度","correct":false},{"key":"C","text":"要求门店员工预先标注监控关键区域,减少系统自动区域定位的依赖","correct":false},{"key":"D","text":"在Planner Agent中,优先将图像识别任务分配给小模型,仅让大模型处理复杂状态判断","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 648, 'single', '在设计一个电商推荐系统的RAG模块时,团队决定优化检索的精确率(context precision),以 确保每次推荐的商品都相关。然而,过度追求精确率可能会带来一些负面影响,以下哪种现象最有 可能出现?', '[{"key":"A","text":"系统召回的商品数量过少,用户难以找到足够的选择。","correct":true},{"key":"B","text":"用户收到大量与查询无关的商品推荐,导致体验下降。","correct":false},{"key":"C","text":"推荐商品的颜色多为用户不喜欢的类型,导致满意度下降。","correct":false},{"key":"D","text":"系统响应时间显著增加,导致用户体验变差。","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 649, 'single', '在优化context recall(上下文召回)指标时,以下哪种方法可以提升召回的准确率?', '[{"key":"A","text":"使用大模型改写query","correct":true},{"key":"B","text":"增加模型的训练数据","correct":false},{"key":"C","text":"减少模型的推理时间","correct":false},{"key":"D","text":"增加模型的参数数量","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 650, 'single', '在文档切片过程中,以下哪种切片方法适合刚开始接触RAG的用户?', '[{"key":"A","text":"句子切片","correct":true},{"key":"B","text":"Token切片","correct":false},{"key":"C","text":"句子窗口切片","correct":false},{"key":"D","text":"语义切片","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 651, 'single', '你设计了一个车载场景的智能对话助手,它可以帮乘客调整座椅、打开空调等。某次测试中, 用户输入“把靠背调低一点”,助手却打开了空调。经过分析,发现是因为调整座椅工具的描述 (description)过于简单,导致助手误判了用户意图。以下哪个调整座椅工具的描述信息可以使助手 提高调用工具的准确率?', '[{"key":"A","text":"请根据用户的输入判断是否需要调整座椅,然后调用对应的工具。","correct":false},{"key":"B","text":"如果用户要调整座椅,请调用aa工具;如果用户要打开空调,请调用bb工具。","correct":false},{"key":"C","text":"你擅长理解用户的多样化需求,可以通过语义分析选择正确的工具。","correct":false},{"key":"D","text":"当用户希望调整座椅靠背或前后位置时使用此工具。该工具接收两个参数:前后(单位为厘 米)、角度(单位为度)。","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 652, 'single', '你在使用本地部署的qwen2.5-14b模型,输入提示词:“请用适合简报的形式,以每篇100字的篇 幅总结今早的十大新闻”,但发现无法按照预期给出正确的结果,这是为什么?', '[{"key":"A","text":"输出长度受限,10篇新闻过多","correct":false},{"key":"B","text":"要求列出10个项目意味着处理结构化数据,而LLM对此不擅长","correct":false},{"key":"C","text":"由于知识截止限制,LLM无法获取最新新闻","correct":true},{"key":"D","text":"指令需要明确简报类型(科技、综合新闻等)","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 653, 'single', '梯度下降算法中学习率的作用是?', '[{"key":"A","text":"决定梯度计算频率","correct":false},{"key":"B","text":"调节参数更新步幅","correct":true},{"key":"C","text":"控制参数更新方向","correct":false},{"key":"D","text":"调整梯度大小","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 654, 'single', '模型微调最适合解决以下哪种问题?', '[{"key":"A","text":"需要实时检索最新互联网信息的任务","correct":false},{"key":"B","text":"需要提升模型在特定任务的表现","correct":true},{"key":"C","text":"需要快速响应简单问答的任务","correct":false},{"key":"D","text":"需要结合用户界面操作的任务","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 655, 'single', '公司文档规模可达数百万条,需7x24小时高可用的RAG服务。下列哪种向量存储方式最适合?', '[{"key":"A","text":"存为Excel","correct":false},{"key":"B","text":"本地部署Milvus/Qdrant","correct":false},{"key":"C","text":"阿里云向量检索服务(DashVector)等云方案","correct":true},{"key":"D","text":"内存向量存储","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 656, 'single', '以下哪种场景适合使用阿里云百炼上提供的大模型BatchAPI(批量处理接口)来优化成本或效 率?', '[{"key":"A","text":"在实时在线客服对话中,使用BatchAPI同时处理多个用户的并发请求,以提高响应速度","correct":false},{"key":"B","text":"在会议直播场景中,使用BatchAPI让大模型将主讲人的发言实时翻译成多个语种","correct":false},{"key":"C","text":"将BatchAPI与流式传输(Streaming)结合,逐步返回批量处理中的部分结果给用户","correct":false},{"key":"D","text":"收集一周内的数千条产品用户反馈信息,打包后一次性提交给大模型生成分析总结报告","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 657, 'single', '一家广告公司打造AI辅助视频制作系统,公司的创意总监要求必须能够对AI生成的初稿进行“像 素级”的精细调整。要满足这种对自动化生成与后期精细编辑控制的双重需求,以下哪种系统设计理 念最为关键?', '[{"key":"A","text":"部署跨模态像素级生成的扩散模型,当检测到标注笔触像素时动态调整潜空间的噪声模式","correct":false},{"key":"B","text":"优先保证生成速度,系统快速输出一个“草稿版”视频,然后使用另一个更昂贵的AI大模型视频修 复工具对不满意的片段进行反复的局部重绘或修复","correct":false},{"key":"C","text":"训练一个接受多模态指令的超大模型,允许用户通过“把那辆车换成XX品牌”或“让解说快一点”等 自然语言指令反复迭代视频","correct":false},{"key":"D","text":"设计一个“分层可编辑”的输出格式,AI不直接生成最终的MP4视频,而是生成一个包含时间轴、 资产清单、变换指令和脚本的结构化项目文件(如JSON或XML)","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 658, 'single', '由于供应商频繁更换原材料,你工厂的AI视觉质检系统经常出错,迫使产线增加人工复检,严 重影响产能。为确保系统能长期自适应,最关键的改进措施是什么?', '[{"key":"A","text":"部署数据漂移检测系统,实时告警原材料图像的统计变化","correct":false},{"key":"B","text":"调整AI质检的判定阈值,以快速减少当前高发的误报数量","correct":false},{"key":"C","text":"建立将人工纠错结果自动回流做增量微调的闭环机制","correct":true},{"key":"D","text":"升级为最先进的视觉理解模型,提升对新特征的泛化能力","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 659, 'single', '你在阿里云百炼上搭建了一个智能体应用,为用户提供美食推荐服务,你希望智能体能记住用 户的喜好,避免推荐之前用户提及过的忌口食物。以下哪个方案能以更低成本满足这一诉求?', '[{"key":"A","text":"构建基于向量数据库的实时对话语义检索系统,检索常见忌口信息","correct":false},{"key":"B","text":"在应用侧提醒用户提供忌口信息","correct":false},{"key":"C","text":"构建独立的历史对话知识库,通过RAG在每次请求时检索用户全部聊天记录并持续维护知识库更 新与索引优化","correct":false},{"key":"D","text":"使用长期记忆功能,让智能体能不断积累用户偏好信息","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 660, 'single', '大模型评判回答质量时,简洁回答总比长回答得分低,但人工评审认为前者更好。如何解决?', '[{"key":"A","text":"换一个参数量更大的模型,期望判断更接近人类","correct":false},{"key":"B","text":"用人工评审建立黄金测试集,定期校准大模型的评分标准","correct":true},{"key":"C","text":"让大模型对同一内容多评几次,取平均分","correct":false},{"key":"D","text":"在评分前对所有回答做标准化处理,统一删减到相同长度","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 661, 'single', '技术负责人说"Agent每一步决策质量取决于我们给它提供了什么信息",他强调的核心理念是?', '[{"key":"A","text":"用更简短的提示词来减少不必要的Token消耗","correct":false},{"key":"B","text":"让模型根据任务需求自己决定需要什么信息","correct":false},{"key":"C","text":"通过持续训练让模型学会更多专业领域的知识","correct":false},{"key":"D","text":"精心组织每一步传递给模型的上下文信息","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 662, 'single', '你打算开发一个智能图像处理应用,用户上传图片后,系统需自动生成对应的多模态描述文 本。以下是架构设计中的几种方案,请选择最佳方案?', '[{"key":"A","text":"用户前端直接调用百炼模型服务生成文本,模型服务将原始图片存入OSS,函数计算FC只负责最 终结果缓存","correct":false},{"key":"B","text":"用户前端上传图片至OSS,函数计算FC直接读取图片内容进行分析,通过数字编解码技术解析文 字信息,保存到OSS","correct":false},{"key":"C","text":"用户前端将图片上传至OSS,触发函数计算FC执行预处理,FC调用百炼模型服务生成描述文本, 最终结果返回前端","correct":true},{"key":"D","text":"用户前端上传图片至函数计算FC,FC调用百炼模型服务生成文本,并将图片和结果统一存入OSS","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 663, 'single', '一家科技公司基于自建向量数据库构建RAG应用。在业务高峰期,该数据库服务经常变慢甚至 中断,需手动重启。为确保高可用和弹性,最合理的架构决策是?', '[{"key":"A","text":"为现有数据库服务器垂直扩容CPU和内存","correct":false},{"key":"B","text":"使用全托管云原生服务如阿里云DashVector","correct":true},{"key":"C","text":"优化Embedding模型以提升检索结果的相关性","correct":false},{"key":"D","text":"基于Kubernetes自建跨可用区的高可用集群","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 664, 'single', '财务小王想使用内部部署的大模型来辅助审计,他发现大模型虽然能指出案例中的问题,却没 有依据今年公司内部新发布的审计规范。他应该要求技术部门如何改进?', '[{"key":"A","text":"改造系统,在生成前从审计规范库中检索并注入流程","correct":true},{"key":"B","text":"部署微调的LLM,训练其掌握公司内部审计规范","correct":false},{"key":"C","text":"增加一个后处理校验层,验证引用条款的版本是否有效","correct":false},{"key":"D","text":"增强提示词,要求模型只参考最新的审计规范版本","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 665, 'single', '一家智能客服系统初期采用了昂贵的旗舰大模型(如GPT-4)。虽然效果很好,但运营发现70% 的用户问题都是“如何登录”、“忘记密码”这类高频简单问题。为了节约API调用成本,团队应该优先 采用那种架构调整?', '[{"key":"A","text":"选择价格更低的API服务套餐","correct":false},{"key":"B","text":"微调旗舰大模型,使其能更快地回答这些高频问题","correct":false},{"key":"C","text":"限制每位用户的日均提问次数,并对超出部分进行收费","correct":false},{"key":"D","text":"先用轻量级模型识别意图进行任务路由,对复杂问题调用旗舰模型","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 666, 'single', '订票Agent成功率60%,意图识别95%、API调用98%,但最终确认环节常出错。只看最终指标难 定位问题。需要什么评测方式?', '[{"key":"A","text":"同时上线新旧两个版本做A/B测试","correct":false},{"key":"B","text":"把Agent的执行过程拆开,每个步骤单独设置评测指标","correct":true},{"key":"C","text":"收集更多用户的订票请求样本来扩大测试规模","correct":false},{"key":"D","text":"给用户发满意度问卷收集反馈","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 667, 'single', '客服系统需判断问题类型:退款转售后组,技术转技术组,投诉转客诉组。如何设计?', '[{"key":"A","text":"把三个组合并成一个全能客服组","correct":false},{"key":"B","text":"让三个组同时处理每个问题,取最快的回复","correct":false},{"key":"C","text":"先识别问题类型,再路由到对应的组","correct":true},{"key":"D","text":"按固定顺序让三个组依次处理","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 668, 'single', '多个Agent像开会讨论一样头脑风暴,互相补充、质疑、完善,没有明确领导者。这种协作方式 的特点是?', '[{"key":"A","text":"有一个总控Agent负责分配任务和汇总结果","correct":false},{"key":"B","text":"各Agent地位平等,相互激发,共同迭代完善方案","correct":true},{"key":"C","text":"根据讨论主题把任务路由给最擅长的Agent","correct":false},{"key":"D","text":"每个Agent只能看到自己的输入,无法获取他人观点","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 669, 'single', '某企业内部知识库RAG系统上线后,产品经理反映搜索“报销流程”返回的是“出差申请”相关的内 容。经过分析,发现是因为这两个概念在文档中经常一起出现。以下哪种优化手段最有可能解决这 个问题?', '[{"key":"A","text":"增加一个意图识别前置环节,将“报销流程”和“出差申请”区分开","correct":true},{"key":"B","text":"提高向量检索的Top K值","correct":false},{"key":"C","text":"更换更大参数量的大模型","correct":false},{"key":"D","text":"提高temperature参数","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 670, 'single', '你在开发一个内部系统,希望能够自动处理员工的请求:“我的投影仪故障了,请安排维修并通 知下午会议改线上”。以下哪种技术方案有效,且能尽量减少人力投入?', '[{"key":"A","text":"通过大模型判断接单人,自动将任务指派给接单人,通知其创建维修工单并调整会议","correct":false},{"key":"B","text":"识别请求中的关键字(如“投影仪故障”“会议改线上”),匹配规则系统后调用API完成任务","correct":false},{"key":"C","text":"通过提示词引导大模型拆解任务为多步骤,然后自动调用维修系统和会议系统API完成操作","correct":true}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 671, 'single', '场景:你需要大模型分析一篇新闻文章的情感倾向(正面/负面/中性)。在零样本(Zero-Shot) 设置下,以下哪个提示词最合适?', '[{"key":"A","text":"\\"总结这篇文章。\\"","correct":false},{"key":"B","text":"\\"这篇文章的情感是正面的、负面的还是中性的?只输出一个词:正面、负面或中性。\\"","correct":true},{"key":"C","text":"\\"写一篇读后感。\\"","correct":false},{"key":"D","text":"\\"把文章翻译成英文。\\"","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 672, 'single', '场景:你需要大模型阅读一份财务报表,并回答关于公司营收和利润的详细问题。该报表长度 超过了模型的上下文窗口。以下哪种RAG中的处理方式最合理?', '[{"key":"A","text":"放弃回答","correct":false},{"key":"B","text":"将整个报表强行输入模型","correct":false},{"key":"C","text":"将报表按章节或段落切分,根据问题检索最相关的片段,再基于这些片段生成答案","correct":true},{"key":"D","text":"让模型自己想象报表内容","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 673, 'single', '场景:你正在构建一个代码助手,需要大模型根据自然语言描述生成SQL查询语句。为了保证生 成代码的基本正确性,除了优化提示词,以下哪种后续步骤是必要的?', '[{"key":"A","text":"直接在生产环境运行生成的SQL","correct":false},{"key":"B","text":"在安全的测试环境中对生成的SQL进行语法检查和结果验证","correct":true},{"key":"C","text":"相信模型总是生成正确代码","correct":false},{"key":"D","text":"要求用户手动重写SQL","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 674, 'single', '场景:你正在开发一个学习助手应用,需要大模型根据教科书内容生成练习题。初始提示词下 生成的题目难度不一。为了生成符合特定难度(例如“初中二年级水平”)的题目,以下哪种提示词改 进最有效?', '[{"key":"A","text":"\\"生成更多题目。\\"","correct":false},{"key":"B","text":"\\"生成容易的题目。\\"","correct":false},{"key":"C","text":"\\"请生成5道适合初中二年级学生水平的数学选择题,考察一元一次方程,难度适中。\\"","correct":true},{"key":"D","text":"\\"把题目翻译成英文。\\"","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 675, 'single', '场景:你正在为一个电商平台开发一个产品描述生成器。初始提示词是“生成一个手机的产品描 述”,但输出过于通用。为了生成更具吸引力和营销效果的描述,你应该如何改进提示词?', '[{"key":"A","text":"\\"生成一个长的手机描述\\"","correct":false},{"key":"B","text":"\\"假设你是一位顶尖的营销文案专家,为目标用户是年轻科技爱好者的旗舰手机创作一段吸引人的 产品描述,突出其摄像功能和电池续航。\\"","correct":true},{"key":"C","text":"\\"列出手机的所有参数\\"","correct":false},{"key":"D","text":"\\"用英文写描述\\"","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 676, 'single', '场景:在一个客服对话中,用户表达非常愤怒和不满。你希望大模型生成的回复能够体现共情 (Empathy),先安抚用户情绪,再解决问题。以下哪个提示词引导最有效?', '[{"key":"A","text":"\\"解决问题。\\"","correct":false},{"key":"B","text":"\\"告诉用户冷静下来。\\"","correct":false},{"key":"C","text":"\\"首先对用户遇到的不便表示理解和歉意,安抚其情绪,然后,针对用户提出的具体问题,提供清 晰的解决方案。\\"","correct":true},{"key":"D","text":"\\"忽略用户情绪。\\"","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 677, 'single', '大模型应用在部署后,持续监控以下哪个指标对于了解服务健康和用户体验最为关键?', '[{"key":"A","text":"模型的训练损失","correct":false},{"key":"B","text":"API的延迟(Latency)和错误率(Error Rate)","correct":true},{"key":"C","text":"研究论文的引用数","correct":false},{"key":"D","text":"训练数据的大小","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 678, 'single', '大模型应用在处理用户输入时,需要考虑注入攻击(Prompt Injection)的风险。以下哪种做法有 助于降低这种风险?', '[{"key":"A","text":"完全信任用户的输入,直接拼接至提示词中","correct":false},{"key":"B","text":"对用户输入进行严格的过滤和清洗,分离指令和数据","correct":true},{"key":"C","text":"使用更复杂的模型","correct":false},{"key":"D","text":"增加提示词的长度","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 679, 'single', '大模型在处理数学计算问题时,直接给出错误答案的概率较高。以下哪种提示技巧被证明能有 效提升这类问题的推理准确性?', '[{"key":"A","text":"让模型输出更短的答案","correct":false},{"key":"B","text":"思维链(Chain-of-Thought, CoT)提示","correct":true},{"key":"C","text":"要求模型用图形回答","correct":false},{"key":"D","text":"提供不相关的示例","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 680, 'single', '大模型在处理需要多步推理的任务时,思维链(CoT)提示的核心思想是?', '[{"key":"A","text":"让模型输出更短的答案","correct":false},{"key":"B","text":"要求模型生成推理的中间步骤","correct":true},{"key":"C","text":"提供更多的训练数据","correct":false},{"key":"D","text":"使用更快的硬件","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 681, 'single', '大模型在处理一些需要实时信息的任务(如查询当前天气)时,存在固有的局限性,因为其训 练数据具有截止日期。解决这个问题的最佳技术方案是?', '[{"key":"A","text":"定期使用最新数据重新预训练模型","correct":false},{"key":"B","text":"通过检索增强生成,让模型能够访问外部实时API或数据库","correct":true},{"key":"C","text":"要求用户只询问训练数据截止日期之前的问题","correct":false},{"key":"D","text":"让模型根据已有知识推测最新情况","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 682, 'single', '当大模型被应用于生成法律合同条款时,最重要的注意事项是?', '[{"key":"A","text":"生成速度要尽可能快","correct":false},{"key":"B","text":"生成的文本必须由人类法律专家进行审查和定稿","correct":true},{"key":"C","text":"使用尽可能复杂的法律术语以体现专业性","correct":false},{"key":"D","text":"确保生成内容在所有司法管辖区都自动有效","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 683, 'single', '当大模型生成的内容包含不希望出现的偏见时,以下哪种方法属于提示工程层面的缓解策略?', '[{"key":"A","text":"忽略此问题","correct":false},{"key":"B","text":"在提示词中明确要求模型避免生成带有偏见的内容","correct":true},{"key":"C","text":"重新训练模型的所有参数","correct":false},{"key":"D","text":"只使用英文数据","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 684, 'single', '当大模型生成的内容存在事实性错误时,以下哪种方法通常不能直接用于纠正这些错误?', '[{"key":"A","text":"通过RAG提供准确的外部知识","correct":false},{"key":"B","text":"在提示词中要求模型进行自我验证","correct":false},{"key":"C","text":"增加模型的温度(temperature)设置","correct":true},{"key":"D","text":"使用思维链(Chain-of-Thought)提示引导模型逐步推理","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 685, 'single', '当使用大模型进行情感分析任务时,发现模型对于“讽刺”类文本的识别准确率很低。以下哪种方 法最有可能专门提升模型在此类文本上的表现?', '[{"key":"A","text":"增加通用情感分析训练数据的数量","correct":false},{"key":"B","text":"在提示词中要求模型“特别注意识别讽刺”","correct":false},{"key":"C","text":"收集更多带有“讽刺”标签的数据,并对模型进行针对性微调","correct":true},{"key":"D","text":"降低模型输出的置信度阈值","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 686, 'single', '当使用大模型进行数据标注时,发现其标注结果存在一定的噪声(不一致或错误)。以下哪种 做法可以提升最终标注质量?', '[{"key":"A","text":"完全依赖单一模型的单次输出","correct":false},{"key":"B","text":"使用多个模型进行标注,并采用投票或一致性检查机制","correct":true},{"key":"C","text":"忽略噪声,直接使用","correct":false},{"key":"D","text":"手动标注所有数据,完全不使用模型","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 687, 'single', '当使用大模型进行数据标注以辅助训练更小的专用模型时,发现小模型在测试集上的性能达到 了一个瓶颈。怀疑是大模型生成的标注数据中存在一定噪声。以下哪种做法对突破这个瓶颈最没有 帮助?', '[{"key":"A","text":"对大模型生成的标注数据进行人工抽样检查和质量清洗","correct":false},{"key":"B","text":"设计更复杂的提示词,提升大模型标注的准确率","correct":false},{"key":"C","text":"完全放弃大模型标注,重新进行纯人工标注","correct":true},{"key":"D","text":"使用多种大模型进行标注,并采用投票法确定最终标签","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 688, 'single', '当使用大模型进行文本摘要时,你希望摘要能够忠实反映原文的主要观点,避免添加原文不存 在的信息。以下哪个提示词要求最相关?', '[{"key":"A","text":"\\"生成一个有趣的摘要。\\"","correct":false},{"key":"B","text":"\\"生成一个详细的摘要,可以添加你的知识。\\"","correct":false},{"key":"C","text":"\\"基于原文生成一个简洁的摘要,不要引入原文之外的信息。\\"","correct":true},{"key":"D","text":"\\"用列表形式输出。\\"","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 689, 'single', '对于创意写作任务(如写诗、写故事),为了增加输出的多样性和新颖性,通常可以调整以下 哪个生成参数?', '[{"key":"A","text":"降低温度(temperature)","correct":false},{"key":"B","text":"提高温度(temperature)","correct":true},{"key":"C","text":"使用贪婪解码(Greedy Decoding)","correct":false},{"key":"D","text":"设置Top-p(nucleus sampling)为0","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 690, 'single', '对于开源大模型,以下哪个因素在商业应用时需要重点考虑?', '[{"key":"A","text":"模型发布的论文数量","correct":false},{"key":"B","text":"模型的开源协议(License)对商业使用的限制","correct":true},{"key":"C","text":"模型的创建者的国籍","correct":false},{"key":"D","text":"模型的名字","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 691, 'single', '对于需要高并发处理的企业级大模型应用,以下哪种部署方式通常能提供更好的弹性和可扩展 性?', '[{"key":"A","text":"在单台本地服务器上部署","correct":false},{"key":"B","text":"使用云服务商提供的托管大模型服务(如阿里灵积)","correct":true},{"key":"C","text":"在开发者的笔记本电脑上部署","correct":false},{"key":"D","text":"不进行部署","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 692, 'single', '对于需要高事实准确性的问答系统,以下哪种架构组合通常能提供更好的效果?', '[{"key":"A","text":"纯生成式模型","correct":false},{"key":"B","text":"RAG(检索增强生成)","correct":true},{"key":"C","text":"模型微调后直接使用","correct":false},{"key":"D","text":"提高温度参数","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 693, 'single', '对于中文文本处理任务,在选择大模型时,以下哪个特性最为重要?', '[{"key":"A","text":"模型参数量","correct":false},{"key":"B","text":"模型在中文语料上的训练情况和表现","correct":true},{"key":"C","text":"模型的推理速度","correct":false},{"key":"D","text":"模型的开源协议","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 694, 'single', '关于RAG(检索增强生成)技术的核心作用,以下描述最准确的是?', '[{"key":"A","text":"提升大模型的训练效率,减少训练数据量","correct":false},{"key":"B","text":"扩展大模型的知识边界,解决“知识过时”和“领域知识缺失”问题","correct":true},{"key":"C","text":"降低大模型的推理延迟,提升响应速度","correct":false},{"key":"D","text":"增强大模型的多模态处理能力(如文本、图像、语音)","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 695, 'single', '关于阿里云PAI平台的“模型服务化”功能,以下描述正确的是?', '[{"key":"A","text":"仅支持阿里云自研大模型的服务化部署","correct":false},{"key":"B","text":"可将自定义训练的模型封装为RESTful API或gRPC服务","correct":true},{"key":"C","text":"模型服务化后,无法进行性能监控和扩容","correct":false},{"key":"D","text":"服务化部署必须依赖本地服务器,无法使用云端资源","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 696, 'single', '关于大模型“幻觉(Hallucination)”现象,以下描述错误的是?', '[{"key":"A","text":"幻觉指模型生成与事实不符、无中生有的内容","correct":false},{"key":"B","text":"增加提示词中的事实性约束可减少幻觉","correct":false},{"key":"C","text":"所有大模型的幻觉率都是固定的,无法通过技术手段降低","correct":true},{"key":"D","text":"RAG技术通过检索真实数据,可有效抑制幻觉","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 697, 'single', '关于大模型“零样本学习(Zero-shot Learning)”的描述,正确的是?', '[{"key":"A","text":"指模型在训练时使用零个数据","correct":false},{"key":"B","text":"指模型在未见过某类任务/数据的情况下,仅通过提示词即可完成该任务","correct":true},{"key":"C","text":"零样本学习的准确率一定高于少样本学习","correct":false},{"key":"D","text":"所有大模型都不支持零样本学习","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 698, 'single', '关于大模型“流式输出(Streaming Output)”的描述,正确的是?', '[{"key":"A","text":"流式输出能减少模型的总生成时间","correct":false},{"key":"B","text":"流式输出将生成结果按token逐段返回,提升用户实时体验","correct":true},{"key":"C","text":"流式输出仅支持文本生成,不支持其他任务","correct":false},{"key":"D","text":"所有大模型API都默认开启流式输出","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 699, 'single', '关于大模型“上下文污染(Context Contamination)”的描述,正确的是?', '[{"key":"A","text":"指模型的上下文窗口大小超过限制","correct":false},{"key":"B","text":"指在多用户共享模型服务时,某用户的输入/输出被其他用户的上下文干扰","correct":true},{"key":"C","text":"上下文污染仅发生在本地部署的模型中","correct":false},{"key":"D","text":"增加模型参数数量可完全避免上下文污染","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 700, 'single', '关于大模型与传统机器学习模型的区别,以下描述正确的是?', '[{"key":"A","text":"大模型无需标注数据即可完成任务,传统机器学习模型必须依赖标注数据","correct":false},{"key":"B","text":"大模型的泛化能力更强,能处理未见过的任务类型,传统机器学习模型通常仅适配特定任务","correct":true},{"key":"C","text":"大模型的推理速度一定比传统机器学习模型快","correct":false},{"key":"D","text":"大模型不需要特征工程,传统机器学习模型也不需要特征工程","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 701, 'single', '假设你正在使用大模型生成一篇关于“人工智能伦理”的技术文章,但初始输出过于泛泛而谈。为 了获得更深入、结构更清晰的内容,以下哪种提示策略最合适?', '[{"key":"A","text":"要求模型用英文输出","correct":false},{"key":"B","text":"提供文章的大纲和关键点","correct":true},{"key":"C","text":"限制输出长度在100字以内","correct":false},{"key":"D","text":"让模型重复生成多次","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 702, 'single', '开发者部署大模型时,发现服务器GPU显存不足,无法加载完整模型。以下哪种解决方案最便 捷?', '[{"key":"A","text":"更换显存更大的GPU服务器","correct":false},{"key":"B","text":"使用模型量化(Quantization)技术,降低显存占用","correct":true},{"key":"C","text":"对模型进行蒸馏,减少参数数量","correct":false},{"key":"D","text":"拆分模型,分布式部署在多台服务器","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 703, 'single', '开发者在调用阿里云大模型API时,返回“Token超出限制”的错误。以下哪种解决措施最直接?', '[{"key":"A","text":"更换更大参数的模型","correct":false},{"key":"B","text":"减少输入文本的长度,或拆分输入内容为多次调用","correct":true},{"key":"C","text":"增加API调用的并发数","correct":false},{"key":"D","text":"延长API调用的超时时间","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 704, 'single', '开发者在调用大模型API时,希望控制模型生成内容的“创新性”,避免生成过于保守或过于夸张 的内容。以下哪种API参数最适配?', '[{"key":"A","text":"max_tokens(最大输出长度)","correct":false},{"key":"B","text":"temperature(温度参数)","correct":true},{"key":"C","text":"top_p(核采样参数)","correct":false},{"key":"D","text":"stop(停止词)","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 705, 'single', '开发者在使用RAG技术时,需将文档存入向量数据库。以下哪种操作是向量数据库的核心步 骤?', '[{"key":"A","text":"将文档原文直接存储,不做任何处理","correct":false},{"key":"B","text":"使用大模型将文档转换为向量(Embedding)后存储","correct":true},{"key":"C","text":"对文档进行分词后,存储分词结果","correct":false},{"key":"D","text":"将文档转换为PDF格式后存储","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 706, 'single', '开发者在使用RAG技术时,选择“余弦相似度(Cosine Similarity)”作为向量匹配算法。其核心 作用是?', '[{"key":"A","text":"计算两个向量的大小差异","correct":false},{"key":"B","text":"计算两个向量的方向相似度,判断文本语义相关性","correct":true},{"key":"C","text":"统计两个文本的关键词重合数量","correct":false},{"key":"D","text":"检测向量中的异常值","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 707, 'single', '开发者在使用阿里云大模型进行微调时,发现微调后的模型性能反而下降(如问答准确率降 低、生成内容偏离需求)。以下哪种原因最不可能?', '[{"key":"A","text":"微调数据量过少,导致模型过拟合","correct":false},{"key":"B","text":"微调数据存在大量错误标注或噪声","correct":false},{"key":"C","text":"微调参数设置不当(如学习率过高)","correct":false},{"key":"D","text":"微调时使用了与基础模型相同的预训练数据","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 708, 'single', '开发者在使用大模型进行文本分类任务时,发现模型对小众类别(如“投诉 - 物流延误”)的识别 准确率极低。以下哪种优化方案最适配?', '[{"key":"A","text":"增加所有类别的训练数据量","correct":false},{"key":"B","text":"采用少样本提示,提供小众类别的多个示例","correct":true},{"key":"C","text":"更换参数更大的大模型","correct":false},{"key":"D","text":"简化分类任务,合并小众类别","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 709, 'single', '开发者优化RAG应用时,发现检索到的文本段与用户问题相关性较低,导致模型回答准确率下 降。以下哪种优化措施最有效?', '[{"key":"A","text":"降低检索的相似度阈值","correct":false},{"key":"B","text":"减少向量数据库中的文本段数量","correct":false},{"key":"C","text":"优化文本分块策略,采用更小的分块粒度并保留上下文信息","correct":true},{"key":"D","text":"增加模型的推理步数","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 710, 'single', '某电商平台开发智能推荐系统,要求根据用户实时浏览的商品,推荐“相似风格、价格区间相近” 的商品。以下哪种技术方案最适配?', '[{"key":"A","text":"仅使用大模型生成推荐文案,不涉及商品匹配","correct":false},{"key":"B","text":"使用向量数据库存储商品特征向量,通过相似度检索推荐相似商品","correct":true},{"key":"C","text":"让大模型直接输出推荐商品列表,不依赖外部数据","correct":false},{"key":"D","text":"基于用户历史订单数据,不考虑实时浏览行为","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 711, 'single', '某电商平台使用大模型开发智能售后系统,用户提问“我的订单显示已发货,但3天还没收到, 怎么办?”。以下哪种提示词设计能让模型生成最实用的回答?', '[{"key":"A","text":"\\"回答用户的问题\\"","correct":false},{"key":"B","text":"\\"用户订单发货3天未收到,给出解决方案\\"","correct":false},{"key":"C","text":"\\"作为电商售后客服,针对用户订单发货3天未送达的问题,按以下步骤回复:1.安抚用户情绪;2. 建议用户查看物流轨迹;3.提供人工客服介入渠道;4.承诺处理时效\\"","correct":true},{"key":"D","text":"\\"详细说明订单未送达的可能原因\\"","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 712, 'single', '某电商平台使用大模型生成商品标题,但发现生成的标题缺乏吸引力。以下哪种提示词构造方 式最有可能提升标题质量?', '[{"key":"A","text":"\\"生成一个关于{产品名称}的标题\\"","correct":false},{"key":"B","text":"\\"作为电商营销专家,为{产品名称}创作3个吸引点击的爆款标题\\"","correct":true},{"key":"C","text":"\\"请写一个{产品名称}的标题\\"","correct":false},{"key":"D","text":"\\"标题: {产品名称}\\"","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 713, 'single', '某电商平台使用大模型优化商品搜索功能,用户搜索“夏天穿的透气鞋子”,要求模型能理解“夏 天”“透气”是核心需求,并匹配相关商品。以下哪种提示优化最有效?', '[{"key":"A","text":"仅输入用户搜索词,不做任何处理","correct":false},{"key":"B","text":"在提示词中明确标注核心需求:“用户搜索意图:季节(夏天)、功能(透气)、品类(鞋子), 请基于核心需求匹配商品,优先展示符合‘透气材质+夏季款式’的商品”","correct":true},{"key":"C","text":"提供大量类似搜索词的示例,让模型学习","correct":false},{"key":"D","text":"更换更大参数的模型","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 714, 'single', '某电商平台希望利用大模型自动生成商品描述。为了确保生成的描述风格统一、包含关键卖点 且符合平台规范,以下哪种提示工程策略组合最有可能达成目标?', '[{"key":"A","text":"仅提供商品名称和类别","correct":false},{"key":"B","text":"提供详细的商品属性列表、风格示例和禁止项说明","correct":true},{"key":"C","text":"要求模型分步骤生成描述","correct":false},{"key":"D","text":"仅指定目标受众","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 715, 'single', '某电商推荐系统需要生成个性化产品描述。以下哪种方法最能体现个性化?', '[{"key":"A","text":"生成统一的产品描述","correct":false},{"key":"B","text":"基于用户历史行为生成描述","correct":true},{"key":"C","text":"随机生成不同风格的描述","correct":false},{"key":"D","text":"使用模板填充","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 716, 'single', '某公司开发一款智能教育产品,要求模型能批改学生的数学应用题,不仅给出对错,还需分析 错误原因。以下哪种技术方案最适配?', '[{"key":"A","text":"让模型直接输出“对”或“错”","correct":false},{"key":"B","text":"采用思维链提示,引导模型分步推导正确答案,再对比学生答案分析错误","correct":true},{"key":"C","text":"提供大量学生错题示例,让模型学习错误类型","correct":false},{"key":"D","text":"调用数学计算API,仅验证结果对错","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 717, 'single', '某公司开发一款智能文案生成工具,要求模型生成的文案符合品牌调性(如专业、简洁),且 避免生成重复内容。以下哪种提示策略最有效?', '[{"key":"A","text":"仅在首次调用时说明品牌调性,后续不再提及","correct":false},{"key":"B","text":"在每次提示中明确品牌调性要求,并添加“禁止重复生成相同表述”的约束","correct":true},{"key":"C","text":"提供100条符合品牌调性的文案作为示例,让模型学习","correct":false},{"key":"D","text":"选用参数更大的模型,依赖其自身能力生成符合要求的文案","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 718, 'single', '场景:你希望大模型帮助你进行头脑风暴,为一个环保项目想10个宣传口号。初始输出有些重 复。为了获得更多样化的想法,以下哪种方法最不值得尝试?', '[{"key":"A","text":"在提示词中要求“从不同角度思考,如节约资源、保护动物、气候变化等”","correct":false},{"key":"B","text":"提高生成时的温度(Temperature)参数","correct":false},{"key":"C","text":"多次运行相同的提示词","correct":false},{"key":"D","text":"要求模型只输出一个最好的口号","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 719, 'single', '在使用大模型生成广告文案时,以下元素中的哪一个可以用来提供上下文特定背景信息?', '[{"key":"A","text":"上下文","correct":true},{"key":"B","text":"样例","correct":false},{"key":"C","text":"输出格式","correct":false},{"key":"D","text":"角色","correct":false},{"key":"E","text":"任务目标","correct":false},{"key":"F","text":"受众","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 720, 'single', '以下哪种情况适合使用视觉模型进行深层次解析?', '[{"key":"A","text":"包含复杂图表和不规则信息的图片。","correct":true},{"key":"B","text":"包含简单文字的命令行截图。","correct":false},{"key":"C","text":"已经通过DashScopeParse解析的普通文本段落。","correct":false},{"key":"D","text":"包含清晰文本的文本截图。","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 721, 'single', '如果某一款大模型无法完全理解复杂图片中的信息,应该采取什么策略?', '[{"key":"A","text":"放弃使用该图片。","correct":false},{"key":"B","text":"使用通义千问API的视觉理解模型对图片进行更深层次的分析。","correct":true},{"key":"C","text":"手动提取图片信息。","correct":false},{"key":"D","text":"使用其他开源OCR工具再次尝试识别。","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 722, 'single', '在提示词构建中,用于提供任务背景信息的要素是什么?', '[{"key":"A","text":"输出格式","correct":false},{"key":"B","text":"角色","correct":false},{"key":"C","text":"用户年龄","correct":false},{"key":"D","text":"上下文","correct":true},{"key":"E","text":"受众","correct":false},{"key":"F","text":"输入数据","correct":false}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 723, 'single', '以下哪行代码用于从存储中加载索引?', '[{"key":"A","text":"index = VectorStoreIndex.from_documents(documents)","correct":false},{"key":"B","text":"index = load_index_from_storage(storage_context)","correct":true},{"key":"C","text":"query_engine = index.as_query_engine()","correct":false},{"key":"D","text":"index.storage_context.persist(persist_dir=PERSIST_DIR)","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 724, 'single', '在等待运行(Run)完成时,调用的函数是什么?', '[{"key":"A","text":"dashscope.Runs.wait()","correct":true},{"key":"B","text":"dashscope.Runs.list()","correct":false},{"key":"C","text":"dashscope.Runs.delete()","correct":false},{"key":"D","text":"dashscope.Runs.create()","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 725, 'single', '以下哪种分隔符最适合用于区分不同的对话轮次或历史记录?', '[{"key":"A","text":"用户:你好 机器人:你好,有什么可以帮你的?","correct":false},{"key":"B","text":"...==用户==你好==机器人==你好,有什么可以帮你的?...","correct":true},{"key":"C","text":">你好>你好,有什么可以帮你的?","correct":false},{"key":"D","text":"<<用户你好<<机器人你好,有什么可以帮你的?","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 726, 'single', '下列代码实现了什么功能? import tensorflow as tf tokenizer = tf.keras.preprocessing.text.Tokenizer() tokenizer.fit_on_texts(texts) sequences = tokenizer.texts_to_sequences(texts)', '[{"key":"A","text":"文本情感分析","correct":false},{"key":"B","text":"文本生成","correct":false},{"key":"C","text":"文本分词/标记化并转换为序列","correct":true},{"key":"D","text":"文本关键词抽取","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 727, 'single', '通过Assistant API的Assistant类创建的智能体对象,可以通过设置下列哪个参数来设定概率质量 的阈值,从而在保持多样性的同时提高输出质量?', '[{"key":"A","text":"max_tokens","correct":false},{"key":"B","text":"temperature","correct":false},{"key":"C","text":"tools","correct":false},{"key":"D","text":"top_p","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 728, 'single', '以下代码中,哪个参数用于指定大模型的名称?', '[{"key":"A","text":"base_url","correct":false},{"key":"B","text":"model","correct":true},{"key":"C","text":"messages","correct":false},{"key":"D","text":"api_key","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 729, 'single', '在使用LlamaIndex构建RAG系统时,如果文档未进行拆分,直接将整个文档作为上下文输入大 模型,可能会导致什么问题?', '[{"key":"A","text":"检索结果更全面,包含更多信息。","correct":false},{"key":"B","text":"系统运行速度更快,效率更高。","correct":false},{"key":"C","text":"检索结果更精准,相关性更高。","correct":false},{"key":"D","text":"大模型无法处理,导致程序报错或返回不相关内容。","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 730, 'single', '大模型在处理下列哪种数据时,能有效地区分并归类具有相似特性的数据点?', '[{"key":"A","text":"天气记录数据,需识别季节性温度变化模式。","correct":false},{"key":"B","text":"用户查询与相应答案的匹配度评估。","correct":false},{"key":"C","text":"一个公司的年度销售数据,需计算总销售额。","correct":false},{"key":"D","text":"社交媒体帖子,根据内容将其分类到不同的兴趣小组。","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 731, 'single', '在设计RAG方案时,以下哪个原则不是必须遵循的?', '[{"key":"A","text":"根据任务的复杂度和需求选择合适的模型和工具。","correct":false},{"key":"B","text":"确保外部知识库的信息准确性和可靠性。","correct":false},{"key":"C","text":"将复杂任务拆分成多个子任务,分别进行处理。","correct":false},{"key":"D","text":"尽可能减少大模型的调用次数,以降低成本。","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 732, 'single', '如果你需要识别生产流水线上产品的缺陷率是否有显著变化,应该考虑使用大模型的哪种能 力?', '[{"key":"A","text":"应用聚类算法,对不同类型的缺陷进行分类。","correct":false},{"key":"B","text":"执行线性回归,建立缺陷率与时间的预测模型。","correct":false},{"key":"C","text":"进行精确的描述性统计分析,如计算平均缺陷率。","correct":false},{"key":"D","text":"通过趋势分析,识别缺陷率随时间的变化趋势。","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 733, 'single', '这段代码中,如何修改召回文本段的个数? print("正在创建索引...") index = VectorStoreIndex.from_documents([document]) print("正在创建提问引擎...") query_engine = index.as_query_engine(streaming=True) print("正在生成回复...") streaming_response = query_engine.query("需求分析使用的工具是什么?") print("回答是:\\n") streaming_response.print_response_stream()', '[{"key":"A","text":"as_query_engine中指定similarity_top_k","correct":true},{"key":"B","text":"from_documents中指定similarity_top_k","correct":false},{"key":"C","text":"streaming_response.print_response_stream中指定similarity_top_k","correct":false},{"key":"D","text":"query_engine.query中指定similarity_top_k","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 734, 'single', '以下哪些代码片段能够成功创建一个使用qwen-max模型且具备夸克搜索工具的智能体?', '[{"key":"A","text":"assistant = dashscope.Assistants.create(model=''qwen-max'', tools=[{''type'': ''code_interpreter''}])","correct":false},{"key":"B","text":"assistant = dashscope.Assistants.create(model=''qwen-max'', tools={''quark_search'': True})","correct":false},{"key":"C","text":"assistant = dashscope.Assistants.create(model=''qwen-max'', quark_search=True)","correct":false},{"key":"D","text":"assistant = dashscope.Assistants.create(model=''qwen-7b'', tools=[{''type'': ''quark_search''}])","correct":false},{"key":"E","text":"assistant = dashscope.Assistants.create(model=''qwen-max'', tools=[{''type'': ''quark_search''}])","correct":true},{"key":"F","text":"assistant = dashscope.Assistants.create(model=''qwen-max'', tools=[''quark_search''])","correct":false}]', 'E') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 735, 'single', '在回答“某技术方案的优点”时,模型常常忘记关键点,原因是相关信息分散在多个切片中。为提 升回答的完整度,你会优先尝试哪种方案?', '[{"key":"A","text":"将所有文档整合成一段文本","correct":false},{"key":"B","text":"提高大模型的presence_penalty","correct":false},{"key":"C","text":"使用滑动窗口作为切片策略","correct":true},{"key":"D","text":"固定随机种子seed=42","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 736, 'single', '某公司计划上线HR问答机器人,其知识库中包含公司各级各类资料。在内部审核中,评审人员 指出,机器人在越级泄露资料的风险。为在当前架构下最直接且可靠地修复此访问控制漏洞,应优 先采取哪项技术措施?', '[{"key":"A","text":"设置知识库访问权限,在RAG检索时,基于用户授权返回知识块。","correct":true},{"key":"B","text":"在API出口部署内容过滤器,对所有响应强制进行关键词扫描。","correct":false},{"key":"C","text":"微调语言模型,增强其角色扮演能力,使其主动拒绝回答敏感问题。","correct":false},{"key":"D","text":"对本次泄露事件进行全面的复盘,并建立相应的应急响应和处罚机制。","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 737, 'single', '公司有查天气、查股票、查快递三个API,希望用户用自然语言提问时模型能自动判断该调哪个 API、参数填什么。如何实现?', '[{"key":"A","text":"开发查天气、查股票、查快递的工具供模型调用","correct":true},{"key":"B","text":"把三个API的文档全部塞进系统提示词","correct":false},{"key":"C","text":"让用户在界面上手动选择要调用的API","correct":false},{"key":"D","text":"为每种问法写一条if_else规则","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 738, 'single', '一款集成了多个学术数据库API的AI研究助手,最近频繁因参数格式错误(如date格式应为 YYYY-MM-DD,author_id应为整数)而调用失败,导致运营成本激增。最有效的改进策略是什么?', '[{"key":"A","text":"部署更精细的日志与追踪系统,以量化分析每种参数错误的具体模式","correct":false},{"key":"B","text":"收集失败调用日志对大模型进行微调,增强其生成正确参数的能力","correct":false},{"key":"C","text":"强制采用基于统一Schema的API规范,并加入前置的自动化校验机制","correct":true},{"key":"D","text":"在系统提示词中为每个工具补充详细的自然语言描述和正反参数示例","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 739, 'single', '你希望对于同一个提示词,让大模型每次都尽最大可能返回相同结果,最关键的一步是?', '[{"key":"A","text":"固定seed","correct":true},{"key":"B","text":"固定temperature","correct":false},{"key":"C","text":"固定top_p","correct":false},{"key":"D","text":"设置stream=False","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 740, 'single', '「总管」Agent拆解任务分配给市场、技术、竞品三个Agent执行后汇总。这种组织方式的特点 是?', '[{"key":"A","text":"有明确的上下级关系,由总管协调分工","correct":true},{"key":"B","text":"各Agent完全独立运行,互不知晓对方存在","correct":false},{"key":"C","text":"所有Agent地位平等,自由讨论达成共识","correct":false},{"key":"D","text":"各Agent按固定顺序依次处理同一份数据","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 741, 'single', '财务Agent自动识别发票并发起转账,财务总监担心识别错误。如何设计才能让他放心?', '[{"key":"A","text":"用多个不同的模型分别判断,少数服从多数","correct":false},{"key":"B","text":"设定金额阈值,超过阈值的转账需经人工审批","correct":true},{"key":"C","text":"把转账任务拆分成多个小额分批执行","correct":false},{"key":"D","text":"给Agent配置更详细的财务规则知识库","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 742, 'single', '旅行规划Agent查完机票发现超预算,自动去查高铁票价替代。这种行为体现了什么特点?', '[{"key":"A","text":"同时并行执行多个独立任务","correct":false},{"key":"B","text":"根据上一步结果动态决定下一步行动","correct":true},{"key":"C","text":"按照预设的固定步骤依次执行","correct":false},{"key":"D","text":"将任务分配给多个专家分别处理","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 743, 'single', '当RAG应用无法检索到相关信息时,大模型常常编造答案。以下哪种方法相对更有助于减少 「幻觉」?', '[{"key":"A","text":"提高temperature","correct":false},{"key":"B","text":"使用更小参数量的模型","correct":false},{"key":"C","text":"提高top_p","correct":false},{"key":"D","text":"提示词明确要求:信息不足则回答无法解答","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 744, 'single', '在RAG系统中,检索器(Retriever)的性能至关重要。以下哪个指标通常用于评估检索器的效 果?', '[{"key":"A","text":"生成文本的流畅度","correct":false},{"key":"B","text":"检索到的文档与查询的相似度得分","correct":true},{"key":"C","text":"生成答案的长度","correct":false},{"key":"D","text":"模型的推理时间","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 745, 'single', '在RAG系统中,检索到的文档片段通常需要被截断以适应模型的上下文窗口。如果被截断的文 档恰好丢失了最关键的信息,最可能导致以下哪种后果?', '[{"key":"A","text":"模型无法生成任何回答","correct":false},{"key":"B","text":"模型基于不完整的上下文,生成不准确或错误的回答","correct":true},{"key":"C","text":"检索速度显著提升","correct":false},{"key":"D","text":"模型的推理能力会自动增强以弥补信息缺失","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 746, 'single', '在RAG流程中,将原始文档拆分成较小片段(Chunking)时,以下哪种策略通常有助于保持上 下文的完整性?', '[{"key":"A","text":"使用固定的、极小的字符数进行重叠分割","correct":false},{"key":"B","text":"完全不做分割,将整个文档作为一簇片段","correct":false},{"key":"C","text":"使用重叠分割,并尽量在句子或段落边界处进行切分","correct":true},{"key":"D","text":"随机地从文档中抽取句子组成片段","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 747, 'single', '在Few-Shot Learning中,提供给模型的示例的主要作用是什么?', '[{"key":"A","text":"增加模型的参数","correct":false},{"key":"B","text":"展示任务的输入输出格式,让模型通过上下文学习","correct":true},{"key":"C","text":"减少计算资源消耗","correct":false},{"key":"D","text":"防止模型过拟合","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 748, 'single', '在Few-Shot Learning中,提供的示例应该是怎样的?', '[{"key":"A","text":"数量越多越好","correct":false},{"key":"B","text":"与目标任务无关","correct":false},{"key":"C","text":"清晰、相关,并能代表期望的输入输出格式","correct":true},{"key":"D","text":"全部来自同一个领域","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 749, 'single', '在优化RAG系统的检索器时,发现当前使用的稠密向量检索器(Dense Retriever)对于某些包含 特定实体名称的查询效果不好,而传统的关键词检索(如BM25)在这些查询上表现更好。以下哪种 架构改进最能兼顾两种检索方式的优势?', '[{"key":"A","text":"完全用关键词检索替换稠密向量检索","correct":false},{"key":"B","text":"采用混合检索(Hybrid Retrieval)策略,合并两种检索方式的结果","correct":true},{"key":"C","text":"增加稠密向量检索的维度","correct":false},{"key":"D","text":"要求用户避免使用实体名称进行查询","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 750, 'single', '在训练大模型时,以下哪种技术主要用于防止过拟合?', '[{"key":"A","text":"增加模型参数","correct":false},{"key":"B","text":"早停(Early Stopping)","correct":true},{"key":"C","text":"使用更小的学习率","correct":false},{"key":"D","text":"增加训练轮数(Epochs)","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 751, 'single', '在微调过程中,学习率(Learning Rate)是一个关键超参数。如果学习率设置得过高,可能会导 致什么现象?', '[{"key":"A","text":"模型训练速度过慢","correct":false},{"key":"B","text":"模型无法收敛,损失值震荡甚至发散","correct":true},{"key":"C","text":"模型完美拟合数据","correct":false},{"key":"D","text":"没有影响","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 752, 'single', '在微调大模型以适应某个垂直领域时,观察到验证集上的损失在几个轮次后就不再显著下降。 以下哪种做法不太可能带来进一步的性能提升?', '[{"key":"A","text":"尝试调整学习率或使用不同的优化器","correct":false},{"key":"B","text":"检查并清洗训练数据中的噪声","correct":false},{"key":"C","text":"显著增加模型的深度和宽度","correct":true},{"key":"D","text":"为模型提供该领域更丰富的上下文信息(如通过RAG)","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 753, 'single', '在微调大模型时,学习率是一个关键的超参数。以下关于学习率设置的描述,哪一项是错误 的?', '[{"key":"A","text":"学习率过大可能导致训练过程不稳定甚至发散","correct":false},{"key":"B","text":"学习率过小可能导致训练速度过慢,或陷入局部最优","correct":false},{"key":"C","text":"学习率通常需要根据模型大小、任务和数据量进行调整","correct":false},{"key":"D","text":"在整个训练过程中,学习率必须始终保持不变","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 754, 'single', '在微调大模型时,通常使用哪种优化算法?', '[{"key":"A","text":"随机梯度下降(SGD)及其变体(如AdamW)","correct":true},{"key":"B","text":"冒泡排序","correct":false},{"key":"C","text":"快速傅里叶变换","correct":false},{"key":"D","text":"迪杰斯特拉算法","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 755, 'single', '在微调大模型时,通常会将数据集划分为训练集、验证集和测试集。验证集的主要作用是?', '[{"key":"A","text":"用于模型的最终训练","correct":false},{"key":"B","text":"用于调整超参数和监控训练过程,防止过拟合","correct":true},{"key":"C","text":"用于发布模型的最终性能指标","correct":false},{"key":"D","text":"用于数据预处理","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 756, 'single', '在微调大模型时,如果训练损失下降得很慢,可能的原因不包括以下哪项?', '[{"key":"A","text":"学习率设置过低","correct":false},{"key":"B","text":"模型已经接近收敛","correct":false},{"key":"C","text":"训练数据量过大","correct":true},{"key":"D","text":"优化器选择不当","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 757, 'single', '在提示工程中,“角色扮演”(Role-Playing)技巧的主要目的是什么?', '[{"key":"A","text":"降低模型计算成本","correct":false},{"key":"B","text":"让模型以特定身份、口吻或视角来生成内容,使其更符合应用场景","correct":true},{"key":"C","text":"增加输出的随机性","correct":false},{"key":"D","text":"改变模型的结构","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 758, 'single', '在使用大模型进行文本续写时,希望通过控制“top-p”核采样参数来平衡生成内容的多样性和质 量。以下关于top-p采样的描述,哪一项是正确的?', '[{"key":"A","text":"top-p值越大,候选词集合越小,生成越集中","correct":false},{"key":"B","text":"top-p值越小,候选词集合越大,生成越多样","correct":false},{"key":"C","text":"top-p采样是从概率最高的候选词中动态选择集合,直至其累积概率超过阈值p","correct":true},{"key":"D","text":"top-p采样总是比top-k采样效果差","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 759, 'single', '在使用大模型进行文本生成时,可以通过调整“温度”超参数来控制生成结果的随机性。以下关于 “温度”设置的描述,哪一项是正确的?', '[{"key":"A","text":"温度值设置越高,生成的内容越保守、可预测","correct":false},{"key":"B","text":"温度值设置越低,生成的内容越多样、有创造性","correct":false},{"key":"C","text":"对于需要事实准确性的任务,通常建议设置较低的温度","correct":true},{"key":"D","text":"温度参数对生成内容的质量没有影响","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 760, 'single', '在使用大模型进行文本分类任务时,发现模型在某个小众类别上的准确率始终很低。已经尝试 过提供更多该类别的样本进行微调,但效果改善有限。接下来,最应该优先考虑以下哪种分析方 向?', '[{"key":"A","text":"检查训练数据中该小众类别的样本是否存在标注噪声或质量问题","correct":true},{"key":"B","text":"增加模型的总参数量","correct":false},{"key":"C","text":"更换另一种完全不同架构的模型","correct":false},{"key":"D","text":"放弃该小众类别,将其合并到其他类别中","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 761, 'single', '在使用大模型进行文本翻译时,为了获得更地道的翻译结果,而不仅仅是字面对译,以下哪种 提示词改进更有帮助?', '[{"key":"A","text":"“逐词翻译。”","correct":false},{"key":"B","text":"“翻译以下文本,注重传达原文的含义和风格,使其在目标语言中读起来自然流畅。”","correct":true},{"key":"C","text":"“用拼音输出。”","correct":false},{"key":"D","text":"“翻译得慢一些。”","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 762, 'single', '在设计和开发大模型应用时,“负责任的AI”实践要求我们关注模型的公平性。以下哪项措施对 于改善模型公平性的帮助最直接?', '[{"key":"A","text":"使用尽可能多的训练数据,不考虑数据来源","correct":false},{"key":"B","text":"在模型评估阶段,分析模型在不同人口统计群体上的性能差异","correct":true},{"key":"C","text":"只使用来自单一文化背景的数据进行训练以确保一致性","correct":false},{"key":"D","text":"追求模型在整体数据集上的最高准确率,忽略子群体表现","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 763, 'single', '在评估文本生成任务时,ROUGE指标主要用于衡量什么?', '[{"key":"A","text":"代码的正确性","correct":false},{"key":"B","text":"摘要质量(与参考摘要的重合度)","correct":true},{"key":"C","text":"图像的清晰度","correct":false},{"key":"D","text":"模型的推理速度","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 764, 'single', '在评估大模型生成文本的质量时,以下哪个指标主要用于衡量生成文本与参考文本在词序和词 组匹配上的相似度?', '[{"key":"A","text":"ROUGE","correct":false},{"key":"B","text":"BLEU","correct":true},{"key":"C","text":"Perplexity","correct":false},{"key":"D","text":"F1 Score","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 765, 'single', '在评估大模型生成内容的安全性时,以下哪个方面通常不属于核心的评估维度?', '[{"key":"A","text":"是否包含歧视性或偏见性内容","correct":false},{"key":"B","text":"是否泄露了训练数据中的隐私信息","correct":false},{"key":"C","text":"生成的文本是否足够长和详细","correct":true},{"key":"D","text":"是否遵从了预设的道德和法律准则","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 766, 'single', '在评估大模型生成的文本时,“流畅性”主要衡量的是?', '[{"key":"A","text":"文本内容的事实准确性","correct":false},{"key":"B","text":"文本是否符合语法、读起来是否自然通顺","correct":true},{"key":"C","text":"文本是否包含了所有必要的信息","correct":false},{"key":"D","text":"文本的篇幅长度","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 767, 'single', '在评估大模型的多轮对话能力时,以下哪个指标通常不适合用来衡量对话质量?', '[{"key":"A","text":"对话连贯性","correct":false},{"key":"B","text":"任务完成率","correct":false},{"key":"C","text":"单轮响应时间","correct":true},{"key":"D","text":"用户满意度","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 768, 'single', '在评估大模型的安全性时,以下哪种测试主要用于检查模型是否容易生成有害、偏见或不安全 的内容?', '[{"key":"A","text":"性能基准测试(如MMLU)","correct":false},{"key":"B","text":"红队测试(Red Teaming)","correct":true},{"key":"C","text":"单元测试","correct":false},{"key":"D","text":"压力测试","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 769, 'single', '在利用大模型进行文本摘要时,希望摘要能够突出原文中的特定信息(例如,只关注财务数 据)。以下哪种提示词设计最有可能达成目标?', '[{"key":"A","text":"“请为上面的文本生成一个摘要。”","correct":false},{"key":"B","text":"“请生成一个摘要,重点总结文中提到的所有财务数据和指标。”","correct":true},{"key":"C","text":"“请生成一个非常简短的摘要。”","correct":false},{"key":"D","text":"“请用英文生成摘要。”","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 770, 'single', '在开发智能排班系统时,需要模型理解复杂的工作规则。以下哪种方法最可靠?', '[{"key":"A","text":"完全依赖模型的推理能力","correct":false},{"key":"B","text":"将规则明确编码到提示词中","correct":false},{"key":"C","text":"使用规则引擎处理规则,模型处理异常情况","correct":true},{"key":"D","text":"人工处理所有排班","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 771, 'single', '在开发智能客服系统时,发现大模型在处理用户投诉时语气过于机械,缺乏同理心。以下哪种 方法最能改善这一问题?', '[{"key":"A","text":"增加训练数据量","correct":false},{"key":"B","text":"在提示词中明确要求“使用 empathetic 的语气”","correct":false},{"key":"C","text":"使用更强大的模型版本","correct":false},{"key":"D","text":"提供角色设定“你是一位富有同理心的客服专家”","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 772, 'single', '在开发语音助手时,需要将语音转换为文本后再处理。以下哪种架构最合理?', '[{"key":"A","text":"端到端的语音到文本模型","correct":false},{"key":"B","text":"语音识别+文本处理流水线","correct":true},{"key":"C","text":"纯语音处理模型","correct":false},{"key":"D","text":"规则-based语音处理","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 773, 'single', '在开发语音生成系统时,需要控制生成语音的情感色彩。以下哪种方法最有效?', '[{"key":"A","text":"使用中性语音","correct":false},{"key":"B","text":"在文本提示中指定情感标签","correct":true},{"key":"C","text":"随机选择情感","correct":false},{"key":"D","text":"让用户选择情感","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 774, 'single', '在开发医疗咨询系统时,需要确保建议的专业性和安全性。以下哪种方法最重要?', '[{"key":"A","text":"使用最新的模型版本","correct":false},{"key":"B","text":"基于权威医学资料构建RAG系统","correct":true},{"key":"C","text":"要求模型“提供专业建议”","correct":false},{"key":"D","text":"在免责声明中说明局限性","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 775, 'single', '在开发一个文本分类应用时,你拥有一个包含10个类别、每个类别1000条数据的数据集。为了 快速验证大模型在零样本(Zero-Shot)下的分类能力,你应该如何设计提示词?', '[{"key":"A","text":"提供所有10000条数据作为上下文","correct":false},{"key":"B","text":"在提示词中列出10个类别的名称,并要求模型将输入文本分类到其中之一","correct":true},{"key":"C","text":"先对模型进行全量微调","correct":false},{"key":"D","text":"只使用一个类别的数据","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 776, 'single', '在开发一个基于RAG的问答系统时,发现系统对于一些需要多步推理的复杂问题回答效果不 佳。初步分析认为是检索到的文档片段过于零散,缺乏足够的上下文信息来支持复杂推理。以下哪 种改进措施最有可能解决这个问题?', '[{"key":"A","text":"提高检索阶段向量搜索的相似度阈值","correct":false},{"key":"B","text":"在检索后,对召回到的多个相关文档片段进行摘要融合,生成更连贯的上下文","correct":true},{"key":"C","text":"增加检索的文档片段数量","correct":false},{"key":"D","text":"要求用户将复杂问题拆分成多个简单问题","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 777, 'single', '在开发一个基于大模型的智能客服系统时,发现模型在处理用户复杂多轮对话时经常偏离主 题。为了提高对话的连贯性和相关性,以下哪种方法最有效?', '[{"key":"A","text":"增加模型的参数量","correct":false},{"key":"B","text":"在提示词中明确对话历史和当前焦点","correct":true},{"key":"C","text":"使用更快的推理硬件","correct":false},{"key":"D","text":"减少训练数据量","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 778, 'single', '在开发一个多轮对话系统时,希望模型能够记住并在后续对话中引用之前讨论过的关键信息。 以下哪种方法通常用于实现这种上下文记忆能力?', '[{"key":"A","text":"要求用户在每轮对话中重复重要信息","correct":false},{"key":"B","text":"将整个对话历史(或其摘要)作为后续对话轮次的输入上下文","correct":true},{"key":"C","text":"只将最新的用户查询输入给模型","correct":false},{"key":"D","text":"训练一个独立的模型来专门记忆信息","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 779, 'single', '在开发文本分类系统时,需要处理类别不平衡问题。以下哪种方法最有效?', '[{"key":"A","text":"使用准确率作为评估指标","correct":false},{"key":"B","text":"对少数类样本过采样","correct":true},{"key":"C","text":"忽略类别不平衡","correct":false},{"key":"D","text":"只关注多数类","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 780, 'single', '在开发多语言客服系统时,需要实时翻译用户查询。以下哪种架构最合适?', '[{"key":"A","text":"单一多语言模型","correct":false},{"key":"B","text":"语言检测+专用翻译模型+处理模型","correct":true},{"key":"C","text":"要求用户使用英语","correct":false},{"key":"D","text":"人工翻译所有查询","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 781, 'single', '在开发多语言翻译应用时,需要处理专业术语的准确翻译。以下哪种方法最有效?', '[{"key":"A","text":"完全依赖模型的翻译能力","correct":false},{"key":"B","text":"构建专业术语词典并通过RAG集成","correct":true},{"key":"C","text":"要求用户提供术语解释","correct":false},{"key":"D","text":"使用在线翻译API","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 782, 'single', '在开发多模态应用时,需要模型根据图像生成描述文字。以下哪种架构最合适?', '[{"key":"A","text":"纯文本模型","correct":false},{"key":"B","text":"视觉-语言多模态模型","correct":true},{"key":"C","text":"两个独立的文本和视觉模型","correct":false},{"key":"D","text":"规则-based系统","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 783, 'single', '在开发多轮对话系统时,希望模型能够记住上下文中的重要信息。以下哪种方法最有效?', '[{"key":"A","text":"在每轮对话中重复重要信息","correct":false},{"key":"B","text":"使用具有上下文窗口的模型","correct":false},{"key":"C","text":"要求用户在每轮对话中重复关键信息","correct":false},{"key":"D","text":"开发外部记忆机制来存储重要信息","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 784, 'single', '在开发代码生成工具时,需要确保代码符合特定编码规范。以下哪种方法最有效?', '[{"key":"A","text":"事后使用lint工具检查","correct":false},{"key":"B","text":"在提示词中明确编码规范要求","correct":true},{"key":"C","text":"依赖模型遵循规范","correct":false},{"key":"D","text":"人工重构所有代码","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 785, 'single', '在开发创意写作应用时,希望模型能够生成更加新颖的内容。以下哪种参数设置最合适?', '[{"key":"A","text":"低温度(low temperature)","correct":false},{"key":"B","text":"高温度(high temperature)","correct":true},{"key":"C","text":"顶层P(top-p)为0.1","correct":false},{"key":"D","text":"重复惩罚为0","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 786, 'single', '在开发创意设计助手时,需要生成新颖的设计概念。以下哪种提示词技术最有效?', '[{"key":"A","text":"直接要求“创新设计”","correct":false},{"key":"B","text":"使用类比和隐喻激发创意","correct":true},{"key":"C","text":"要求遵循现有设计规范","correct":false},{"key":"D","text":"使用模板化设计","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 787, 'single', '在规划一个大模型项目的技术栈时,选择使用API而不是本地部署开源模型,其主要优势通常不 包括以下哪项?', '[{"key":"A","text":"更低的初始部署和运维成本","correct":false},{"key":"B","text":"无需管理底层基础设施","correct":false},{"key":"C","text":"可以获得模型供应商提供的最新模型版本","correct":false},{"key":"D","text":"对模型数据和权重拥有完全的物理控制权","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 788, 'single', '在管理大模型应用的开发生命周期时,持续对提示词进行版本控制和管理的主要目的是?', '[{"key":"A","text":"增加开发的复杂性","correct":false},{"key":"B","text":"跟踪提示词的变更历史,便于迭代、测试和回滚","correct":true},{"key":"C","text":"防止其他开发者看到提示词内容","correct":false},{"key":"D","text":"减少模型API的调用次数","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 789, 'single', '在构建智能数据分析系统时,需要模型从表格数据中提取洞察。以下哪种提示词最有效?', '[{"key":"A","text":"\\"分析这个表格\\"","correct":false},{"key":"B","text":"\\"作为数据分析师,从该表格中识别3个关键趋势和2个异常点\\"","correct":true},{"key":"C","text":"\\"看这个数据\\"","correct":false},{"key":"D","text":"\\"表格分析\\"","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 790, 'single', '在构建一个RAG(检索增强生成)应用时,你发现检索器返回的文档片段虽然相关,但生成答 案时仍然包含事实错误。以下哪种改进措施最可能解决这个问题?', '[{"key":"A","text":"提高检索器的相似度阈值","correct":false},{"key":"B","text":"增加生成模型的温度(temperature)参数","correct":false},{"key":"C","text":"在提示词中明确要求模型仅基于检索到的上下文作答","correct":true},{"key":"D","text":"使用更短的文档片段","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 791, 'single', '在构建一个知识问答系统时,如果领域知识更新频繁(如科技新闻),以下哪种架构最能适应 这种变化?', '[{"key":"A","text":"只使用一个静态微调过的模型","correct":false},{"key":"B","text":"RAG(检索增强生成)结合一个可实时更新的知识库","correct":true},{"key":"C","text":"完全依赖模型的内置知识","correct":false},{"key":"D","text":"定期重新微调模型","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 792, 'single', '在构建一个支持多种语言的国际化大模型应用时,发现模型在某些低资源语言上的翻译质量明 显较差。以下哪种方法对改善这种情况的帮助最小?', '[{"key":"A","text":"为这些低资源语言收集更多的平行语料数据","correct":false},{"key":"B","text":"利用迁移学习,从高资源语言模型中迁移知识","correct":false},{"key":"C","text":"使用反向翻译数据增强技术","correct":false},{"key":"D","text":"提高模型在处理高资源语言时的温度参数","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 793, 'single', '在构建一个面向儿童的教育类大模型应用时,以下哪项安全措施是至关重要的?', '[{"key":"A","text":"确保生成内容的语言和知识深度适合儿童认知水平","correct":true},{"key":"B","text":"生成内容必须包含复杂的逻辑推理以挑战儿童","correct":false},{"key":"C","text":"屏蔽所有可能由用户输入的不当词汇,但无需过滤模型输出","correct":false},{"key":"D","text":"鼓励儿童与模型分享个人身份信息以提供个性化服务","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 794, 'single', '在构建一个基于大模型的智能客服系统时,发现模型在处理特定领域的专业问题时,回答不够 准确。为了提高模型在该领域的表现,以下哪种方法最为直接有效?', '[{"key":"A","text":"增加模型的通用知识训练数据","correct":false},{"key":"B","text":"使用思维链提示方法引导模型推理","correct":false},{"key":"C","text":"通过微调使模型适配领域知识","correct":true},{"key":"D","text":"要求用户提供更详细的问题描述","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 795, 'single', '在构建一个多轮对话系统时,为了保持对话的一致性(例如,用户之前提到的偏好信息),以 下哪种方法最有效?', '[{"key":"A","text":"每轮对话都作为独立的请求,不保留历史","correct":false},{"key":"B","text":"在系统提示词中设定一个固定的角色","correct":false},{"key":"C","text":"将整个对话历史作为上下文传递给模型","correct":true},{"key":"D","text":"要求用户每次重复重要信息","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 796, 'single', '在构建一个对话系统时,你希望模型能记住较长的对话历史。以下哪种方法最直接有效?', '[{"key":"A","text":"每次都将完整的对话历史作为上下文输入模型","correct":false},{"key":"B","text":"只输入最后一条用户消息","correct":false},{"key":"C","text":"训练一个更大的模型","correct":false},{"key":"D","text":"使用一个外部数据库来存储和检索相关对话历史","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 797, 'single', '在构建一个代码生成助手时,希望模型生成的代码不仅是功能正确的,还应具备良好的可读性 和符合团队的编码规范。以下哪种方法对实现这一目标帮助最小?', '[{"key":"A","text":"在提示词中明确要求代码风格(如PEP 8 for Python)","correct":false},{"key":"B","text":"在微调数据中精心挑选符合规范的代码样本","correct":false},{"key":"C","text":"要求模型在生成代码后,自行进行代码审查并输出修改建议","correct":true},{"key":"D","text":"在提示词中提供少量符合规范的代码示例","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 798, 'single', '在构建学术研究助手时,需要模型提供最新研究进展。以下哪种方法最有效?', '[{"key":"A","text":"依赖模型训练时知识","correct":false},{"key":"B","text":"通过RAG接入学术数据库","correct":true},{"key":"C","text":"要求模型基于常识推理","correct":false},{"key":"D","text":"人工搜索最新研究","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 799, 'single', '在构建学术论文助手时,需要模型引用特定格式的参考文献。以下哪种方法最有效?', '[{"key":"A","text":"要求模型“使用APA格式”","correct":false},{"key":"B","text":"提供APA格式的引用示例","correct":true},{"key":"C","text":"使用专门的引用生成工具","correct":false},{"key":"D","text":"要求模型自行决定格式","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 800, 'single', '在构建文档摘要应用时,发现大模型生成的摘要遗漏了重要信息。以下哪种改进措施最有效?', '[{"key":"A","text":"降低生成温度(temperature)参数","correct":false},{"key":"B","text":"在提示词中明确要求“必须包含文档中的关键数据和结论”","correct":false},{"key":"C","text":"增加生成的最大token数","correct":false},{"key":"D","text":"使用思维链提示要求模型先识别关键点再生成摘要","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 801, 'single', '在构建客户反馈分析系统时,需要识别情感倾向和关键问题。以下哪种方法最全面?', '[{"key":"A","text":"只分析情感","correct":false},{"key":"B","text":"只识别具体问题","correct":false},{"key":"C","text":"结合情感分析和关键主题提取","correct":true},{"key":"D","text":"简单分类反馈类型","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 802, 'single', '在构建技术文档问答系统时,需要确保答案的准确性。以下哪种方法最可靠?', '[{"key":"A","text":"完全依赖模型知识","correct":false},{"key":"B","text":"基于文档检索生成答案","correct":true},{"key":"C","text":"要求用户提供答案","correct":false},{"key":"D","text":"人工回答所有问题","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 803, 'single', '在构建技术文档翻译系统时,需要保持术语一致性。以下哪种方法最有效?', '[{"key":"A","text":"每次翻译都重新生成术语","correct":false},{"key":"B","text":"构建术语库并在翻译中强制使用","correct":true},{"key":"C","text":"依赖模型的术语一致性","correct":false},{"key":"D","text":"人工后期统一术语","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 804, 'single', '在构建法律文档分析系统时,需要模型识别文档中的关键条款。以下哪种提示词工程方法最有 效?', '[{"key":"A","text":"\\"分析这个法律文档\\"","correct":false},{"key":"B","text":"\\"作为法律专家,识别本协议中的5个关键责任条款和3个限制条款\\"","correct":true},{"key":"C","text":"\\"找出重要内容\\"","correct":false},{"key":"D","text":"\\"总结这个文档\\"","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 805, 'single', '在构建法律合同生成系统时,需要确保条款的合法性和完整性。以下哪种方法最可靠?', '[{"key":"A","text":"完全依赖模型生成","correct":false},{"key":"B","text":"使用模板+模型填充","correct":false},{"key":"C","text":"律师审核所有合同","correct":false},{"key":"D","text":"结合法律知识库和模型生成","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 806, 'single', '在构建代码生成应用时,发现生成的代码缺乏注释。以下哪种方法能确保代码包含充分注释?', '[{"key":"A","text":"要求模型“写注释”","correct":false},{"key":"B","text":"在提示词中明确要求“为每段重要代码添加详细注释”","correct":true},{"key":"C","text":"事后手动添加注释","correct":false},{"key":"D","text":"使用代码审查工具","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 807, 'single', '在构建代码审查工具时,需要模型识别潜在的安全漏洞。以下哪种提示词最有效?', '[{"key":"A","text":"\\"检查这段代码\\"","correct":false},{"key":"B","text":"\\"作为安全专家,识别这段代码中的安全漏洞和潜在风险\\"","correct":true},{"key":"C","text":"\\"找代码问题\\"","correct":false},{"key":"D","text":"\\"代码审查\\"","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 808, 'single', '在构建财务报表分析系统时,需要确保数字计算的绝对准确。以下哪种方法最可靠?', '[{"key":"A","text":"完全依赖模型的计算能力","correct":false},{"key":"B","text":"要求模型分步计算并验证","correct":false},{"key":"C","text":"集成外部计算引擎","correct":true},{"key":"D","text":"人工重新计算所有数字","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 809, 'single', '在对比全参数微调(Full Fine-tuning)与参数高效微调(PEFT,如LoRA)时,以下关于PEFT优 势的描述中,哪一项是不准确的?', '[{"key":"A","text":"PEFT通常需要更少的计算资源和存储空间","correct":false},{"key":"B","text":"PEFT能够有效避免灾难性遗忘问题","correct":false},{"key":"C","text":"PEFT的训练速度总是远快于全参数微调","correct":true},{"key":"D","text":"PEFT产出的模型权重文件通常更小","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 810, 'single', '在对比零样本学习与少样本学习时,以下关于少样本学习优势的描述,哪一项是正确的?', '[{"key":"A","text":"少样本学习完全不需要任何示例","correct":false},{"key":"B","text":"少样本学习通常比零样本学习具有更高的准确率,因为它提供了任务范例","correct":true},{"key":"C","text":"少样本学习总是比微调模型的效果更好","correct":false},{"key":"D","text":"少样本学习可以避免任何形式的模型偏见","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 811, 'single', '在进行大模型微调时,观察到随着训练轮次的增加,模型在训练集上的损失持续下降,但在验 证集上的损失先下降后开始上升。这种现象通常表明了什么?', '[{"key":"A","text":"模型处于欠拟合状态","correct":false},{"key":"B","text":"模型达到了最佳拟合状态","correct":false},{"key":"C","text":"模型出现了过拟合","correct":true},{"key":"D","text":"训练数据和验证数据分布完全一致","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 812, 'single', '在大模型应用开发中,“模型微调(Fine-tuning)”的核心目的是?', '[{"key":"A","text":"降低模型的推理延迟","correct":false},{"key":"B","text":"让模型适配特定领域或任务的需求","correct":true},{"key":"C","text":"增加模型的上下文窗口大小","correct":false},{"key":"D","text":"减少模型的参数数量","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 813, 'single', '在大模型提示工程中,“要求模型先分析问题类型,再拆解解决步骤,最后输出结论”的提示方 式,对应的核心技术是?', '[{"key":"A","text":"少样本提示","correct":false},{"key":"B","text":"思维链(Chain-of-Thought)提示","correct":true},{"key":"C","text":"角色设定提示","correct":false},{"key":"D","text":"指令优化提示","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 814, 'single', '在大模型提示工程中,“给模型赋予具体角色(如‘你是资深产品经理’)”的核心目的是?', '[{"key":"A","text":"增加提示词的长度,提升模型重视程度","correct":false},{"key":"B","text":"引导模型从特定角色的视角思考,输出符合角色专业度的内容","correct":true},{"key":"C","text":"限制模型的输出格式,避免生成过长文本","correct":false},{"key":"D","text":"让模型记住该角色,后续对话无需再次设定","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 815, 'single', '在大模型提示词设计中,“明确任务目标、限定输出格式、提供核心约束条件”属于哪种提示原 则?', '[{"key":"A","text":"简洁性原则","correct":false},{"key":"B","text":"具体性原则","correct":true},{"key":"C","text":"多样性原则","correct":false},{"key":"D","text":"开放性原则","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 816, 'single', '在大模型多轮对话应用开发中,为避免模型遗忘前文信息,以下哪种做法最有效?', '[{"key":"A","text":"每轮对话仅向模型输入当前用户问题","correct":false},{"key":"B","text":"将历史对话记录与当前问题一起作为输入传递给模型","correct":true},{"key":"C","text":"要求模型每轮对话后总结前文要点并保存","correct":false},{"key":"D","text":"减少每轮对话的输出文本长度","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 817, 'single', '在大模型部署中,“模型并行(Model Parallelism)”的核心作用是?', '[{"key":"A","text":"减少模型的参数数量","correct":false},{"key":"B","text":"将模型拆分到多个设备上运行,解决单设备显存不足问题","correct":true},{"key":"C","text":"提高模型的训练数据量","correct":false},{"key":"D","text":"加快模型的文本生成速度,与显存无关","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 818, 'single', '在大模型部署中,“动态批处理(Dynamic Batching)”的核心优势是?', '[{"key":"A","text":"减少模型的参数数量","correct":false},{"key":"B","text":"提高GPU利用率,在高并发场景下提升整体吞吐量","correct":true},{"key":"C","text":"降低模型的推理延迟,确保单次请求响应更快","correct":false},{"key":"D","text":"避免模型出现幻觉现象","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 819, 'single', '在部署一个大模型API服务时,为了应对可能的高并发请求,保证服务的稳定性,以下哪项措施 是最重要的?', '[{"key":"A","text":"为每个请求分配尽可能多的计算资源","correct":false},{"key":"B","text":"实现请求队列、限流和自动扩缩容机制","correct":true},{"key":"C","text":"要求用户一次性提交所有请求,减少连接次数","correct":false},{"key":"D","text":"关闭所有日志记录以提升性能","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 820, 'single', '在部署大模型服务时,以下哪个因素通常对API的吞吐量(Throughput)有正面影响?', '[{"key":"A","text":"增加批量大小(Batch Size)","correct":true},{"key":"B","text":"使用自回归解码(Autoregressive Decoding)一次生成一个token","correct":false},{"key":"C","text":"提高生成文本的最大长度","correct":false},{"key":"D","text":"使用更高的浮点精度(如FP32)","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 821, 'single', '在部署大模型服务时,为了降低API调用的延迟,以下哪种方法通常最有效?', '[{"key":"A","text":"使用量化(Quantization)技术减少模型大小","correct":true},{"key":"B","text":"增加模型的层数","correct":false},{"key":"C","text":"提高生成文本的最大长度","correct":false},{"key":"D","text":"使用更复杂的解码策略","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 822, 'single', '在比较不同大模型的性能时,以下哪个基准(Benchmark)主要用于评估模型的通用知识和推理 能力?', '[{"key":"A","text":"MMLU(Massive Multitask Language Understanding)","correct":true},{"key":"B","text":"BLEU","correct":false},{"key":"C","text":"ROUGE","correct":false},{"key":"D","text":"Perplexity","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 823, 'single', '以下哪种措施不能有效降低大模型的“幻觉”现象?', '[{"key":"A","text":"在提示词中明确要求模型“基于事实回答,不确定时说明”","correct":false},{"key":"B","text":"使用RAG技术,让模型基于检索到的真实数据生成回答","correct":false},{"key":"C","text":"增加模型的参数数量,提升模型复杂度","correct":true},{"key":"D","text":"对模型生成的回答进行事实校验,过滤错误信息","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 824, 'single', '以下哪种场景最适合使用大模型的“函数调用(Function Calling)”能力?', '[{"key":"A","text":"生成一篇产品推广文案","correct":false},{"key":"B","text":"解答用户的历史常识问题","correct":false},{"key":"C","text":"根据用户提供的地址查询实时天气数据","correct":true},{"key":"D","text":"总结一篇长篇学术论文","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 825, 'single', '以下哪种场景不适合使用大模型的“少样本提示(Few-shot Prompting)”?', '[{"key":"A","text":"企业内部特定流程的问答(如“报销流程”,可提供3个示例)","correct":false},{"key":"B","text":"小众领域的文本分类(如“芯片故障类型分类”,样本稀缺)","correct":false},{"key":"C","text":"通用常识问答(如“地球的半径是多少”,无需示例)","correct":true},{"key":"D","text":"特定格式的文本生成(如“按固定模板生成会议纪要”,提供1个示例)","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 826, 'single', '以下关于大模型“LoRA微调”的描述,错误的是?', '[{"key":"A","text":"LoRA是一种轻量化微调方法,仅训练少量新增参数","correct":false},{"key":"B","text":"LoRA微调无需加载完整模型权重,可降低显存占用","correct":true},{"key":"C","text":"LoRA微调后的模型可与基础模型权重合并,便于部署","correct":false},{"key":"D","text":"LoRA微调适用于数据量较少、计算资源有限的场景","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 827, 'single', '以下关于大模型“上下文窗口”的描述,正确的是?', '[{"key":"A","text":"上下文窗口越大,模型的推理速度越快","correct":false},{"key":"B","text":"上下文窗口的大小决定了模型能处理的最大输入文本长度","correct":true},{"key":"C","text":"所有大模型的上下文窗口大小都是固定不可调整的","correct":false},{"key":"D","text":"上下文窗口仅影响模型的文本生成能力,不影响理解能力","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 828, 'single', '以下关于阿里云通义千问“模型微调”功能的描述,错误的是?', '[{"key":"A","text":"支持基于通义千问基础模型,使用企业私有数据进行微调","correct":false},{"key":"B","text":"微调后的模型可直接部署为API服务供应用调用","correct":false},{"key":"C","text":"微调过程中无需关注数据格式,任意格式数据均可直接使用","correct":true},{"key":"D","text":"支持LoRA等轻量化微调方法,降低计算资源消耗","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 829, 'single', '以下关于RAG技术中“文本分块”的描述,错误的是?', '[{"key":"A","text":"文本分块过大会导致检索时包含过多冗余信息,降低相关性(如将整本书作为一个分块,检索“某 章节细节”时会带入大量无关内容)","correct":false},{"key":"B","text":"文本分块过小会导致上下文丢失,无法理解文本完整含义(如将一句话拆分为多个分块,丢失句 子逻辑)","correct":false},{"key":"C","text":"所有类型的文档(如小说、合同、学术论文)都应采用相同的分块大小(如固定500字符/块)","correct":true},{"key":"D","text":"分块时可保留文本的元数据(如章节名、页码、作者),便于检索后定位原文来源","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 830, 'single', '一个RAG系统在回答用户关于最新事件的问题时,由于知识库更新不及时,无法提供正确答 案。在不改变知识库更新频率的前提下,以下哪种技术手段能最有效地改善这种情况?', '[{"key":"A","text":"使用模型的内部知识来回答问题,完全忽略检索到的文档","correct":false},{"key":"B","text":"在系统提示词中教导模型:如果检索到的文档信息不足或过时,可以结合自身知识进行回答,并 说明信息来源","correct":true},{"key":"C","text":"强制模型必须基于检索到的文档进行回答,即使答案是错误的","correct":false},{"key":"D","text":"对用户查询进行修改,使其更匹配知识库中的旧内容","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 831, 'single', '一个RAG系统在处理用户查询时,有时会返回与查询相关但已经过时的信息,因为知识库中的 部分文档未被及时更新。在不立即更新全部知识库文档的前提下,以下哪种方法能最有效地缓解这 个问题?', '[{"key":"A","text":"在提示词中明确告知模型知识截止日期,并让其谨慎回答时效性问题","correct":true},{"key":"B","text":"完全依赖模型自身的知识来回答所有问题,绕过检索模块","correct":false},{"key":"C","text":"对用户查询进行改写,去除可能涉及时效性的关键词","correct":false},{"key":"D","text":"降低检索模块的召回率,只返回相似度极高的文档","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 832, 'single', '一个智能写作助手在生成新闻稿时,有时会虚构一些不存在的引述或数据。从技术层面看,导 致这个问题最可能的原因是?', '[{"key":"A","text":"模型的训练数据中包含了不准确或虚构的信息","correct":true},{"key":"B","text":"用户的提示词写得不够长","correct":false},{"key":"C","text":"模型缺乏足够的创造性","correct":false},{"key":"D","text":"生成长度设置得太短","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 833, 'single', '一个智能客服系统在处理用户投诉时,需要识别用户的情绪状态(如愤怒、焦虑),以便采取 更合适的沟通策略。以下哪种模型应用方式最适合完成这项情绪识别任务?', '[{"key":"A","text":"训练一个全新的、专门用于文本情绪分类的模型","correct":false},{"key":"B","text":"使用通用大模型,并通过提示词要求其直接判断用户情绪","correct":true},{"key":"C","text":"要求用户自行选择其当前情绪状态","correct":false},{"key":"D","text":"忽略用户情绪,只关注问题本身的内容","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 834, 'single', '一个基于大模型的聊天机器人,在开放域对话中有时会表现出前后矛盾的观点。从技术角度 看,导致这种现象的根本原因最可能是?', '[{"key":"A","text":"模型在训练时接触了包含多种不同观点的海量文本数据","correct":true},{"key":"B","text":"用户的提问方式太模糊","correct":false},{"key":"C","text":"模型的上下文长度不够","correct":false},{"key":"D","text":"没有为模型设定一个固定的人格","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 835, 'single', '一个基于大模型的翻译服务,在处理某些小众方言时效果不佳。考虑到收集大量该方言的平行 语料成本很高,以下哪种技术路线更适合快速、低成本地提升该方言的翻译质量?', '[{"key":"A","text":"从头开始训练一个专门针对该方言的翻译模型","correct":false},{"key":"B","text":"采用少量样本提示(Few-shot Prompting)的方法,在翻译请求中提供几个该方言到目标语言的 例句","correct":true},{"key":"C","text":"放弃支持该方言,引导用户使用主流语言","correct":false},{"key":"D","text":"等待通用大模型下一次版本升级,期望其自动改善","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 836, 'single', '一个多模态大模型应用需要处理用户上传的图片并回答相关问题。如果用户上传的是一张模糊 不清的图片,以下哪种处理方式最符合用户体验原则?', '[{"key":"A","text":"强行对模糊图片进行分析,并输出一个可能错误的描述","correct":false},{"key":"B","text":"直接返回“我无法处理图片”的通用错误信息","correct":false},{"key":"C","text":"识别到图片质量问题时,主动告知用户并建议其提供更清晰的图片","correct":true},{"key":"D","text":"忽略图片,只基于文本对话历史进行回答","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 837, 'single', '小王使用大模型来辅助撰写技术博客。他发现模型有时会生成一些看似合理但实际上错误的代 码片段。为了最大限度地降低这种风险,以下哪种做法最有效?', '[{"key":"A","text":"完全信任模型的输出,因为模型拥有海量知识","correct":false},{"key":"B","text":"要求模型只生成文字描述,不生成任何代码","correct":false},{"key":"C","text":"对模型生成的代码,进行必要的人工审查和测试","correct":true},{"key":"D","text":"使用更复杂的提示词,但不对输出做额外验证","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 838, 'single', '为了提升大模型在数学推理问题上的表现,研究者常常使用“思维链”提示方法。这种方法的核心 思想是?', '[{"key":"A","text":"要求模型生成最终答案即可","correct":false},{"key":"B","text":"提供大量的数学公式作为背景知识","correct":false},{"key":"C","text":"引导模型将复杂问题分解为多个中间推理步骤","correct":true},{"key":"D","text":"要求模型必须使用代码来解决问题","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 839, 'single', '为了提升大模型在代码生成任务上的性能,除了提供函数签名和注释外,以下哪种额外的上下 文信息对模型最有帮助?', '[{"key":"A","text":"项目所在的文件目录结构","correct":false},{"key":"B","text":"相关的其他函数或类的代码实现","correct":true},{"key":"C","text":"开发者的编程经验水平","correct":false},{"key":"D","text":"计算机的硬件配置","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 840, 'single', '为了提高大模型在处理长文档时的效率并降低计算成本,以下哪种方法通常被采用?', '[{"key":"A","text":"要求用户将长文档拆分成多个短段落分别提交","correct":false},{"key":"B","text":"使用滑动窗口注意力等机制来减少计算复杂度","correct":true},{"key":"C","text":"增加模型的层数和参数量以提升处理能力","correct":false},{"key":"D","text":"只处理文档的开头和结尾部分","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 841, 'single', '为了让大模型在对话中表现出特定的性格或角色(例如,扮演一个幽默的助手),以下哪种方 法通常能产生最稳定、最一致的角色行为?', '[{"key":"A","text":"在每轮对话的系统提示词中反复强调该角色设定","correct":false},{"key":"B","text":"使用包含该角色对话风格的数据对模型进行微调","correct":true},{"key":"C","text":"要求用户在对话开始时指定期望的角色","correct":false},{"key":"D","text":"让模型根据对话上下文自行推断合适的角色","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 842, 'single', '为了评估一个文本摘要模型的效果,除了使用ROUGE等自动评估指标外,还希望引入人工评 估。以下哪项是人工评估摘要质量时最应该关注的核心维度?', '[{"key":"A","text":"摘要的词汇丰富度","correct":false},{"key":"B","text":"摘要与原文事实的一致性","correct":true},{"key":"C","text":"摘要的句子长度","correct":false},{"key":"D","text":"摘要的排版格式","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 843, 'single', '为了降低大模型应用在特定领域产生有害或偏见内容的风险,以下哪种措施属于“预部署”阶段的 防护手段?', '[{"key":"A","text":"部署实时内容过滤系统","correct":false},{"key":"B","text":"对模型的输出进行人工审核","correct":false},{"key":"C","text":"在模型训练阶段使用经过严格清洗和去偏的数据","correct":true},{"key":"D","text":"设置用户举报和反馈机制","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 844, 'single', '为了防止大模型生成包含暴力等不安全内容,在部署时通常会引入内容安全过滤器。这个过滤 器最可能工作在以下哪个阶段?', '[{"key":"A","text":"在用户输入之前,过滤用户的查询","correct":false},{"key":"B","text":"在模型推理过程中,实时干预模型的下一个token生成","correct":false},{"key":"C","text":"在模型输出最终结果之后,但对用户可见之前","correct":true},{"key":"D","text":"在模型训练完成之后,微调开始之前","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 845, 'single', '你正在设计一个提示词,让大模型扮演一个严格的数学老师。以下哪个提示词片段最能有效地 设定这个角色?', '[{"key":"A","text":"\\"你是一个AI助手。\\"","correct":false},{"key":"B","text":"\\"请回答这个数学问题。\\"","correct":false},{"key":"C","text":"\\"假设你是一位经验丰富的数学老师,对学生要求严格,讲解问题时注重逻辑和步骤。\\"","correct":true},{"key":"D","text":"\\"生成一些数学公式。\\"","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 846, 'single', '你希望大模型生成的文本更具创造性,比如为一个新产品想广告标语。以下哪个参数调整可能 有助于此目标?', '[{"key":"A","text":"设置Top-p为0.1","correct":false},{"key":"B","text":"设置温度(Temperature)为0","correct":false},{"key":"C","text":"设置温度(Temperature)为0.9","correct":true},{"key":"D","text":"使用贪婪搜索(Greedy Search)","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 847, 'single', '你的RAG系统在处理用户查询时,检索到了多篇相关文档。为了生成一个综合性的答案,同时 避免信息冗余,以下哪种提示词设计最合理?', '[{"key":"A","text":"\\"请根据以下文档,生成一个答案。\\"","correct":false},{"key":"B","text":"\\"请总结以下所有文档的内容,不要遗漏任何细节。\\"","correct":false},{"key":"C","text":"\\"基于提供的上下文,提炼关键信息,生成一个简洁、准确的答案。如果信息有冲突,请以最新文 档为准。\\"","correct":true},{"key":"D","text":"\\"直接复制以下文档中的第一段。\\"","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 848, 'single', '你的应用需要大模型生成JSON格式的数据。为了确保输出是有效的、可解析的JSON,以下哪种 方法最可靠?', '[{"key":"A","text":"在提示词中要求模型输出JSON","correct":false},{"key":"B","text":"使用输出解析(Output Parsing)库或框架,在模型输出后强制进行格式检查和解析","correct":true},{"key":"C","text":"相信模型总是能输出正确JSON","correct":false},{"key":"D","text":"要求模型输出XML","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 849, 'single', '你的应用需要大模型处理超长文档(例如一本数百页的书),但模型有上下文窗口限制。以下 哪种策略是处理长文档的常见方法?', '[{"key":"A","text":"将整个文档一次性输入模型","correct":false},{"key":"B","text":"使用文档切片(Chunking)技术,将长文档分割成较小的片段进行处理","correct":true},{"key":"C","text":"要求用户只提交摘要","correct":false},{"key":"D","text":"忽略上下文限制,强制模型处理","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 850, 'single', '你的团队正在微调一个大模型用于医疗问答场景。在评估微调后的模型时,发现其在训练数据 上表现很好,但在未见过的医疗问题上泛化能力较差。这最可能是哪种现象?', '[{"key":"A","text":"过拟合(Overfitting)","correct":true},{"key":"B","text":"欠拟合(Underfitting)","correct":false},{"key":"C","text":"梯度爆炸","correct":false},{"key":"D","text":"模型收敛","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 851, 'single', '某智能助手在处理用户查询时,经常给出过于冗长的回答。以下哪种方法能有效控制回答长 度?', '[{"key":"A","text":"设置最大token限制","correct":false},{"key":"B","text":"要求模型“简短回答”","correct":false},{"key":"C","text":"要求模型“用一句话回答”","correct":false},{"key":"D","text":"在提示词中明确要求“回答不超过50字”","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 852, 'single', '某智能招聘系统需要生成职位描述。以下哪种方法最能确保内容合规?', '[{"key":"A","text":"完全依赖模型生成","correct":false},{"key":"B","text":"基于合规模板和模型生成","correct":true},{"key":"C","text":"人工编写所有描述","correct":false},{"key":"D","text":"复制其他公司描述","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 853, 'single', '某智能营销系统需要生成不同渠道的广告内容。以下哪种方法最能适应渠道特点?', '[{"key":"A","text":"生成统一内容分发所有渠道","correct":false},{"key":"B","text":"为每个渠道提供格式和风格要求","correct":true},{"key":"C","text":"只生成文字内容","correct":false},{"key":"D","text":"依赖渠道自动适配","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 854, 'single', '某智能写作助手需要适应不同的写作风格。以下哪种方法最灵活?', '[{"key":"A","text":"为每种风格训练专用模型","correct":false},{"key":"B","text":"提供风格示例作为参考","correct":true},{"key":"C","text":"使用固定的写作模板","correct":false},{"key":"D","text":"要求用户指定风格关键词","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 855, 'single', '某智能写作助手需要避免生成重复内容。以下哪种参数设置最有帮助?', '[{"key":"A","text":"高重复惩罚(high repetition penalty)","correct":true},{"key":"B","text":"低温度(low temperature)","correct":false},{"key":"C","text":"高顶层P(high top-p)","correct":false},{"key":"D","text":"增加生成长度","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 856, 'single', '某智能日程管理系统需要理解模糊的时间描述。以下哪种方法最能改善理解准确性?', '[{"key":"A","text":"要求用户使用精确时间","correct":false},{"key":"B","text":"使用时间解析库预处理","correct":true},{"key":"C","text":"依赖模型理解能力","correct":false},{"key":"D","text":"忽略模糊描述","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 857, 'single', '某智能旅行规划系统需要生成个性化行程。以下哪种方法最能满足用户需求?', '[{"key":"A","text":"生成标准行程","correct":false},{"key":"B","text":"基于用户偏好和历史生成行程","correct":true},{"key":"C","text":"随机生成行程","correct":false},{"key":"D","text":"要求用户详细指定所有活动","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 858, 'single', '某智能客服需要处理多轮对话并保持上下文连贯。以下哪种技术最关键?', '[{"key":"A","text":"对话状态跟踪","correct":true},{"key":"B","text":"每次对话独立处理","correct":false},{"key":"C","text":"要求用户重复信息","correct":false},{"key":"D","text":"使用短上下文模型","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 859, 'single', '某智能教学系统需要适应不同学生的学习水平。以下哪种方法最能实现个性化?', '[{"key":"A","text":"为每个学生训练专用模型","correct":false},{"key":"B","text":"在提示词中包含学生水平信息","correct":true},{"key":"C","text":"使用统一模型对所有学生","correct":false},{"key":"D","text":"让学生自己选择难度","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 860, 'single', '某新闻摘要系统需要保持中立客观。以下哪种方法最能减少模型偏见?', '[{"key":"A","text":"使用多个模型投票","correct":false},{"key":"B","text":"要求多个角度分析","correct":false},{"key":"C","text":"基于事实性信息生成摘要","correct":true},{"key":"D","text":"人工编写摘要","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 861, 'single', '在使用大模型进行代码生成时,你希望生成的代码具有良好的可读性和注释。以下哪个提示词 附加要求最有助于实现这一目标?', '[{"key":"A","text":"\\"生成代码。\\"","correct":false},{"key":"B","text":"\\"生成高效的代码。\\"","correct":false},{"key":"C","text":"\\"生成可读性高的Python代码,并添加必要的注释。\\"","correct":true},{"key":"D","text":"\\"用C++写代码。\\"","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 862, 'single', '某推荐系统需要生成个性化的产品推荐理由。以下哪种方法最能提升推荐质量?', '[{"key":"A","text":"生成统一的推荐理由","correct":false},{"key":"B","text":"基于用户画像和产品特征生成理由","correct":true},{"key":"C","text":"随机生成推荐理由","correct":false},{"key":"D","text":"不使用推荐理由","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 863, 'single', '某团队希望利用开源大模型构建一个企业内部知识问答系统,但担心直接将模型部署在公有云 上可能引发数据隐私泄露风险。以下哪种部署方案最能缓解这一风险?', '[{"key":"A","text":"使用公有云提供的API服务,因为云服务商承诺数据安全","correct":false},{"key":"B","text":"将模型部署在企业内部的私有服务器或私有云上","correct":true},{"key":"C","text":"对所有发送到公有云API的数据进行高级加密","correct":false},{"key":"D","text":"要求模型在输出中不包含任何敏感信息","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 864, 'single', '某团队使用大模型生成产品创意,并希望通过评估筛选出最好的创意。以下哪项评估标准更侧 重于创意的“可行性”而非“新颖性”?', '[{"key":"A","text":"这个创意是否前所未有","correct":false},{"key":"B","text":"这个创意与公司现有技术能力和资源的匹配程度","correct":true},{"key":"C","text":"这个创意的描述是否生动有趣","correct":false},{"key":"D","text":"这个创意名称的响亮程度","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 865, 'single', '某企业使用大模型处理内部合同文档,要求模型能对比两份合同的差异(如条款修改、新增内 容)。以下哪种提示策略最有效?', '[{"key":"A","text":"仅输入两份合同文本,要求模型“找出差异”","correct":false},{"key":"B","text":"采用结构化提示,明确要求模型“按条款编号 - 原合同内容 - 新合同内容 - 差异类型(修改/新增/删 除)”的格式,列出所有差异","correct":true},{"key":"C","text":"提供一份合同差异示例,让模型模仿","correct":false},{"key":"D","text":"先让模型总结每份合同内容,再对比总结结果","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 866, 'single', '某企业使用大模型处理客户反馈文本,需从反馈中提取“客户姓名、联系方式、问题类型”等关键 信息。以下哪种任务类型最适配?', '[{"key":"A","text":"文本分类","correct":false},{"key":"B","text":"文本摘要","correct":false},{"key":"C","text":"命名实体识别(NER)与信息抽取","correct":true},{"key":"D","text":"文本翻译","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 867, 'single', '某企业使用阿里云大模型构建客服机器人,要求机器人能识别用户的“敏感问题”(如“投诉公司 产品质量缺陷”“询问公司未公开的财务数据”),并自动转接人工客服,避免模型生成不当回复。以 下哪种技术方案最适配?', '[{"key":"A","text":"让模型直接生成回复,不处理敏感问题","correct":false},{"key":"B","text":"采用文本分类任务,基于历史敏感问题数据训练模型,识别“敏感问题”类别,触发人工转接逻辑","correct":true},{"key":"C","text":"提供大量敏感问题示例,让模型学习“回避回答”","correct":false},{"key":"D","text":"在前端限制用户输入,禁止输入包含“投诉”“财务”等关键词的内容","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 868, 'single', '某企业开发智能办公助手,要求模型能解析用户上传的PDF文档(含表格、公式),并回答相关 问题。以下哪种技术方案最完整?', '[{"key":"A","text":"直接将PDF文本提取后输入大模型","correct":false},{"key":"B","text":"使用OCR工具提取PDF中的表格/公式,转换为文本,结合RAG接入文档数据库","correct":true},{"key":"C","text":"要求用户手动将PDF内容转换为纯文本后输入","correct":false},{"key":"D","text":"选用支持多模态的大模型,直接输入PDF","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 869, 'single', '某企业开发内部知识库问答系统,需让大模型能精准回答企业内部规章制度、产品参数等涉密 信息,且要求数据不对外泄露。以下哪种方案符合要求?', '[{"key":"A","text":"使用公有云大模型API,将涉密信息直接嵌入提示词","correct":false},{"key":"B","text":"基于开源大模型进行私有化部署,结合RAG接入内部知识库","correct":true},{"key":"C","text":"将涉密信息脱敏后,调用第三方大模型API","correct":false},{"key":"D","text":"选用免费的通用大模型,仅输入非核心涉密信息","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 870, 'single', '某企业开发内部工单处理系统,要求大模型能自动将“客户投诉工单”分类为“产品质量、物流问 题、售后服务”等类别,并分配给对应部门。以下哪种技术方案最适配?', '[{"key":"A","text":"采用少样本提示,提供每个类别的3-5个工单示例","correct":true},{"key":"B","text":"直接使用通用大模型,不做任何优化","correct":false},{"key":"C","text":"让人工手动分类,不使用大模型","correct":false},{"key":"D","text":"将所有工单转换为向量,存储到向量数据库","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 871, 'single', '某内容生成系统需要确保输出内容的多样性。以下哪种参数配置最合适?', '[{"key":"A","text":"temperature=0.1, top-p=0.9","correct":false},{"key":"B","text":"temperature=0.7, top-p=0.9","correct":true},{"key":"C","text":"temperature=0.1, top-p=0.1","correct":false},{"key":"D","text":"temperature=0.9, top-p=0.1","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 872, 'single', '某内容生成系统需要控制输出内容的毒性。以下哪种方法最有效?', '[{"key":"A","text":"事后内容过滤","correct":false},{"key":"B","text":"在训练数据中去毒","correct":false},{"key":"C","text":"提示词中要求“生成友好内容”","correct":false},{"key":"D","text":"结合提示词指导和实时内容检测","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 873, 'single', '某内容审核系统使用大模型识别违规内容,但误判率较高。以下哪种方法最能降低误判?', '[{"key":"A","text":"降低判断阈值","correct":false},{"key":"B","text":"提供更多违规内容示例","correct":false},{"key":"C","text":"要求模型“严格审核”","correct":false},{"key":"D","text":"结合规则引擎和模型判断","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 874, 'single', '某客服系统需要处理敏感客户信息,以下哪种方法最能保护隐私?', '[{"key":"A","text":"在提示词中要求“不要泄露隐私”","correct":false},{"key":"B","text":"使用模型内置的隐私保护功能","correct":false},{"key":"C","text":"在输入前对敏感信息进行脱敏处理","correct":true},{"key":"D","text":"依赖用户不提供敏感信息","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 875, 'single', '某开发者需开发一款电商智能导购系统,要求模型能根据用户历史购买记录、浏览行为推荐精 准商品,且响应延迟≤500ms。以下哪种模型部署方案最适配?', '[{"key":"A","text":"选用13B参数的开源大模型本地部署","correct":false},{"key":"B","text":"选用70B参数的闭源大模型API调用","correct":false},{"key":"C","text":"选用3B参数的轻量化模型结合向量数据库","correct":true},{"key":"D","text":"直接使用通用大模型,不做任何优化","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 876, 'single', '某开发者使用开源大模型进行本地部署,发现模型推理速度过慢,影响用户体验。以下哪种优 化措施不适用?', '[{"key":"A","text":"对模型进行量化(如从FP32转为INT8)","correct":false},{"key":"B","text":"减少模型的上下文窗口大小","correct":false},{"key":"C","text":"增加服务器的CPU核心数(模型仅依赖GPU推理)","correct":true},{"key":"D","text":"使用模型蒸馏技术,简化模型结构","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 877, 'single', '某开发者使用大模型生成API的调用代码,但发现不同次生成的代码风格差异很大,有些不符合 项目的编码规范。以下哪种方法能最有效地促使模型生成风格一致的代码?', '[{"key":"A","text":"在每次请求的提示词中,随机选择一个编码规范进行说明","correct":false},{"key":"B","text":"在系统级提示词中固定地、明确地定义所期望的代码风格和规范","correct":true},{"key":"C","text":"接受所有输出,然后使用外部工具统一进行格式化","correct":false},{"key":"D","text":"不采取任何措施,认为风格多样性是好事","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 878, 'single', '某开发者使用阿里云通义千问API开发应用,需控制每次API调用的成本。以下哪种措施最有 效?', '[{"key":"A","text":"增加每次请求的文本输入长度","correct":false},{"key":"B","text":"选用更高精度的模型版本","correct":false},{"key":"C","text":"合理设置“max_tokens”参数,限制输出文本长度","correct":true},{"key":"D","text":"提高API调用的并发量","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 879, 'single', '某开发者使用阿里云PAI平台开发大模型应用,需将模型部署为RESTful API供前端调用,且要求 支持高并发请求。以下哪种部署方式最适合?', '[{"key":"A","text":"单机部署模型,直接暴露HTTP接口","correct":false},{"key":"B","text":"使用PAI-EAS(弹性计算服务)进行容器化部署,配置自动扩缩容","correct":true},{"key":"C","text":"将模型部署在本地服务器,通过内网穿透供前端调用","correct":false},{"key":"D","text":"采用静态文件部署方式,将模型权重文件直接提供给前端","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 880, 'single', '某开发者使用RAG技术开发知识库问答系统,发现部分最新文档(如2025年发布的政策)无法 被检索到。以下哪种原因最可能?', '[{"key":"A","text":"向量数据库未更新,未存入2025年的文档","correct":true},{"key":"B","text":"模型的上下文窗口过小","correct":false},{"key":"C","text":"检索时使用的相似度阈值过高","correct":false},{"key":"D","text":"文档分块粒度不当","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 881, 'single', '某开发者使用RAG技术开发知识库问答系统,发现部分最新文档(如2025年发布的行业政策文 档)无法被检索到,导致模型无法回答相关问题。以下哪种原因最可能?', '[{"key":"A","text":"向量数据库未更新,未将2025年的政策文档转换为向量并存入数据库","correct":true},{"key":"B","text":"模型的上下文窗口过小,无法处理长文档","correct":false},{"key":"C","text":"检索时使用的相似度阈值过高(如0.9),过滤了相关文档","correct":false},{"key":"D","text":"文档分块粒度不当(如分块过大),导致检索精度低","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 882, 'single', '某开发者开发大模型应用时,需实现“用户输入语音指令,模型生成文本回复”的功能。以下哪种 技术组合最完整?', '[{"key":"A","text":"仅使用大模型的文本生成能力","correct":false},{"key":"B","text":"使用语音识别API将语音转文本,再调用大模型生成回复","correct":true},{"key":"C","text":"直接将语音数据输入大模型","correct":false},{"key":"D","text":"使用语音合成API将文本回复转为语音,再输出给用户","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 883, 'single', '某开发者开发大模型应用时,需实现“用户上传Excel表格,模型分析表格数据并生成可视化图表 描述”的功能。以下哪种技术方案最完整?', '[{"key":"A","text":"直接将Excel表格输入大模型,要求生成图表描述","correct":false},{"key":"B","text":"使用Excel解析库(如Pandas)提取表格数据(转为JSON/CSV格式),结合提示词要求模型“按 ‘图表类型-数据维度-关键结论’的结构,生成可视化描述(如‘柱状图:Q1产品销量1200件,同比增 长15%’)”","correct":true},{"key":"C","text":"让用户手动输入表格数据,再调用模型","correct":false},{"key":"D","text":"仅生成表格数据的文本总结,不涉及图表描述","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 884, 'single', '某开发者开发大模型多轮对话应用,用户连续提问:“推荐一款性价比高的笔记本电脑”→“它的 内存是多大?”。模型无法理解“它”指代“推荐的笔记本电脑”。以下哪种优化措施最有效?', '[{"key":"A","text":"要求用户每次提问都重复提及“笔记本电脑”","correct":false},{"key":"B","text":"在每次对话中,将历史对话中的核心实体(如“推荐的笔记本电脑”)标注并传入模型","correct":true},{"key":"C","text":"更换参数更大的模型","correct":false},{"key":"D","text":"限制用户的提问长度","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 885, 'single', '某金融公司使用大模型分析财报,需要模型进行复杂的数学计算。发现模型经常出现计算错 误,以下哪种方法最能改善计算准确性?', '[{"key":"A","text":"要求模型“仔细计算”","correct":false},{"key":"B","text":"提供计算示例","correct":false},{"key":"C","text":"要求模型分步展示计算过程","correct":true},{"key":"D","text":"使用更简单的语言描述问题","correct":false}]', 'C') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 886, 'single', '某教育应用使用大模型生成数学题目,但需要控制题目难度。以下哪种提示词构造最有效?', '[{"key":"A","text":"\\"生成一道数学题\\"","correct":false},{"key":"B","text":"\\"生成一道适合小学五年级学生的数学应用题\\"","correct":true},{"key":"C","text":"\\"生成一道简单的数学题\\"","correct":false},{"key":"D","text":"\\"生成数学题\\"","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 887, 'single', '某教育平台需要生成不同难度的测验题目。以下哪种方法最能系统化控制难度?', '[{"key":"A","text":"随机生成题目","correct":false},{"key":"B","text":"基于布鲁姆分类法明确要求认知层次","correct":true},{"key":"C","text":"要求模型“生成简单题目”","correct":false},{"key":"D","text":"人工编写所有题目","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 888, 'single', '某公司希望使用大模型生成产品描述,但要求描述必须包含特定关键词,并且以表格形式输 出。以下哪种提示词工程方法最能有效实现这一目标?', '[{"key":"A","text":"提供少量样例","correct":false},{"key":"B","text":"明确输出格式要求","correct":true},{"key":"C","text":"思维链方法","correct":false},{"key":"D","text":"提供受众和角色","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 889, 'single', '某公司希望大模型能够根据公司内部的业务规则(例如,折扣计算逻辑、客户等级划分)来回 答用户咨询。为了确保答案的准确性,以下哪种集成方案最可靠?', '[{"key":"A","text":"期望模型通过阅读公司文档自行学习这些规则","correct":false},{"key":"B","text":"将业务规则编写成代码或SQL查询,让模型在需要时调用这些外部工具来获取准确结果","correct":true},{"key":"C","text":"在提示词中用自然语言详细描述所有业务规则","correct":false},{"key":"D","text":"训练模型记忆所有可能的规则组合","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 890, 'single', '某公司使用大模型自动生成会议纪要。为了保护隐私,需要在纪要中自动隐去所有提到的人 名。以下哪种实现方案在效果和复杂性上相对最平衡?', '[{"key":"A","text":"先使用大模型生成完整纪要,再使用一个专门的命名实体识别模型来识别并删除人名","correct":false},{"key":"B","text":"在给大模型的提示词中,明确要求“在生成的会议纪要中,用[匿名]替换所有真实人名”","correct":true},{"key":"C","text":"在会议录音转文字后,手动删除所有人名,再将文本输入模型生成纪要","correct":false},{"key":"D","text":"训练一个专门用于匿名化文本的大模型","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 891, 'single', '某公司使用大模型生成营销邮件,但发现风格不一致。以下哪种方法能最好地统一风格?', '[{"key":"A","text":"提供风格示例作为参考","correct":true},{"key":"B","text":"要求模型“保持风格一致”","correct":false},{"key":"C","text":"使用不同的模型版本","correct":false},{"key":"D","text":"人工修改所有输出","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 892, 'single', '某公司使用大模型生成面试问题,但需要避免歧视性内容。以下哪种方法最有效?', '[{"key":"A","text":"事后人工审查","correct":false},{"key":"B","text":"在提示词中明确要求“避免歧视性内容”","correct":false},{"key":"C","text":"使用去偏见的训练数据","correct":false},{"key":"D","text":"结合内容过滤器和明确提示词要求","correct":true}]', 'D') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 893, 'single', '某公司使用大模型生成产品代码文档,但发现文档与代码实际功能不符。以下哪种改进措施最 有效?', '[{"key":"A","text":"要求开发人员重写代码","correct":false},{"key":"B","text":"基于代码分析生成文档","correct":true},{"key":"C","text":"要求模型“确保文档准确”","correct":false},{"key":"D","text":"人工校对所有文档","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 894, 'single', '某公司开发智能舆情分析系统,要求模型能从海量新闻、社交媒体文本中,识别出“提及公司产 品”的文本,并判断情感倾向(正面/负面/中性)。以下哪种技术组合最适配?', '[{"key":"A","text":"文本分类(情感倾向)+ 命名实体识别(识别产品名)","correct":true},{"key":"B","text":"文本摘要 + 文本翻译","correct":false},{"key":"C","text":"语音识别 + 文本生成","correct":false},{"key":"D","text":"向量检索 + 模型并行","correct":false}]', 'A') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 895, 'single', '某公司开发智能HR助手,要求模型能根据求职者简历,生成针对性的面试问题(如针对“项目经 验中的Python开发”提问技术细节,针对“团队管理经历”提问协作能力)。以下哪种提示策略最适 配?', '[{"key":"A","text":"仅输入简历文本,要求“生成面试问题”","correct":false},{"key":"B","text":"采用结构化提示,要求模型“按‘简历模块(项目经验/教育背景/技能证书/工作经历)-考察维度 (技术能力/软技能/经验匹配度)-具体问题’的格式,生成3-5个针对性问题,每个问题需关联简历中 的具体信息”","correct":true},{"key":"C","text":"提供1-2个面试问题示例,让模型模仿","correct":false},{"key":"D","text":"先让模型总结简历核心内容,再基于总结生成问题","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-single', 896, 'single', '某新闻机构使用大模型撰写报道,需要确保事实准确性。以下哪种方法组合最有效?', '[{"key":"A","text":"仅依赖模型的内在知识","correct":false},{"key":"B","text":"通过RAG接入最新新闻数据库","correct":true},{"key":"C","text":"要求模型“确保事实准确”","correct":false},{"key":"D","text":"人工审核所有输出","correct":false}]', 'B') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
