INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 105, 'multi', '如何引导大型语言模型提供合规、无害内容的产生?', '[{"key":"A","text":"明确使用目标与生成内容范围","correct":true},{"key":"B","text":"设计内容时进行多轮审查","correct":true},{"key":"C","text":"允许模型自由生成任何内容","correct":false},{"key":"D","text":"主动设置内容过滤机制","correct":true},{"key":"E","text":"审查并确保内容符合社会伦理标准和法律法规","correct":true},{"key":"F","text":"忽略对模型输出内容的审核","correct":false}]', 'ABDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 106, 'multi', 'ModelScope-Agent框架具备简单的Agent实现流程、丰富的多模态工具、通义的接口和扩展性。 在框架内部自动实现工具的使用、规划、记忆等工作流的编排。下列描述正确的是哪些?', '[{"key":"A","text":"该框架自动将复杂任务分解为简单子任务来实现","correct":true},{"key":"B","text":"该框架自动处理任务之间的依赖关系和执行顺序","correct":true},{"key":"C","text":"该框架不支持多步骤任务执行","correct":false},{"key":"D","text":"开发者必须手动编写任务调度逻辑来使用插件","correct":false}]', 'AB') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 107, 'multi', '关于预训练模型的选择,以下哪些描述是正确的?', '[{"key":"A","text":"应根据任务的特定需求选择不同规模的预训练模型","correct":true},{"key":"B","text":"模型的大小直接决定了其泛化能力,因此越大越好","correct":false},{"key":"C","text":"需要评估模型在类似任务上的表现以预测其在新任务上的潜力","correct":true},{"key":"D","text":"考虑模型的可访问性和许可要求,以免侵犯版权","correct":true}]', 'ACD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 108, 'multi', '以下哪些描述符合使用列表方法给通义千问大模型增加记忆的场景?', '[{"key":"A","text":"在与模型的交互中,将关键信息以列表形式累积存储","correct":true},{"key":"B","text":"每次提问时,将该列表作为上下文附加到问题中,帮助模型理解历史对话","correct":true},{"key":"C","text":"列表中存储的信息会随每次请求自动清空,保证每次对话独立性","correct":false},{"key":"D","text":"可以手动编辑列表内容,选择性地向模型展示特定的记忆信息","correct":true}]', 'ABD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 109, 'multi', '大模型Agent自动处理任务时,可以减少哪些人工工作量?', '[{"key":"A","text":"手工阅卷","correct":false},{"key":"B","text":"数据清洗","correct":true},{"key":"C","text":"智能日志分析","correct":true},{"key":"D","text":"客服聊天记录总结","correct":false},{"key":"E","text":"数学计算","correct":true}]', 'BCE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
