INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 111, 'multi', '以下关于大语言模型与多模态模型的描述中,正确的是?', '[{"key":"A","text":"大语言模型主要基于Transformer架构,通过深度学习处理自然语言文本,擅长任务包括文本生成 和机器翻译","correct":true},{"key":"B","text":"Bard是微软推出的一款大型语言模型,专门设计用于创造高度创意的文本内容","correct":false},{"key":"C","text":"多模态模型能够同时处理文本、图像、音频等多种类型的数据,并实现这些模态间的关联分析","correct":true},{"key":"D","text":"音频处理模型是一种计算机程序或算法,用于将人类口语(即语音信号)转化为可被计算机理解的文 字形式","correct":false}]', 'AC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 112, 'multi', '在利用大模型处理调查问卷时,以下哪些步骤可能是必要的?', '[{"key":"A","text":"将问卷数据预处理为模型可接受的格式","correct":true},{"key":"B","text":"设定评分标准或关键词以判断回答质量","correct":true},{"key":"C","text":"人工检查每一份问卷的每一个答案","correct":false},{"key":"D","text":"使用API调用大模型进行批量分析","correct":true},{"key":"E","text":"直接将原始问卷文档上传至大模型进行处理","correct":false}]', 'ABD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 113, 'multi', '在使用大模型Agent时,哪种方式可以增强它的能力?', '[{"key":"A","text":"增加训练数据集","correct":true},{"key":"B","text":"使用插件","correct":true},{"key":"C","text":"调整学习率","correct":true},{"key":"D","text":"集成第三方API","correct":true},{"key":"E","text":"更改模型架构","correct":true}]', 'ABCDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 114, 'multi', '已知Qwen-7B预训练模型、Qwen-7B-Chat对话对齐微调模型和Qwen-Max线上模型,对比三者在 处理特定领域问题时的能力,我们有可能遇到的问题是:', '[{"key":"A","text":"Qwen-7B由于缺乏特定领域知识的微调,可能在专业性回答上不如后两者","correct":true},{"key":"B","text":"Qwen-7B-Chat通过对话微调,能更好地理解并回应复杂对话场景,但可能在广度上不及Qwen- Max","correct":true},{"key":"C","text":"Qwen-Max作为线上模型,通常拥有更庞大的参数量和更广泛的训练数据,从而在泛化能力和某 些特定任务上表现最优","correct":true},{"key":"D","text":"无论模型大小,只要经过足够的微调,所有模型都能达到相同水平的性能表现","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 115, 'multi', '在大模型的风险评测中,哪些步骤可以帮助有效评估模型的安全性?', '[{"key":"A","text":"定义风险类型","correct":true},{"key":"B","text":"构建评估基准(Benchmark)","correct":true},{"key":"C","text":"优化用户界面","correct":false},{"key":"D","text":"增加模型的计算资源","correct":false}]', 'AB') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 116, 'multi', '以下选项中,百炼平台目前支持导入的数据格式有哪些?', '[{"key":"A","text":"pdf","correct":true},{"key":"B","text":"html","correct":true},{"key":"C","text":"docx","correct":true},{"key":"D","text":"csv","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 117, 'multi', '预训练(Pre-training)、SFT、RLHF这三个阶段,分别解决了哪些关键问题?', '[{"key":"A","text":"预训练解决了模型如何从无标注文本中学习语言基本结构的问题","correct":true},{"key":"B","text":"SFT专注于缩小模型输出与特定任务目标之间的差距","correct":true},{"key":"C","text":"RLHF通过引入人类评价来指导模型学习更高质量、更符合伦理的输出","correct":true},{"key":"D","text":"这三个阶段依次解决了模型的泛化能力、任务适应性和价值导向性问题","correct":true}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 118, 'multi', '以下哪些是多模态学习在实际应用中的例子?', '[{"key":"A","text":"智能客服系统,结合语音识别和自然语言处理提供服务","correct":true},{"key":"B","text":"自动驾驶车辆,集成视觉、雷达和GPS数据进行环境感知","correct":true},{"key":"C","text":"医疗影像分析,融合影像数据和临床报告辅助诊断","correct":true},{"key":"D","text":"在线教育平台,利用视频、语音和文字同步提升教学体验","correct":true}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 119, 'multi', '下列哪些技术或领域特别适合利用单Agent系统的集中处理能力?', '[{"key":"A","text":"无人驾驶汽车的路径规划与避障算法","correct":false},{"key":"B","text":"大型数据中心的资源分配与优化","correct":false},{"key":"C","text":"单一目标的深度学习训练,如图像分类","correct":true},{"key":"D","text":"工业自动化中的生产线监控与调度","correct":true}]', 'CD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 120, 'multi', '在个人信息治理的过程中,哪些措施可以有效保护用户的隐私?', '[{"key":"A","text":"数据去标识化","correct":true},{"key":"B","text":"用户身份验证","correct":true},{"key":"C","text":"数据加密","correct":true},{"key":"D","text":"数据混杂处理","correct":true},{"key":"E","text":"数据开源处理","correct":false},{"key":"F","text":"提高模型参数","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 121, 'multi', '以下哪些场景体现了多模态学习的应用,且需要跨模态的信息转换或推理?', '[{"key":"A","text":"文字到语音的合成(TTS)","correct":true},{"key":"B","text":"视频中的物体检测","correct":false},{"key":"C","text":"语音频域分析","correct":false},{"key":"D","text":"图像描述生成(Image Captioning)","correct":true}]', 'AD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 122, 'multi', '以下关于分词化的描述中,错误的是?', '[{"key":"A","text":"“分词化”就是将日常使用的一个个词语转换成计算机可以理解的数量向量形式","correct":true},{"key":"B","text":"分词化将文本数据转换成一系的字节码,以便于存储和传输","correct":true},{"key":"C","text":"分词化将句子或文本字符串分解成更小的组成单元,如单词、短语或其他有意义的符号","correct":false},{"key":"D","text":"子词粒度(Subword-Level)分词化是中文最直接的分词方法,它是以单个汉字为单位进行分词化","correct":true}]', 'ABD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 123, 'multi', '在设计LLM思维链提示(Chain-of-Thought Prompting,CoT)时,以下哪几项是有助于提高其效 的关键因素?', '[{"key":"A","text":"明确问题背景","correct":true},{"key":"B","text":"提供中间步骤","correct":true},{"key":"C","text":"使用简洁明了的语言","correct":true},{"key":"D","text":"引入无关信息干扰","correct":false},{"key":"E","text":"增加问题难度","correct":false},{"key":"F","text":"确保逻辑性和连贯性","correct":true}]', 'ABCF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 124, 'multi', '利用大模型API开发应用时,开发者需要注意的事项包括:', '[{"key":"A","text":"数据隐私和安全问题","correct":true},{"key":"B","text":"控制和应对模型输出的不确定性","correct":true},{"key":"C","text":"成本控制,避免无限制的API调用","correct":true},{"key":"D","text":"模型的版权和使用条款遵守","correct":true},{"key":"E","text":"必须具备高级编程技能才能使用","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 125, 'multi', '在模型安全防控中,哪些措施可以增强模型的鲁棒性(健壮性)?', '[{"key":"A","text":"增加训练数据多样性","correct":true},{"key":"B","text":"对抗性攻击测试","correct":true},{"key":"C","text":"缩小模型规模","correct":false},{"key":"D","text":"提升模型参数","correct":true}]', 'ABD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 126, 'multi', '关于LLM少样本提示(Few-Shot Prompting)中的示例选择,以下哪些说法是正确的?', '[{"key":"A","text":"示例应覆盖任务的各种可能情况","correct":false},{"key":"B","text":"示例应体现任务的主要难点","correct":true},{"key":"C","text":"示例应具有代表性,避免使用可能引起模型混淆的极端或边缘案例","correct":true},{"key":"D","text":"示例应尽可能多,以增加模型学习数据量","correct":false},{"key":"E","text":"示例应避免重复已知知识","correct":true},{"key":"F","text":"示例尽可能来源于真实场景","correct":true}]', 'BCEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 127, 'multi', '在运用LLM零样本提示技术时,以下哪些是提高模型性能的建议?', '[{"key":"A","text":"明确任务描述","correct":true},{"key":"B","text":"使用冗长复杂的提示","correct":false},{"key":"C","text":"提供背景信息","correct":true},{"key":"D","text":"描述任务时使用专业术语或英文缩写","correct":false},{"key":"E","text":"保持提示的一致性","correct":true},{"key":"F","text":"避免使用引导词汇","correct":true}]', 'ACEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 128, 'multi', '在大模型微调的准备阶段,哪些因素直接关系到微调效果的优化和资源的有效利用?', '[{"key":"A","text":"明确应用场景与目标","correct":true},{"key":"B","text":"随机选择的预训练模型","correct":false},{"key":"C","text":"业务领域无关的数据集","correct":false},{"key":"D","text":"充足且适合的计算资源","correct":true}]', 'AD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 129, 'multi', '在自动化处理问卷调查数据时,以下哪些步骤是适当的?', '[{"key":"A","text":"调用大模型API","correct":true},{"key":"B","text":"人工逐个审阅","correct":false},{"key":"C","text":"使用数据可视化工具分析结果","correct":true},{"key":"D","text":"应用统计分析","correct":true}]', 'ACD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
