INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 131, 'multi', '单Agent模式可能在以下哪些应用场景中表现优异?', '[{"key":"A","text":"个人智能助手,如日程管理、提醒服务","correct":true},{"key":"B","text":"单一目标追踪,如无人机监视特定对象","correct":true},{"key":"C","text":"简化的自动化生产线监控与控制","correct":true},{"key":"D","text":"小规模室内导航与地图构建","correct":true}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 132, 'multi', '在设计LLM提示词时,分配角色的目的可能包括哪些?', '[{"key":"A","text":"改变文本的语气","correct":true},{"key":"B","text":"控制文本的生成风格","correct":true},{"key":"C","text":"增加模型的输出随机性","correct":true},{"key":"D","text":"让模型进行“角色扮演”","correct":true},{"key":"E","text":"改变呈现信息的深浅程度","correct":true},{"key":"F","text":"限制模型的功能","correct":true}]', 'ABCDEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 133, 'multi', '在确保合规与数据安全方面,微调大模型项目需要关注哪些方面?', '[{"key":"A","text":"获取并遵守数据使用的合法授权","correct":true},{"key":"B","text":"实施数据脱敏和隐私保护措施,避免泄露敏感信息","correct":true},{"key":"C","text":"建立数据审计机制,追踪数据使用情况","correct":true},{"key":"D","text":"采用加密技术保护数据传输和存储的安全","correct":true}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 134, 'multi', '下列哪些描述符合斯坦福小镇项目的特点?', '[{"key":"A","text":"项目包含3人模式和25人模式","correct":true},{"key":"B","text":"重点研究智能体的社会互动与关系形成","correct":true},{"key":"C","text":"智能体的日常活动按时间点分层设计执行","correct":true},{"key":"D","text":"目的是创建一个易用性高的Agent框架","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 135, 'multi', '多模态学习中,哪些流程是关键步骤,旨在整合和协调不同模态的信息?', '[{"key":"A","text":"多模态表征","correct":true},{"key":"B","text":"多模态对齐","correct":true},{"key":"C","text":"多模态融合","correct":true},{"key":"D","text":"多模态协同学习","correct":true}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 136, 'multi', '开发Agent应用时,我们会引入规划能力,例如让大模型帮我们打牌。在长链路规划场景中,规 划性能不足可能体现在哪些方面?', '[{"key":"A","text":"完成一次长链路规划,用户等待时间过长","correct":true},{"key":"B","text":"长链路规划的稳定性差,易导致执行偏差累积","correct":true},{"key":"C","text":"过细的规划粒度增加了执行复杂度和资源消耗","correct":true},{"key":"D","text":"缺乏有效的人机协作接口,在CoT过程中限制了人工修正","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 137, 'multi', '关于多智能体对话框架的应用与特性,下列哪些说法正确?', '[{"key":"A","text":"斯坦福小镇的多智能体通过分层设计和时间规划执行任务,强调两两沟通","correct":false},{"key":"B","text":"Agentscope演示了狼人杀等多人游戏,以及分布式对话、分布式辩论、分布式并行搜索、分布式 大规模模仿等多种分布式智能体系统","correct":true},{"key":"C","text":"MetaGPT能够为用户提供从用户案例到项目工程文档的一系列软件开发产出","correct":true},{"key":"D","text":"微软AutoGen提供易于构建多样应用的多智能体对话框架及增强的LLM推理优化","correct":true}]', 'BCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 138, 'multi', '在多模态对齐技术中,哪些方法可以用来确保不同模态数据间的时空一致性?', '[{"key":"A","text":"使用注意力机制匹配关键信息","correct":true},{"key":"B","text":"应用跨模态相似度学习","correct":true},{"key":"C","text":"利用预定义的时间戳或位置标签","correct":true},{"key":"D","text":"仅依赖于数据的先后顺序自然对齐","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 139, 'multi', '以下关于分词化的描述中,正确的是?', '[{"key":"A","text":"每个token会被直接用其对应的词汇字符串作为词表中的唯一标识,而不是映射为一个唯一的token id","correct":false},{"key":"B","text":"分词化是自然语言处理中的一个步骤,旨在将文本切分成更小的管理单元,称为token","correct":true},{"key":"C","text":"词粒度分词化适用于英语等西方语言,因为这些语言中的词通常由空格分隔","correct":true},{"key":"D","text":"在分词化过程结束后,每个token需要转换成一个数字id,这样才能被用于后续的计算机处理和分析","correct":true}]', 'BCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 140, 'multi', '在大模型的内容安全治理中,哪些措施可以防止生成非法或不当内容?', '[{"key":"A","text":"标准回答预置","correct":true},{"key":"B","text":"Query风险识别","correct":true},{"key":"C","text":"上传用户输入内容","correct":false},{"key":"D","text":"基于知识库的搜索增强","correct":true},{"key":"E","text":"Response风险识别","correct":true},{"key":"F","text":"增加训练轮数","correct":false}]', 'ABDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 141, 'multi', '以下概念属于机器学习范畴的是?', '[{"key":"A","text":"无监督学习","correct":true},{"key":"B","text":"超监督学习","correct":false},{"key":"C","text":"监督学习","correct":true},{"key":"D","text":"强化学习","correct":true}]', 'ACD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 142, 'multi', '以下哪些user_query的设计能够有效引导大语言模型进行英文到中文的翻译?', '[{"key":"A","text":"Translate the following English text to Chinese: \\"Hello, world!\\"","correct":true},{"key":"B","text":"\\"Hello, world!\\" 中文","correct":true},{"key":"C","text":"把 \\"Hello, world!\\" 翻译成中文","correct":true},{"key":"D","text":"English to Chinese: \\"Hello, world!\\"","correct":true},{"key":"E","text":"我想知道 \\"Hello, world!\\" 用中文怎么说","correct":true},{"key":"F","text":"将以下内容翻译为中文: \\"Hello, world!\\"","correct":true}]', 'ABCDEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 143, 'multi', '在使用CosyVoice进行语音合成时,通过以下哪些方式可以确保最终音频的质量和自然度?', '[{"key":"A","text":"保持录音环境的安静和无干扰","correct":false},{"key":"B","text":"在生成语音前,对文本内容进行优化,简化复杂句子","correct":true},{"key":"C","text":"使用多个语音合成模型进行比较,选择最佳结果","correct":true},{"key":"D","text":"调整语音合成模型的参数,如语速和音调","correct":true},{"key":"E","text":"增加语音合成的音量","correct":false}]', 'BCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 144, 'multi', '在大语言模型RAG应用的基本工作流程中,以下哪些是优化文档切片方法的有效思路?', '[{"key":"A","text":"将所有文档合并成一个大文件,以便一次性加载和处理","correct":false},{"key":"B","text":"按照markdown文档的结构进行切片,保留文档的原始结构信息","correct":true},{"key":"C","text":"对于独立的标题、段落、单元内容,在切片时补充语义信息","correct":true},{"key":"D","text":"尽量将文档切分成等长的文本块,方便后续的向量化处理","correct":false},{"key":"E","text":"根据用户提问的习惯和可能的提问方式进行切片","correct":true},{"key":"F","text":"使用更复杂的文档解析器,例如支持表格和图片解析的解析器","correct":true}]', 'BCEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 145, 'multi', '在qwen-plus对messages进行回答后,如果你想按照当前对话基础继续提问,需要怎么做?', '[{"key":"A","text":"对话历史跟着模型名称走,所以只要继续指定模型为qwen-plus就可以了","correct":false},{"key":"B","text":"将新的User Message添加到messages列表中","correct":true},{"key":"C","text":"大模型不支持多轮对话","correct":false},{"key":"D","text":"将大模型生成的Assistant Message添加到messages列表中","correct":true}]', 'BD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 146, 'multi', '在使用Ragas评估RAG应用的效果时,answer_correctness由哪些指标共同计算得来?', '[{"key":"A","text":"answer与ground_truth的语义相似度","correct":true},{"key":"B","text":"基于ground_truth与answer计算answer的事实准确性","correct":true},{"key":"C","text":"answer与context的语义相似度","correct":false},{"key":"D","text":"answer与query的一致性","correct":false},{"key":"E","text":"answer的长度","correct":false}]', 'AB') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 147, 'multi', '关于大语言模型在文本处理中的局限性,以下哪些描述是准确的?', '[{"key":"A","text":"大模型可能在处理特定领域专业术语时出现误解","correct":true},{"key":"B","text":"在没有明确指示的情况下,大模型可能无法自动识别源语言和目标语言","correct":true},{"key":"C","text":"即使有合适的系统提示词,大模型生成的内容仍需人工复审以保证质量","correct":true},{"key":"D","text":"大模型对用户查询的依赖性强,如果查询表述不清,结果可能偏离预期","correct":true},{"key":"E","text":"大模型技术已经完全成熟,能够无差错地执行所有文本转换和润色任务","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 148, 'multi', '下列哪些因素会影响大语言模型微调的效果?', '[{"key":"A","text":"微调数据的质量和数量","correct":true},{"key":"B","text":"微调时使用的超参数设置","correct":true},{"key":"C","text":"预训练模型的选择","correct":true},{"key":"D","text":"微调持续的轮数(epochs)","correct":true},{"key":"E","text":"是否采用数据增强技术","correct":true},{"key":"F","text":"计算资源的限制","correct":true}]', 'ABCDEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 149, 'multi', '已知prompt_template定义了让大语言模型生成摘要的具体要求,以下哪些措施可以提高摘要生成 函数的生成质量?', '[{"key":"A","text":"在prompt_template中提供更详细的输出格式要求,例如指定摘要的长度、语气等","correct":true},{"key":"B","text":"在prompt_template中提供一些示例摘要","correct":true},{"key":"C","text":"将document分成多个段落,分别生成摘要,最后合并","correct":true},{"key":"D","text":"在prompt_template中明确指出需要提取文章的主旨","correct":true},{"key":"E","text":"不使用prompt_template,直接调用大模型","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 150, 'multi', '下列Assistant API示例代码的query方法中,dashscope.Runs.wait的作用是什么?', '[{"key":"A","text":"监听后台请求,并在用户的等待期间消耗资源","correct":false},{"key":"B","text":"阻塞当前线程,直到请求的响应准备好为止","correct":true},{"key":"C","text":"提供异步呼叫的机制,以提升查询响应速度","correct":false},{"key":"D","text":"确保所有消息都已处理并存储好","correct":false},{"key":"E","text":"等待所有的辅助工具输出,确保信息的完整性","correct":true},{"key":"F","text":"返回请求的实时进度,对于调试非常有用","correct":false}]', 'BE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 151, 'multi', '在开发基于大语言模型的新员工帮助应用过程中,以下哪些建议有助于提升用户体验?', '[{"key":"A","text":"为每个任务定制详细的系统提示词,确保大模型理解上下文","correct":true},{"key":"B","text":"当用户输入超过500个字的时候截断,超长部分包含的关键信息较少,尽量保留有效信息","correct":false},{"key":"C","text":"引入多轮对话机制,允许用户基于大模型的初步回应进一步细化需求","correct":true},{"key":"D","text":"实现自动检测用户查询类型并调用相应的大模型处理策略,无需用户指定任务类型","correct":true},{"key":"E","text":"由于大模型的准确性极高,无需提供反馈或修正机制","correct":false}]', 'ACD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 152, 'multi', '关于大语言模型微调的潜在挑战,下列描述正确的是?', '[{"key":"A","text":"过度微调可能导致泛化能力下降","correct":true},{"key":"B","text":"特定任务数据不足可能限制模型性能","correct":true},{"key":"C","text":"微调总是能显著提升模型性能","correct":false},{"key":"D","text":"微调过程可能加剧模型的偏见","correct":true},{"key":"E","text":"微调比从头训练更容易导致模型欠拟合","correct":false},{"key":"F","text":"高质量预训练模型的可获得性是个问题","correct":false}]', 'ABD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 153, 'multi', '在开发大语言模型RAG应用过程中,以下哪些描述符合“基于语义的文档切片”的理念?', '[{"key":"A","text":"将文档按照固定长度进行切分","correct":false},{"key":"B","text":"根据文档的结构,例如标题、段落、列表等进行切分","correct":true},{"key":"C","text":"将表格的每个单元格作为一个独立的Chunk","correct":false},{"key":"D","text":"在Chunk中添加上下文信息,例如标题、父级列表项等","correct":true},{"key":"E","text":"使用机器学习模型对文档进行语义分析,并根据语义边界进行切分","correct":true},{"key":"F","text":"将代码块单独切分出来,并标注其编程语言","correct":false}]', 'BDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 154, 'multi', '以下哪些选项是有效的用户查询语句,可以指导大语言模型将一段正式的商务邮件改写成更轻 松友好的语气?', '[{"key":"A","text":"请将以下邮件改写成更口语化的表达方式:","correct":true},{"key":"B","text":"将以下邮件的语气变得更轻松友好:","correct":true},{"key":"C","text":"用更随意的语气重写以下邮件:","correct":true},{"key":"D","text":"将以下邮件翻译成英文:","correct":false},{"key":"E","text":"用更适合朋友之间交流的语气改写以下邮件:","correct":true},{"key":"F","text":"请将以下邮件改写成,去掉所有非专业表达:","correct":false}]', 'ABCE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 155, 'multi', '在使用大模型提炼图文课程内容时,以下哪些指导原则是正确的?', '[{"key":"A","text":"提炼关键信息,避免冗长段落","correct":true},{"key":"B","text":"使用简短标题,聚焦于要点","correct":true},{"key":"C","text":"内容应尽量详细和全面","correct":false},{"key":"D","text":"结合图片辅助,在适当的位置插入图片","correct":true},{"key":"E","text":"不做任何修改,直接使用原始内容","correct":false}]', 'ABD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 156, 'multi', '大语言模型微调可能涉及下列哪些步骤?', '[{"key":"A","text":"选定预训练模型","correct":true},{"key":"B","text":"减少模型层数","correct":false},{"key":"C","text":"构建特定任务数据集","correct":true},{"key":"D","text":"调整优化器和学习率","correct":true},{"key":"E","text":"在特定数据上训练模型","correct":true},{"key":"F","text":"评估模型性能","correct":true}]', 'ACDEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 157, 'multi', '以下对于大语言模型预训练与微调的关系描述正确的有哪些?', '[{"key":"A","text":"预训练提供了一个良好的初始化状态","correct":true},{"key":"B","text":"微调是对预训练模型的简单复制","correct":false},{"key":"C","text":"微调可以视为预训练的直接延续","correct":false},{"key":"D","text":"两者都强调领域无关的特征学习","correct":false},{"key":"E","text":"微调使模型适应特定任务需求","correct":true},{"key":"F","text":"预训练模型不需要修改即可应用于所有任务","correct":false}]', 'AE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 158, 'multi', '以下哪些因素会影响RAG系统的性能?', '[{"key":"A","text":"文档的质量和数量","correct":true},{"key":"B","text":"切片方法的选择","correct":true},{"key":"C","text":"向量数据库的类型和配置","correct":true},{"key":"D","text":"查询语句的表达方式","correct":true},{"key":"E","text":"硬件资源的限制","correct":true},{"key":"F","text":"所使用的预训练语言模型的大小和性能","correct":true}]', 'ABCDEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 159, 'multi', '优化大语言模型RAG应用时,需要考虑下列哪些因素?', '[{"key":"A","text":"用户提问的习惯和可能的提问方式","correct":true},{"key":"B","text":"大模型的解析方式和理解能力","correct":true},{"key":"C","text":"文档的结构和内容特点","correct":true},{"key":"D","text":"检索的效率和速度","correct":true},{"key":"E","text":"系统的可维护性和可扩展性","correct":true},{"key":"F","text":"最新的深度学习模型和算法","correct":true}]', 'ABCDEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 160, 'multi', '在通过API开发RAG应用时,一般会将API_KEY配置环境变量,以下选项中关于其原因的解释正 确的有哪些?', '[{"key":"A","text":"防止KEY泄漏","correct":true},{"key":"B","text":"环境变量会自动被SDK读取和使用","correct":true},{"key":"C","text":"环境变量可以加快程序的运行速度","correct":false},{"key":"D","text":"配置为环境变量可以减少代码的行数","correct":false}]', 'AB') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 161, 'multi', '关于智能体应用的图片合规检查的技术手段,下列说法正确的有哪些?', '[{"key":"A","text":"可以使用目标检测算法如YOLO系列检测图片中的敏感物体,例如武器","correct":true},{"key":"B","text":"OCR技术可以用于提取图片中的文字信息,用于后续的文本合规检测","correct":true},{"key":"C","text":"图片内容检测只能依靠人工审核,无法使用深度学习模型进行自动化分类","correct":false},{"key":"D","text":"PHash算法可以用于版权检查,通过比较图像指纹识别相似图像","correct":true},{"key":"E","text":"水印和品牌标志检查与合规性无关,不需要进行检测","correct":false},{"key":"F","text":"卷积神经网络(CNN)可以用于对图片内容的合规性进行分类,例如识别暴力内容","correct":true}]', 'ABDF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 162, 'multi', '在RAG系统中,关于文档解析阶段可能遇到的问题,以下说法正确的有哪些?', '[{"key":"A","text":"即使原始文档质量很高,也可能因为解析工具的问题导致解析出错","correct":true},{"key":"B","text":"不同版本的Word文档,即使内容相同,也可能因为格式差异导致解析结果不同","correct":true},{"key":"C","text":"PDF文件的解析通常比纯文本文件更简单","correct":false},{"key":"D","text":"在线文档由于其动态特性,解析难度通常比静态文件更大","correct":true},{"key":"E","text":"选择合适的解析工具和方法对于提高解析效率和准确性至关重要","correct":true},{"key":"F","text":"文档解析阶段的问题只跟技术层面相关,与业务层面无关","correct":false}]', 'ABDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 163, 'multi', '在生成插图提示词时,应该考虑哪些因素来确保提示词的有效性?', '[{"key":"A","text":"插图描述的详细程度","correct":true},{"key":"B","text":"场景和对象的具体性","correct":true},{"key":"C","text":"插图编号和位置的准确性","correct":true},{"key":"D","text":"插图文件的大小","correct":false},{"key":"E","text":"插图的颜色模式","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 164, 'multi', '在调用大语言模型对话的API过程中,关于abstract_generator (document) 函数,以下说法正确的 有哪些? def abstract_generator(document): prompt_template = "【角色背景】你是一个专业的审稿人..." 【任务要求】...【输出要求】请以json格式输出...摘要本身的内容不超过40个字...【用户输 入】...query = prompt_template + document # ...调用大模型', '[{"key":"A","text":"该函数利用大型模型实现了文本摘要功能","correct":true},{"key":"B","text":"该函数的输入document应该是一个字符串,代表需要生成摘要的文本","correct":true},{"key":"C","text":"该函数的输出是一个JSON格式的字符串,包含\\"abstract\\"键及其对应的摘要内容","correct":true},{"key":"D","text":"该函数内部使用了TextRank算法计算句子相似度","correct":false},{"key":"E","text":"该函数要求生成的摘要不超过40个字","correct":true}]', 'ABCE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 165, 'multi', '通过LlamaIndex创建RAG应用时,编写了如下代码,关于这段代码作用的描述正确的有哪些? documents = SimpleDirectoryReader(path).load_data() document = Document(text="\\n".join(doc.text for doc in documents)) replacements = {":": ":", "?": "?", "。": "."} for src, dst in replacements.items(): document.text = document.text.replace(src, dst) return document', '[{"key":"A","text":"将指定文件夹中的文件加载为document对象","correct":true},{"key":"B","text":"将中文的标点符号预先转化为英文标点符号,使得切分时不会使得chunk度过长","correct":true},{"key":"C","text":"将所有Document对象合并为一个Document对象","correct":true},{"key":"D","text":"对乱码内容进行数据清洗","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 166, 'multi', '以下哪些方法可以有效降低大语言模型在私域场景下泄露敏感信息的风险?', '[{"key":"A","text":"对用户输入进行敏感信息检测和过滤","correct":true},{"key":"B","text":"对大模型的输出进行敏感信息检测和过滤","correct":true},{"key":"C","text":"使用微调技术,使大模型学习私域数据的安全策略","correct":true},{"key":"D","text":"对大模型访问私域数据做适当程度的限制","correct":true},{"key":"E","text":"使用通用大模型的自我意识来防范","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 167, 'multi', '通过LamaIndex创建RAG应用时,编写了如下代码,这段代码有哪些问题?(缺代码)', '[{"key":"A","text":"重排选中的chunk数大于初步召回的chunk数","correct":true},{"key":"B","text":"rerank方法不应该放在node_postprocessors中","correct":false},{"key":"C","text":"LlamaIndex在RAG回答时不可以使用流式输出","correct":false},{"key":"D","text":"相似度阈值设置过高","correct":true}]', 'AD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 168, 'multi', '在开发基于RAG的智能答疑机器人过程中,以下那些代码可以用于检测用户输入中是否包含敏 感词?', '[{"key":"A","text":"import re def detect_sensitive_words(text, sensitive_words): for word in sensitive_words: if re.search(word, text): return True return False","correct":true},{"key":"B","text":"def detect_sensitive_words(text, sensitive_words): return any(word in text for word in sensitive_words)","correct":true},{"key":"C","text":"def detect_sensitive_words(text, sensitive_words): for word in text.split(): if word in sensitive_words: return True return False","correct":true},{"key":"D","text":"def detect_sensitive_words(text, sensitive_words): return text in sensitive_words","correct":false},{"key":"E","text":"import nltk def detect_sensitive_words(text, sensitive_words): tokens = nltk.word_tokenize(text) return any(token in sensitive_words for token in tokens)","correct":true},{"key":"F","text":"def detect_sensitive_words(text, sensitive_words): try: return any(word in text.lower() for word in sensitive_words) except AttributeError: # in case text is not a string return False","correct":true}]', 'ABCEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 169, 'multi', '在使用大模型生成课程内容的过程中,建议通过以下哪些方式提高生成内容的质量和准确性?', '[{"key":"A","text":"提供详细且清晰的输入提示词","correct":true},{"key":"B","text":"增加输入数据的数量","correct":false},{"key":"C","text":"根据模型的反馈不断优化提示词","correct":true},{"key":"D","text":"使用多个模型进行生成并比较结果","correct":true},{"key":"E","text":"使用固定的模板进行生成","correct":false}]', 'ACD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 170, 'multi', '在微调模型并使用模型检查点 (checkpointing) 时,哪些策略可以帮助选择和保存最佳模型?', '[{"key":"A","text":"仅保存每个epoch的模型","correct":false},{"key":"B","text":"当验证准确率提升时保存模型","correct":true},{"key":"C","text":"保存训练损失最低的模型","correct":false},{"key":"D","text":"定期保存模型以防训练中断","correct":true},{"key":"E","text":"保存验证损失最低的模型","correct":true},{"key":"F","text":"每当模型参数更新时保存","correct":false}]', 'BDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
