INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 186, 'multi', '下列关于将AgentModule类设计为基类的原因,正确的有哪些?', '[{"key":"A","text":"简化子类中的构造函数,减少重复代码","correct":true},{"key":"B","text":"由于Python不支持多重继承,因此需要这样设计","correct":false},{"key":"C","text":"允许每个子类定义自己的query方法,增加灵活性","correct":true},{"key":"D","text":"作为一个基类,可以方便地隐藏私有属性,保护数据","correct":false},{"key":"E","text":"提供统一的call方法以便通过相同的方式调用所有子类","correct":true},{"key":"F","text":"使得多个不同的代理模块可以共享相同的接口,实现代码复用","correct":true}]', 'ACEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 187, 'multi', '用户上传了一个包含复杂表格的Markdown文档,使用默认的RAG流程进行问答。用户提问关于 表格中特定单元格含义的问题时,大模型经常给出错误或不相关的答案。请问以下哪些方案可以尝 试解决这个问题?', '[{"key":"A","text":"对用户提问进行预处理,提取表格相关的关键词。","correct":true},{"key":"B","text":"在文档切片时,将表格的行列信息添加到每个单元格的Chunk中。","correct":true},{"key":"C","text":"将表格转换成JSON格式,然后使用JSONLoader加载数据。","correct":true},{"key":"D","text":"使用OCR技术识别表格中的文字,并将识别结果添加到文本中。","correct":false},{"key":"E","text":"使用更强大的Embedding模型。","correct":true},{"key":"F","text":"增加训练数据,让大模型更好地理解表格内容。","correct":false}]', 'ABCE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 188, 'multi', '有关输出格式要素的描述,以下哪项是正确的?', '[{"key":"A","text":"输出格式不影响大模型的应答","correct":false},{"key":"B","text":"不需要明确不期望输出的内容","correct":false},{"key":"C","text":"可使用案例来提示大模型的输出","correct":true},{"key":"D","text":"应明确指出枚举值的范围","correct":true},{"key":"E","text":"明确提供要输出的内容类型","correct":true},{"key":"F","text":"无需结合样例来明确输出格式","correct":false}]', 'CDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 189, 'multi', '以下哪些措施可以提高大模型在私域场景下的安全性?', '[{"key":"A","text":"对相关人员进行安全培训","correct":true},{"key":"B","text":"建立完善的安全incident响应机制","correct":true},{"key":"C","text":"使用开源的数据管理软件","correct":false},{"key":"D","text":"将所有数据存储在云端","correct":false},{"key":"E","text":"定期更新大模型和相关软件","correct":true},{"key":"F","text":"对大模型进行持续的安全评估和测试","correct":true}]', 'ABEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
