INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 191, 'multi', '关于Loss function & Cost function,下面描述正确的是?', '[{"key":"A","text":"拟合任意复杂函数","correct":false},{"key":"B","text":"用于度量当前所设置的参数是否合适","correct":true},{"key":"C","text":"决定神经元是否被激活并传递信息","correct":false},{"key":"D","text":"帮助寻找函数的参数最优解","correct":true}]', 'BD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
