INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 193, 'multi', '你开发了一个公司制度文件的RAG问答机器人。在测试时你发现提问“公司几点上班”,召回的 文本段包含公司福利等信息,作息信息由于排名靠后而没有被召回。以下哪两个措施更有助于解决 这一问题?', '[{"key":"A","text":"更换一个性能更优秀的Embedding模型","correct":true},{"key":"B","text":"优化生成阶段的提示词模板","correct":false},{"key":"C","text":"使用重排(rerank)技术","correct":true},{"key":"D","text":"更换一个性能更优秀的大模型","correct":false}]', 'AC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 194, 'multi', '通过LlamaIndex创建RAG应用,关于下面这段代码作用的描述正确的有哪些? def get_documents(path): documents = SimpleDirectoryReader(path).load_data() document = Document(text="\\n\\n".join([doc.text for doc in documents])) replacements = { ''!'': ''!'', ''?'': ''?'', ''。'': ''.'' } for src, dst in replacements.items(): document.text = document.text.replace(src, dst) return document', '[{"key":"A","text":"将所有Document对象合并为一个Document对象","correct":true},{"key":"B","text":"对乱码内容进行数据清洗","correct":false},{"key":"C","text":"将中文的标点符号预先转化为英文标点符号,使得切分时不会使得chunk长度过长","correct":true},{"key":"D","text":"将指定文件夹中的文件加载为document对象","correct":true}]', 'ACD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 195, 'multi', '一家教育科技公司拟开发AI教学产品,以下哪些方案能体现“个性化、智能化、普惠教育”?', '[{"key":"A","text":"自适应学习平台根据学生水平动态调整题库","correct":true},{"key":"B","text":"用VR实验室模拟替代昂贵的物理实验,降低教学成本","correct":true},{"key":"C","text":"方言识别系统辅助少数民族学生练习普通话","correct":true},{"key":"D","text":"选择题自动判卷,问答题错别字纠正","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 196, 'multi', 'qwen2.5-1.5b模型训练过程中较大的batchsize会带来哪些影响?', '[{"key":"A","text":"帮助模型充分地学习训练集","correct":false},{"key":"B","text":"可能导致模型泛化性能下降","correct":true},{"key":"C","text":"加速训练过程","correct":true},{"key":"D","text":"GPU显存消耗更大","correct":true}]', 'BCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 197, 'multi', '以下哪些选项是abstract_generator函数中提示词模板的关键组成部分? def abstract_generator(document): prompt_template = """【角色背景】 你是一个专业的审稿人,你将阅读文稿,并生成摘要 【任务要求】 你将看到一篇文章。请提取文章的主旨。 【输出要求】 请以json格式输出,不要输出其他内容 摘要本身的内容不超过40个字 【用户输入】 以下是用户输入,请审阅:""" query = prompt_template + document # ...调用大模型', '[{"key":"A","text":"任务要求描述","correct":true},{"key":"B","text":"角色背景设定","correct":true},{"key":"C","text":"输出格式要求","correct":true},{"key":"D","text":"错误处理机制","correct":false},{"key":"E","text":"用户输入示例","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 198, 'multi', '在APIAssistantAgent的query方法中,dashscope.Runs.wait的作用是什么? class APIAssistantAgent(AgentModule): def query(self, query:str): message = dashscope.Messages.create(self.thread.id, content=query) message_run = dashscope.Runs.create(self.thread.id, assistant_id=self.assistant.id) run_status = dashscope.Runs.wait(message_run.id, thread_id=self.thread.id) if run_status.required_action: self._forward_and_submit_outputs(run_status) run_status = dashscope.Runs.wait(run_status.id, thread_id=self.thread.id) msgs = dashscope.Messages.list(self.thread.id) answer = json.load(json.dumps(msgs, default=lambda o: o.__dict__))[''data''][0][''content''][0][''text''][''value''] return answer', '[{"key":"A","text":"返回请求的实时进度,对于调试非常有用","correct":false},{"key":"B","text":"等待所有的辅助工具输出,确保信息的完整性","correct":true},{"key":"C","text":"监听后台请求,并在用户的等待期间消耗资源","correct":false},{"key":"D","text":"确保所有消息都已处理并存储好","correct":false},{"key":"E","text":"阻塞当前线程,直到请求的响应准备好为止","correct":true},{"key":"F","text":"提供异步呼叫的机制,以提升查询响应速度","correct":false}]', 'BE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 199, 'multi', '把API Key配置到环境变量里有哪些优点?', '[{"key":"A","text":"提高大模型的回复速度","correct":false},{"key":"B","text":"提高大模型的回复准确率","correct":false},{"key":"C","text":"降低泄漏风险","correct":true},{"key":"D","text":"在其它代码中也可以直接加载环境变量,无需记住又长又复杂的API Key","correct":true}]', 'CD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 200, 'multi', '已知prompt_template定义了让大模型生成摘要的具体要求,以下哪些措施可以提高摘要生成函数 的生成质量?', '[{"key":"A","text":"将document分成多个段落,分别生成摘要,最后合并。","correct":true},{"key":"B","text":"在prompt_template中明确指出需要提取文章的主旨。","correct":true},{"key":"C","text":"不使用prompt_template,直接调用大模型。","correct":false},{"key":"D","text":"在prompt_template中提供一些示例摘要。","correct":true},{"key":"E","text":"在prompt_template中提供更详细的输出格式要求,例如指定摘要的长度、语气等。","correct":true}]', 'ABDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 201, 'multi', '为了尽量减少大模型应用的幻觉,以下哪些措施是有效的?', '[{"key":"A","text":"对生成内容进行后处理和验证","correct":true},{"key":"B","text":"使用参数量小更适合本地部署的模型","correct":false},{"key":"C","text":"引入知识库补充大模型缺少的行业知识","correct":true},{"key":"D","text":"在提示词中要求禁止虚构内容,遇到无法回答的问题可以直接回复不知道","correct":true}]', 'ACD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 202, 'multi', '以下关于CosyVoice的描述,哪些是正确的?', '[{"key":"A","text":"CosyVoice是一个文本转语音模型。","correct":true},{"key":"B","text":"CosyVoice可以直接生成视频。","correct":false},{"key":"C","text":"CosyVoice支持实时流式语音合成。","correct":true},{"key":"D","text":"CosyVoice可以用于语音识别。","correct":false}]', 'AC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 203, 'multi', '独立部署的模型服务的监控显示QPS突增500%。 哪些项是可能的原因?', '[{"key":"A","text":"前端生成的语音文件格式与模型期望不匹配","correct":false},{"key":"B","text":"突增请求中包含大量触发模型Bug的异常音频","correct":true},{"key":"C","text":"语言模型未针对专业术语做优化,意图理解准确率低","correct":false},{"key":"D","text":"处理能力达模型在高并发下过载,达到上限","correct":true}]', 'BD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 204, 'multi', '选择LORA秩(r)时需考虑哪些因素?', '[{"key":"A","text":"训练数据量","correct":true},{"key":"B","text":"基础模型参数量","correct":true},{"key":"C","text":"任务复杂度","correct":true},{"key":"D","text":"GPU显存容量","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 205, 'multi', '以下哪些选项属于提示词要素中的"输出格式(OutputFormat)"?', '[{"key":"A","text":"请你总结一下这篇文章的主要内容。","correct":false},{"key":"B","text":"请用表格形式展示结果。","correct":true},{"key":"C","text":"假设你是一个资深律师。","correct":false},{"key":"D","text":"请使用JSON格式输出。","correct":true},{"key":"E","text":"我希望你以第一人称的口吻写作。","correct":false},{"key":"F","text":"结果需要包含姓名、年龄和地址。","correct":false}]', 'BD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 206, 'multi', '关于多模态技术底层原理,正确的说法是?', '[{"key":"A","text":"图像理解模型也需要先将视频或图像分词化再做处理","correct":true},{"key":"B","text":"实现「方言语音合成」需要训练模型建立方言音素与标准发音的映射关系","correct":true},{"key":"C","text":"视频合成所花费的时间与可用的算力呈负相关","correct":true},{"key":"D","text":"文生图模型生成不同尺寸图像时,必须重新训练模型","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 207, 'multi', '在使用大语言模型时,什么是“样例”的作用?', '[{"key":"A","text":"确定目标用户","correct":false},{"key":"B","text":"辅助模型生成单一答案","correct":true},{"key":"C","text":"明确限制模型的回答长度","correct":false},{"key":"D","text":"提供有指导性的案例","correct":true},{"key":"E","text":"设定模型的情感色彩","correct":true},{"key":"F","text":"抽象出实现方案","correct":false}]', 'BDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 208, 'multi', 'AssistantAPI中Message类包含了各类关于消息的函数,以下哪些选项属于Message类中的函数?', '[{"key":"A","text":"update","correct":true},{"key":"B","text":"search","correct":false},{"key":"C","text":"retrieve","correct":true},{"key":"D","text":"create","correct":true},{"key":"E","text":"list","correct":true}]', 'ACDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 209, 'multi', '以下哪些场景适合使用流式对话LLM_MODEL.stream_chat(messages)?', '[{"key":"A","text":"实时聊天机器人,需要立即响应用户输入。","correct":true},{"key":"B","text":"需要对大模型的输出进行实时监控和干预的场景。","correct":true},{"key":"C","text":"用户需要快速获得初步结果,后续可以继续补充信息完善结果。","correct":true},{"key":"D","text":"只需要一次性返回完整结果的简单任务,例如翻译单个单词。","correct":false},{"key":"E","text":"需要处理长文本输入的场景,可以逐步返回结果,避免超时。","correct":true}]', 'ABCE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 210, 'multi', '构建高质量的数学题微调数据集应包含哪些要素?', '[{"key":"A","text":"包含详细分步推导","correct":true},{"key":"B","text":"统一使用LaTeX公式或Markdown格式输出公式","correct":true},{"key":"C","text":"大量的数学题解题数据","correct":true},{"key":"D","text":"覆盖多种解题思路","correct":true}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 211, 'multi', '关于大模型在文本处理中的局限性,以下哪些陈述是准确的?', '[{"key":"A","text":"即使有合适的系统提示词,大模型生成的内容仍需人工复审以保证质量","correct":true},{"key":"B","text":"大模型技术已经完全成熟,能够无差错地执行所有文本转换和润色任务","correct":false},{"key":"C","text":"大模型可能在处理特定领域专业术语时出现误解","correct":true},{"key":"D","text":"大模型对用户查询的依赖性极强,如果查询表述不清,结果可能偏离预期","correct":true},{"key":"E","text":"在没有明确指示的情况下,大模型可能无法自动识别源语言和目标语言","correct":true}]', 'ACDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 212, 'multi', '在进行RAGAS评测时,使用通过自定义API封装的langchainLLM对象主要有哪些优点?', '[{"key":"A","text":"可以在API中定义langchainLLM类中不支持指定的参数","correct":true},{"key":"B","text":"由于langchain官方封装好的模型有限,因此通过自定义方法选择更多模型","correct":true},{"key":"C","text":"可以打印出中间结果,帮助评测人员了解分数来源","correct":true},{"key":"D","text":"无需输入APIKey即可使用大模型","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 213, 'multi', '通过LlamaIndex创建RAG应用,在修改默认prompt时,包含以下哪些步骤?', '[{"key":"A","text":"定义新的prompt字符串,将chunk和query的位置空出来","correct":true},{"key":"B","text":"使用新的prompt初始化一个PromptTemplate对象","correct":true},{"key":"C","text":"对新的prompt进行保存,使得LlamaIndex中的源代码prompt也变成中文","correct":false},{"key":"D","text":"用index的update_prompts方法将新的prompt同步上去","correct":true}]', 'ABD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 214, 'multi', '在下面的代码片段中,哪些是微调大语言模型训练循环中必要的步骤?', '[{"key":"A","text":"model.train()","correct":true},{"key":"B","text":"loss = criterion(predictions, targets)","correct":true},{"key":"C","text":"predictions = model(inputs)","correct":true},{"key":"D","text":"optimizer.step()","correct":true},{"key":"E","text":"optimizer.zero_grad()","correct":true},{"key":"F","text":"loss.backward()","correct":true}]', 'ABCDEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 215, 'multi', '在多轮对话场景中,以下哪些方案,更有利于保障用户体验的同时,降低大模型使用成本?', '[{"key":"A","text":"在多轮对话场景中使用支持长上下文缓存的大模型API","correct":true},{"key":"B","text":"每次对话仅保留最近2轮历史,避免携带过长的上下文","correct":false},{"key":"C","text":"按照100的长度,对历史对话截断,避免携带上下文过长","correct":false},{"key":"D","text":"在多轮对话场景中,避免始终传入完整的历史对话,而是用最早的历史对话做总结处理后携带在 对话中","correct":true}]', 'AD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 216, 'multi', '某大型公司对每位员工都有多条文档记录。RAG在检索时只依赖Embedding相似度,有时召回了 不匹配的“同名员工”信息。为提高准确度,你会如何处理?', '[{"key":"A","text":"给每条记录打标签(如部门、邮箱)并结合标签过滤","correct":true},{"key":"B","text":"修改大模型为qwen-max","correct":false},{"key":"C","text":"改用TokenTextSplitter","correct":false},{"key":"D","text":"提高相似度阈值,过滤噪声","correct":true}]', 'AD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 217, 'multi', '你正在开发一个机器学习领域的答疑机器人,辅助学生学习,但你对该领域专业知识掌握有 限,以下哪些策略更有助于你改进提示词设计?', '[{"key":"A","text":"邀请机器学习课程助教一起审核和改进提示词,要求其按照一定的结构来回答问题","correct":true},{"key":"B","text":"要求大模型扮演「机器学习教授」,结合学生认知水平,重新写出更结构化的提示词","correct":true},{"key":"C","text":"按照自己的理解要求大模型按照一定的结构来回答问题","correct":false},{"key":"D","text":"保持提示词简单,避免引入错误的信息","correct":false}]', 'AB') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 218, 'multi', '某电商公司需开发一个客服机器人处理“退换货政策咨询”和“商品推荐”任务,下列哪两种角色应 该深度参与提示词设计?', '[{"key":"A","text":"产品经理(定义用户场景和业务流程)","correct":true},{"key":"B","text":"前端开发工程师(负责对话界面实现)","correct":false},{"key":"C","text":"算法工程师(擅长模型调优和参数调整)","correct":false},{"key":"D","text":"客服部门主管(熟悉用户高频问题和政策细节)","correct":true}]', 'AD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 219, 'multi', '你在开发的招聘答疑机器人,在回答“产品经理的岗位职责有哪些”时,输出的职责经常包含客户 经理的工作职责。经排查发现,不同岗位的说明文档使用了相同的模板,文档切片时经常将#客户经 理#岗位和#产品经理#岗位的职责主要是这样描述的。以下哪两种方法能有效解决这个问题?', '[{"key":"A","text":"使用ReRank对检索结果再次排序","correct":false},{"key":"B","text":"在处理文档时,对于文档中的二级标题,自动拼接文档名称,如##岗位职责会被拼接为##客户经 理-岗位职责","correct":true},{"key":"C","text":"在建立索引时,以文档名称建立标签,检索阶段使用标签+向量混合检索","correct":true},{"key":"D","text":"调高大模型temperature参数,提高大模型匹配正确答案数据的概率","correct":false}]', 'BC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 220, 'multi', '基于字符的文档切片方法有哪些潜在的缺点?', '[{"key":"A","text":"难以实现","correct":false},{"key":"B","text":"可能导致语义分离","correct":true},{"key":"C","text":"需要大量的存储空间","correct":false},{"key":"D","text":"计算复杂度高","correct":false},{"key":"E","text":"切片大小不均匀","correct":false},{"key":"F","text":"可能导致上下文丢失","correct":true}]', 'BF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 221, 'multi', '选择LoRA权重时需考虑哪些因素?', '[{"key":"A","text":"GPU显存容量","correct":true},{"key":"B","text":"训练数据量","correct":true},{"key":"C","text":"任务复杂度","correct":true},{"key":"D","text":"基础模型参数量","correct":true}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 222, 'multi', '你通过RAG为用户提供商品推荐服务。用户反馈说,在搜索“包子”时,推荐结果中经常出现“书 包”的商品信息。后台分析发现,召回阶段确实会夹杂部分无关商品的信息。以下哪些措施能够有效 提升该系统的推荐效果?', '[{"key":"A","text":"降低检索阶段的相似度阈值","correct":false},{"key":"B","text":"优化大模型的prompt,强调要重点关注用户问题,避免输出无关商品信息","correct":true},{"key":"C","text":"在知识库中剔除包含相关的内容","correct":false},{"key":"D","text":"微调大模型,提高其在面对包含噪声数据的信息时筛选有效信息的能力","correct":true}]', 'BD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 223, 'multi', '通过Llama index创建RAG应用,这段代码有哪些问题? python query_engine = index.as_query_engine( similarity_top_k=3, streaming=True, node_postprocessors=[ DepthScopeRank(top_n=8, model="gte-rerank"), SimilarityPostprocessor(similarity_cutoff=1)] ) response = query_engine.retrieve("需求分析使用的工具是什么?") response.print_response_stream()', '[{"key":"A","text":"query_engine不支持retrieve","correct":true},{"key":"B","text":"重排选中的chunk数大于初步召回的chunk数","correct":true},{"key":"C","text":"相似度阈值设置过高","correct":true},{"key":"D","text":"Llama index在RAG回答时不可以使用流式输出","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 224, 'multi', '微调qwen2.5-1.5b模型过程中发现模型开始欠拟合,可采取的优化措施包括?', '[{"key":"A","text":"增加训练数据量","correct":true},{"key":"B","text":"增加训练集迭代次数(epoch)","correct":false},{"key":"C","text":"增加lora_rank值","correct":true},{"key":"D","text":"学习率增加一倍","correct":false}]', 'AC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 225, 'multi', '一家旅游公司计划推出一款沉浸式个性化AI导游产品,以下哪些功能设计可以有效提升产品的 吸引力和实用性?', '[{"key":"A","text":"使用大语言模型为游客实时生成个性化的景点介绍,结合游客的兴趣和历史游览记录。","correct":true},{"key":"B","text":"开发一个路径规划系统,根据实时交通和天气情况为游客推荐最佳游览路线。","correct":true},{"key":"C","text":"利用图像识别技术分析游客拍摄的照片,自动标注景点名称并提供相关背景信息。","correct":true},{"key":"D","text":"提供一个语音讲解的随身pad,确保所有游客听到的内容完全相同。","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 226, 'multi', '视频合规检测的关键步骤包括下列哪些选项?', '[{"key":"A","text":"视频上传后的用户评论分析","correct":false},{"key":"B","text":"视频预处理,例如视频分段和帧提取","correct":true},{"key":"C","text":"音频合规检测","correct":true},{"key":"D","text":"视频编码格式的选择","correct":false},{"key":"E","text":"图片合规检测","correct":true},{"key":"F","text":"文本合规检测(包括字幕和音频转录文本)","correct":true}]', 'BCEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 227, 'multi', 'user_query="请帮我润色一下如下文段,让文字优美适合朗读:小猫玩毛线球。"为了让大模型更 好地理解润色需求,可以补充哪些附加说明到user query中?', '[{"key":"A","text":"尽量保持原文的核心意思不变","correct":false},{"key":"B","text":"将文字翻译成英文","correct":false},{"key":"C","text":"希望润色后的文字更加生动活泼","correct":true},{"key":"D","text":"请使用比喻和拟人的修辞手法","correct":true},{"key":"E","text":"把这段文字扩展成一个500字左右的小故事","correct":false},{"key":"F","text":"目标读者是小学三年级的学生","correct":false}]', 'CD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 228, 'multi', '用户多次反馈“AI回答中有捏造内容”,排查后发现是当知识库没有相关内容时,大模型直接虚 构答案。为减少此情况,你可以怎么做?', '[{"key":"A","text":"在百炼RAG应用中将回答范围设置为“仅知识库范围”","correct":true},{"key":"B","text":"调高temperature值","correct":false},{"key":"C","text":"使用ReRank对检索结果再次排序","correct":false},{"key":"D","text":"使用提示词,无匹配就明确回复“无法回答”","correct":true}]', 'AD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 229, 'multi', '为了将RAGAS评测适配到中文问答场景,有哪些有效方法?', '[{"key":"A","text":"使用中文能力较强的大模型","correct":true},{"key":"B","text":"将RAGAS自带的prompt翻译为中文再传入","correct":true},{"key":"C","text":"在faithfulness中修改json.dumps函数,使其返回中文而非unicode码","correct":false},{"key":"D","text":"在Systemprompt中提醒大模型:你要适配到中文问答场景","correct":true}]', 'ABD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 230, 'multi', '关于Qwen-Max、CosyVoice和moviepy的协同使用,以下哪些说法是正确的?', '[{"key":"A","text":"CosyVoice可以将文本转换为音频。","correct":true},{"key":"B","text":"CosyVoice的主要功能是视频剪辑。","correct":false},{"key":"C","text":"moviepy可以直接将文本转换为视频。","correct":false},{"key":"D","text":"Qwen-Max主要用于生成视频字幕。","correct":false},{"key":"E","text":"moviepy可以用来获取音频文件的持续时间,用于生成字幕。","correct":true},{"key":"F","text":"使用这三个工具的典型流程是,Qwen-Max->CosyVoice->moviepy。","correct":true}]', 'AEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 231, 'multi', '在创建APIAssistantAgent的过程中,将functions参数作为字典传入的解释正确的有哪些? class APIAssistantAgent(AgentModule): def __init__(self, name:str="", description:str="", model:str="", instructions:str="", tools: List=[], functions: Dict={}, assistant_id: str=None): name, description create name=name, description=description, instructions=instructions, tools=tools, verify_status_code(self.assistant) else: assistant via id self.assistant = dashscope retrieve(assistant_id = assistant_id) self.name, self.description = self.assistant.name, self.assistant.description self.assistant_id = self.assistant.id self.funcs = functions self.thread = dashscope.Threads.create() verify_status_code(self.thread)', '[{"key":"A","text":"这样可以方便地根据函数名来动态调用对应的函数","correct":true},{"key":"B","text":"由于Python中的类只能接收一个类型的参数,字典是唯一选择","correct":false},{"key":"C","text":"为了让智能体能够调用不同的函数来满足用户的请求","correct":true},{"key":"D","text":"该结构为智能体的多任务处理提供了更高的可扩展性","correct":true},{"key":"E","text":"因为字典结构可以提供键值对,便于存储函数的信息","correct":true},{"key":"F","text":"字典可以支持函数参数的动态传递,提高灵活性","correct":true}]', 'ACDEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 232, 'multi', '你写了一个提示词“请用适合简报的形式,以每篇100字的篇幅总结今早的十大新闻”。你希望大 模型能按照提示词完成任务,以下哪些方案可行?', '[{"key":"A","text":"设计提示词,明确要求大模型要基于今天最新的新闻来总结,避免基于历史新闻总结","correct":false},{"key":"B","text":"设计提示词,结合functioncall,让大模型回答时效性问题时,调用搜索工具","correct":true},{"key":"C","text":"整理历史新闻库,构建一个RAG应用,让大模型回答时参考知识库中的新闻","correct":false},{"key":"D","text":"使用阿里云百炼平台的qwen-plus,并且调用API时设置enable_search=True","correct":true}]', 'BD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 233, 'multi', '以下哪些代码片段可以用于检测用户输入中是否包含敏感词?', '[{"key":"A","text":"def detect_sensitive_words(text, sensitive_words): for word in text.split(): if word in sensitive_words: return True return False","correct":true},{"key":"B","text":"def detect_sensitive_words(text, sensitive_words): return any(word in text for word in sensitive_words)","correct":true},{"key":"C","text":"def detect_sensitive_words(text, sensitive_words): try: return any(word in text.lower() for word in [w.lower() for w in sensitive_words]) except AttributeError: return False","correct":true},{"key":"D","text":"import nltk def detect_sensitive_words(text, sensitive_words): tokens = nltk.word_tokenize(text) return any(token in sensitive_words for token in tokens)","correct":true},{"key":"E","text":"def detect_sensitive_words(text, sensitive_words): return text in sensitive_words","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 234, 'multi', '对于RAG应用的理解,以下哪两项描述是正确的?', '[{"key":"A","text":"RAG中的\\"R\\"(Retrieval,检索)通常依赖专门的检索模块,从外部知识库中提取与输入问题最 相关的文本信息,为后续解答提供依据","correct":true},{"key":"B","text":"在RAG框架中,大模型仅起信息汇总作用,即便其本身不熟悉某些领域的知识,也一定可以凭借 总结能力准确回答问题","correct":false},{"key":"C","text":"RAG的\\"G\\"(Generation,生成),指的是大模型在得到参考知识与输入问题后进行回答的过程","correct":true},{"key":"D","text":"RAG的\\"A\\"(Augmented,增强),是通过提示词来实时训练模型,达到增强模型的效果","correct":false}]', 'AC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 235, 'multi', '你正在优化一个RAG系统,发现某些相似文本对的向量相似度较低,以下哪两种方法可以改善 这种情况?', '[{"key":"A","text":"更换效果更好的embedding模型","correct":true},{"key":"B","text":"将索引保存到本地并在运行时加载","correct":false},{"key":"C","text":"减少向量数据库的存储容量","correct":false},{"key":"D","text":"通过对比学习让相关文本对的向量相似度更高","correct":true}]', 'AD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 236, 'multi', '一家教育科技公司拟开发高级AI教学产品,旨在实现个性化、智能化、普惠教育。从多智能体 协作与自适应教学系统设计的角度,以下哪些系统架构方案是达成其核心目标的有效策略?', '[{"key":"A","text":"设计分层智能体架构,由策略智能体、教学智能体和评估智能体协同规划学习路径。","correct":true},{"key":"B","text":"部署基于共享内存的黑板(Blackboard)系统,实现各智能体间实时信息交换与决策。","correct":true},{"key":"C","text":"要求用户统一购买经过认证的高性能设备,将所有核心AI推理功能部署在用户设备上,避免隐私 风险。","correct":false},{"key":"D","text":"依赖人工专家团队进行实时干预作为教学策略调整的主要驱动力","correct":false}]', 'AB') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 237, 'multi', '哪些代码段涉及文本序列化和标准化?', '[{"key":"A","text":"tokenizer.texts_to_sequences(texts)","correct":true},{"key":"B","text":"pad_sequences(sequences, padding=''post'')","correct":false},{"key":"C","text":"vocab_size = len(tokenizer.word_index) + 1","correct":false},{"key":"D","text":"sequences = [seq[:MAX_SEQ_LEN] for seq in sequences]","correct":false},{"key":"E","text":"texts = [preprocess(text) for text in texts]","correct":true},{"key":"F","text":"embedding_matrix = np.zeros((vocab_size, EMBEDDING_DIM))","correct":false}]', 'AE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 238, 'multi', '在实现大模型辅助的新员工帮助应用中,以下哪些建议有助于提升用户体验?', '[{"key":"A","text":"为每个任务定制详细的系统提示词,确保大模型理解上下文。","correct":true},{"key":"B","text":"限制用户查询长度,因为长文本可能导致响应延迟或理解错误。","correct":false},{"key":"C","text":"引入多轮对话机制,允许用户基于大模型的初步回应进一步细化需求。","correct":true},{"key":"D","text":"由于大模型的准确性极高,无需提供反馈或修正机制。","correct":false},{"key":"E","text":"实现自动检测用户查询类型并调用相应的大模型处理策略,无需用户指定任务类型。","correct":true}]', 'ACE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 239, 'multi', '以下哪些选项体现了提示词要素中的“上下文(Context)”?', '[{"key":"A","text":"用户喜欢历史文化景点,不喜欢游乐场。","correct":true},{"key":"B","text":"请提供不少于三个景点的推荐。","correct":false},{"key":"C","text":"输出格式为JSON。","correct":false},{"key":"D","text":"请你扮演一位资深旅游博主。","correct":true},{"key":"E","text":"请根据用户提供的行程安排,推荐合适的旅游景点。","correct":false},{"key":"F","text":"用户计划前往北京旅游,时间为一周。","correct":true}]', 'ADF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 240, 'multi', '小李正在使用阿里云百炼大模型服务平台开发一款AI语音助手APP。为了确保APP能够顺利上 线,小李在开发过程中应注意哪些事项?', '[{"key":"A","text":"关注《生成式人工智能服务管理暂行办法》的最新动态,及时调整APP的功能和策略。","correct":true},{"key":"B","text":"在APP上线前完成算法备案手续。","correct":true},{"key":"C","text":"忽略备案要求,尽快上线抢占市场。","correct":false},{"key":"D","text":"对用户生成的AIGC内容进行审核和过滤,避免传播违规信息。","correct":true},{"key":"E","text":"收集用户数据前需获得用户明确同意,并保障用户数据安全。","correct":true},{"key":"F","text":"在APP中明确告知用户该应用使用了AIGC技术。","correct":true}]', 'ABDEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 241, 'multi', '以下哪些选项是把DASH SCOPE_API_KEY配置为环境变量的原因?', '[{"key":"A","text":"防止KEY泄漏","correct":true},{"key":"B","text":"配置为环境变量可以减少代码的行数。","correct":false},{"key":"C","text":"环境变量会自动被SDK读取和使用。","correct":true},{"key":"D","text":"环境变量可以加快程序的运行速度。","correct":false}]', 'AC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 242, 'multi', '你负责的短视频平台在接入多模态技术后出现故障。 1:用户输入“生成夏日海滩vlog背景”时,系统返回静态图片而非视频 2:视频自动剪辑功能无法识别冲浪板等特定物体 3:添加的AI解说语音与动画动作不同步 需要重点检查的技术环节是?', '[{"key":"A","text":"视频编辑时是否设置了正确的时间轴","correct":false},{"key":"B","text":"图像理解模型可能缺少对特定场景的训练数据","correct":true},{"key":"C","text":"仅使用了文生图模型来生成完整视频","correct":true},{"key":"D","text":"语音合成模型采样率不合适导致视频音画不同步","correct":true}]', 'BCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 243, 'multi', '以下哪些情况可能导致大模型检索不准确?', '[{"key":"A","text":"文档中包含大量的图片信息,而当前的文档解析器无法有效提取和理解图片内容。","correct":true},{"key":"B","text":"使用了基于深度学习的语义搜索引擎,但模型训练数据不足,导致检索结果不准确。","correct":true},{"key":"C","text":"文档中包含复杂的表格结构,而简单的文本解析器无法理解表格单元格之间的关系。","correct":true},{"key":"D","text":"使用了复杂的文档解析器,导致解析速度慢,影响检索效率。","correct":false},{"key":"E","text":"索引构建过程中使用了错误的embedding模型,导致语义相似度计算错误。","correct":true},{"key":"F","text":"文档切片时,仅简单地按照字符长度进行分割,丢失了文档的语义信息。","correct":true}]', 'ABCEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 244, 'multi', '某教育问答系统上线后,你通过监控日志发现模型有时会返回个人隐私信息,为防止此类敏感 信息泄露,可以采取以下哪三项措施?', '[{"key":"A","text":"过滤用户提问,避免诱导性问题","correct":true},{"key":"B","text":"在问答系统流式返回内容时,实时检测并过滤敏感信息","correct":true},{"key":"C","text":"增加知识库内容的多样性,减少隐私信息被召回的概率","correct":false},{"key":"D","text":"对教育知识库的内容进行脱敏处理","correct":true}]', 'ABD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 245, 'multi', '关于temperature和top_p参数的作用,以下哪三个描述是正确的?', '[{"key":"A","text":"较低的top_p可以提高生成内容的稳定性","correct":true},{"key":"B","text":"较低的temperature可以增加生成内容的多样性","correct":false},{"key":"C","text":"通常情况下,只需调整其中一个参数即可。","correct":true},{"key":"D","text":"较高的temperature可以增加生成内容的多样性","correct":true}]', 'ACD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 246, 'multi', '在RAGAS评测中,embedding模型的作用有哪些?', '[{"key":"A","text":"评估answer与ground_truth的相似度,从而计算answer_correctness","correct":true},{"key":"B","text":"评估每个chunk之间的相似度,从而剔除离群点","correct":false},{"key":"C","text":"评估context与answer的相似度,从而计算faithfulness","correct":true},{"key":"D","text":"评估answer与query的相似度,从而计算answer_relevancy","correct":true}]', 'ACD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 247, 'multi', 'RAG应用在检索时共召回了10条切片,其中3条高度相关,但这3条内容都来自相邻段落,却被 系统拆分成不同切片,从而导致回答时缺失连贯的上下文信息。哪些方案可进一步提升答案准确 度?', '[{"key":"A","text":"使用按照语义的切片策略,切分出语义更完整的切片","correct":true},{"key":"B","text":"调整切片大小使其覆盖完整更大段落范围","correct":true},{"key":"C","text":"采用滑动窗口策略生成重叠的文本切片","correct":true},{"key":"D","text":"提高temperature参数控制生成多样性","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 248, 'multi', '在决定模型微调前,你应该考虑以下哪些事情?', '[{"key":"A","text":"训练数据量是否达到微调的最低标准","correct":true},{"key":"B","text":"该任务是否更适合使用RAG","correct":true},{"key":"C","text":"提示词工程是否能达到预期效果","correct":true},{"key":"D","text":"训练服务器资源的成本","correct":true}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 249, 'multi', '实现早停法(early stopping)策略时,考虑的条件可能包括:', '[{"key":"A","text":"验证损失连续n轮不再下降","correct":true},{"key":"B","text":"验证损失达到预设阈值","correct":true},{"key":"C","text":"训练损失持续增加","correct":false},{"key":"D","text":"验证准确率连续提高","correct":false},{"key":"E","text":"训练准确率不再提高","correct":false},{"key":"F","text":"迭代次数达到预定最大值","correct":true}]', 'ABF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 250, 'multi', '在大语言模型微调的训练循环中,哪些步骤是必须包含的?', '[{"key":"A","text":"梯度裁剪","correct":false},{"key":"B","text":"模型保存","correct":false},{"key":"C","text":"正向传播","correct":true},{"key":"D","text":"反向传播","correct":true},{"key":"E","text":"超参数调整","correct":false},{"key":"F","text":"梯度更新","correct":true}]', 'CDF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 251, 'multi', '在RAGAS中,answer_correctness由哪些指标共同计算得来?', '[{"key":"A","text":"answer与context的语义相似度;","correct":false},{"key":"B","text":"answer与ground_truth的语义相似度;","correct":true},{"key":"C","text":"answer与query的一致性;","correct":false},{"key":"D","text":"基于ground_truth与answer计算answer的事实准确性;","correct":true}]', 'BD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 252, 'multi', '某金融智能风控系统在高峰期偶尔出现模型不可用的情况,以下哪些方案可以作为降级策略?', '[{"key":"A","text":"增加GPU实例数量","correct":false},{"key":"B","text":"切换至规则引擎兜底","correct":true},{"key":"C","text":"使用备份模型继续服务","correct":true},{"key":"D","text":"关闭部分非核心功能","correct":true}]', 'BCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 253, 'multi', 'faithfulness、answer_relevancy、context_recall、context_precision这些指标中,哪些指标仅评估检 索阶段的性能?', '[{"key":"A","text":"context_precision","correct":true},{"key":"B","text":"answer_relevancy","correct":false},{"key":"C","text":"context_recall","correct":true},{"key":"D","text":"faithfulness","correct":false}]', 'AC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 254, 'multi', '以下哪些方案,有助于提升大模型应用的用户体验?', '[{"key":"A","text":"等全部内容生成后一次性返回","correct":false},{"key":"B","text":"展示任务处理进度","correct":true},{"key":"C","text":"生成的内容流式输出","correct":true},{"key":"D","text":"将任务分解为多个步骤,并且将分步执行过程展示给用户","correct":true}]', 'BCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 255, 'multi', '以下哪两个参数的设置会影响训练时显存占用峰值的大小?', '[{"key":"A","text":"批量大小(batch_size)","correct":true},{"key":"B","text":"验证损失计算步数(evaluation_step)","correct":false},{"key":"C","text":"训练集迭代次数(epoch)","correct":false},{"key":"D","text":"LoRA秩(lora_rank)","correct":true}]', 'AD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 256, 'multi', '当你在使用一款基于大模型构建的创意助手,要求它一次性产生10条宣传文案时,发现生成的 文案千篇一律,缺乏多样性。为了在保证一定多样性的同时避免模型生成不符合主题的内容,可以 优先考虑以下哪些改进措施?', '[{"key":"A","text":"使用模糊的指令,让模型自由发挥。","correct":false},{"key":"B","text":"检查提示词是否过于局限,尝试在提示词中明确指定多个角度方向(如情感、风格、视角等)来 扩展其灵活性。","correct":true},{"key":"C","text":"固定top_p=0.1以确保最大范围的词汇选择。","correct":false},{"key":"D","text":"小幅调高temperature以保证生成内容的多样性。","correct":true}]', 'BD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 257, 'multi', '如果将RAG与开卷考试相比,下列哪两项描述最符合它们的相同之处?', '[{"key":"A","text":"都是通过引入外部知识来增强输出","correct":true},{"key":"B","text":"人的思维与大模型的权重参数,都会随着外部知识的输入而发生改变","correct":false},{"key":"C","text":"都需要提前对知识作出标记,来帮助检索","correct":true},{"key":"D","text":"都不需要对问题本身进行理解即可回答","correct":false}]', 'AC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 258, 'multi', 'AssistantAPI的Assistant类的各项功能中涵盖了以下哪些操作?', '[{"key":"A","text":"列举","correct":true},{"key":"B","text":"剪切","correct":false},{"key":"C","text":"复制","correct":false},{"key":"D","text":"删除","correct":true},{"key":"E","text":"更新","correct":true},{"key":"F","text":"创建","correct":true}]', 'ADEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 259, 'multi', '以下哪些任务可以使用ffmpeg完成?', '[{"key":"A","text":"提取视频中的音频。","correct":true},{"key":"B","text":"调整视频的分辨率。","correct":true},{"key":"C","text":"训练一个语音识别模型。","correct":false},{"key":"D","text":"将多个视频片段合并成一个视频。","correct":true},{"key":"E","text":"为视频添加水印。","correct":true},{"key":"F","text":"转换视频格式(例如mp4到avi)","correct":true}]', 'ABDEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 260, 'multi', '关于图片合规检查的技术手段,下列说法正确的有哪些?', '[{"key":"A","text":"可以使用目标检测算法如YOLO系列检测图片中的敏感物体,例如武器。","correct":true},{"key":"B","text":"OCR技术可以用于提取图片中的文字信息,用于后续的文本合规检测。","correct":true},{"key":"C","text":"水印和品牌标志检查与合规性无关,不需要进行检测。","correct":false},{"key":"D","text":"图片内容检测只能依靠人工审核,无法使用深度学习模型进行自动化分类。","correct":false},{"key":"E","text":"pHash算法可以用于版权检查,通过比较图像指纹识别相似图像。","correct":true},{"key":"F","text":"卷积神经网络(CNN)可以用于对图片内容的合规性进行分类,例如识别暴力内容。","correct":true}]', 'ABEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 261, 'multi', '以下哪些选项属于提示词要素中的样例(Sample)?', '[{"key":"A","text":"请你扮演一位医生。","correct":false},{"key":"B","text":"输入:汽车,输出:交通工具","correct":true},{"key":"C","text":"用户输入:“我想了解一下人工智能。”你的回复:“人工智能是......”","correct":true},{"key":"D","text":"请用表格形式展示结果。","correct":false},{"key":"E","text":"输入:苹果,输出:水果","correct":true},{"key":"F","text":"请你总结这篇文章的中心思想。","correct":false}]', 'BCE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 262, 'multi', '在开发一款基于大语言模型的会议纪要生成工具时,团队发现模型在处理会议记录时经常遗漏 关键决议内容,导致生成的纪要不够准确和全面。以下哪两个选项能较低成本地解决这一问题?', '[{"key":"A","text":"增加模型的训练数据量,特别是包含更多会议记录样本的数据集","correct":false},{"key":"B","text":"要求模型在输出纪要时使用特定格式(如紫色字体或表格形式)","correct":false},{"key":"C","text":"在提示词中明确角色定义,例如“你是一名专业秘书,负责从会议记录中提取所有关键决议和行动 项”","correct":true},{"key":"D","text":"要求模型先对会议记录中的行动项和决议进行逐句摘要标记,再生成最终的纪要","correct":true}]', 'CD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 263, 'multi', '哪种形式可以用作提示词的分隔符?', '[{"key":"A","text":"XML标签","correct":true},{"key":"B","text":"<|CO|>","correct":true},{"key":"C","text":"**","correct":false},{"key":"D","text":"...","correct":false},{"key":"E","text":"##","correct":true}]', 'ABE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 264, 'multi', '在以下含码段中,哪些是设置模型训练参数的例子?', '[{"key":"A","text":"learning_rate = 0.001","correct":true},{"key":"B","text":"model = \\"qwen-7b-chat\\"","correct":false},{"key":"C","text":"device = torch.device(''cuda'' if torch.cuda.is_available() else ''cpu'')","correct":false},{"key":"D","text":"optimizer = AdamW(model.parameters(), lr=learning_rate)","correct":true},{"key":"E","text":"num_epochs = 3","correct":true},{"key":"F","text":"batch_size = 64","correct":true}]', 'ADEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 265, 'multi', '你在构建一个RAG应用,以下哪些提示词模板是合理的?', '[{"key":"A","text":"检索到的相关内容为,{检索到的文本段}用户的问题是,{用户问题}请结合以上信息,给出准确且 简洁的回答。","correct":true},{"key":"B","text":"以下是用户的问题,{用户问题}","correct":false},{"key":"C","text":"以下是与问题相关的背景信息,{检索到的文本段}问题是,{用户问题}请基于背景信息,提供一个 合理且完整的答案。","correct":true},{"key":"D","text":"以下是检索到的内容,{检索到的文本段}","correct":false}]', 'AC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 266, 'multi', '某团队计划为法律咨询场景微调一个大模型。在正式启动微调前,团队需优先评估以下哪三 点?', '[{"key":"A","text":"通过设计专业法律术语提示词优化输出结果","correct":true},{"key":"B","text":"使用法律条文数据库构建知识检索增强生成(RAG)系统","correct":true},{"key":"C","text":"验证现有法律案例数据量是否满足微调的数据规模要求","correct":true},{"key":"D","text":"采购10块专业显卡用于本地训练","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 267, 'multi', '以下哪些描述符合基于语义的文档切片的理念?', '[{"key":"A","text":"使用机器学习模型对文档进行语义分析,并根据语义边界进行切分","correct":true},{"key":"B","text":"在Chunk中添加上下文信息,例如标题、父级列表项等","correct":true},{"key":"C","text":"将代码模块单独切出来,并标注其编程语言","correct":false},{"key":"D","text":"将文档按照固定长度进行切分","correct":false},{"key":"E","text":"将表格的每个单元格作为一个独立的Chunk","correct":false},{"key":"F","text":"根据文档的结构,例如标题、段落、列表等进行切分","correct":true}]', 'ABF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 268, 'multi', '在qwen-plus对messages进行回答后,如果你想按照当前对话基础继续提问,需要怎么做? LLM_MODEL = DashScope(modelname="qwen-plus") messages = [ChatMessage(role=MessageRole.SYSTEM, content="你负责教育内容开发公司的答疑,你 的名字叫公司小蜜,你要回答学员的问题。"),ChatMessage(role=MessageRole.USER, content="你 好")]', '[{"key":"A","text":"将大模型生成的AssistantMessage添加到messages列表中","correct":true},{"key":"B","text":"对话历史跟着模型名称走,所以只要继续指定模型为qwen-plus就可以了","correct":false},{"key":"C","text":"大模型不支持多轮对话","correct":false},{"key":"D","text":"将新的UserMessage添加到messages列表中","correct":true}]', 'AD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 269, 'multi', 'APIAssistantAgent示例代码query函数中,哪些步骤与大语言模型交互?', '[{"key":"A","text":"调用forward_and_submit_outputs函数","correct":true},{"key":"B","text":"调用dashscope.Runs.wait函数","correct":true},{"key":"C","text":"创建message对象","correct":false},{"key":"D","text":"调用dashscope.Messages.list函数","correct":false},{"key":"E","text":"解析msgs获取最终答案","correct":false},{"key":"F","text":"调用dashscope.Runs.create函数","correct":true}]', 'ABF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 270, 'multi', '你需要大模型从客户邮件中提取结构化数据(如姓名、订单号、问题类型),以下哪两个选项 有助于你达成这一目标?', '[{"key":"A","text":"提供你期望的JSON结构示例","correct":true},{"key":"B","text":"调低温度参数(Temperature)以降低随机性","correct":false},{"key":"C","text":"在任务目标中明确“输出JSON格式”","correct":true},{"key":"D","text":"要求模型分两步操作,先总结邮件内容,再提取字段","correct":false}]', 'AC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 271, 'multi', '某跨境电商平台的客服系统需要处理多语言用户咨询,在进行文本合规检查时发现部分违规内 容无法被检测出来。哪两个方案能提供多语言文本的合规检查效果?', '[{"key":"A","text":"强制要求用户使用英语提问,其他语言咨询转入人工处理","correct":false},{"key":"B","text":"建立多语言同义词库,覆盖常见违规表述的变体(如“免税代购”的谐音/缩写形式)","correct":true},{"key":"C","text":"使用跨语言语义理解模型,识别违规意图而非依赖关键词匹配","correct":true},{"key":"D","text":"将非英语内容翻译为英语后复用单语种审核规则","correct":false}]', 'BC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 272, 'multi', '以下哪些选项属于流式输出相比于非流式输出的优势?', '[{"key":"A","text":"能够提升大模型回复的效果","correct":false},{"key":"B","text":"能够给用户带来良好的阅读体验","correct":true},{"key":"C","text":"能够加快大模型回复的速度","correct":false},{"key":"D","text":"在网络连接时不会造成可能存在的超时错误","correct":true}]', 'BD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 273, 'multi', '小明开发了一款基于通义千问的AI写作助手小程序,计划在微信小程序平台上线。目前小程序 已经开发完成,但尚未提交任何合规备案申请。根据相关规定,小明应该如何操作?', '[{"key":"A","text":"直接上线,后续再补充备案材料。","correct":false},{"key":"B","text":"向应用商店提交应用,等待审核通过后再备案。","correct":false},{"key":"C","text":"下架小程序,停止运营。","correct":false},{"key":"D","text":"联系阿里云百炼大模型服务平台,咨询备案流程并按要求提交申请。","correct":true},{"key":"E","text":"无需备案,直接上线即可。","correct":false},{"key":"F","text":"先进行算法备案,获得备案号后再上线。","correct":true}]', 'DF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 274, 'multi', '以下哪些方法有助于你减少大模型应用的输出结果等待时间?', '[{"key":"A","text":"使用支持上下文缓存的模型API","correct":true},{"key":"B","text":"使用参数量更大的模型","correct":false},{"key":"C","text":"提前生成和复用内容","correct":true},{"key":"D","text":"减少输入Token数量","correct":true}]', 'ACD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 275, 'multi', '某游戏平台上线了一个辅助聊天机器人,可帮助玩家完成游戏内交易、提交客服工单,以及获 取实时游戏分析。有玩家发现机器人时常在简单客服请求时错误调用analytics工具。为改进这个多智 能体系统的工具使用准确性,应该怎么做?', '[{"key":"A","text":"删除analytics相关Agent","correct":false},{"key":"B","text":"在Agent指令中进一步明确各Agent的功能边界","correct":true},{"key":"C","text":"改进PlannerAgent的决策逻辑,精细化路由","correct":true},{"key":"D","text":"将游戏的所有代码库交给聊天机器人学习","correct":false}]', 'BC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 276, 'multi', '在初步构建好大模型应用后,应该对它进行“自动化评测”,如何理解自动化?', '[{"key":"A","text":"自动化的评测指标由大模型制定","correct":false},{"key":"B","text":"自动化的评测集由大模型生成","correct":false},{"key":"C","text":"自动化指的是通过引入大模型来减少人为查验的工作方式","correct":true},{"key":"D","text":"自动化的前提是要有业务专家参与构建评测集","correct":true}]', 'CD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 277, 'multi', '你发现大量员工信息都存放在PDF、Word文档里,部分还包含表格和图片,RAG无法正确提取 关键信息。你可以怎么处理?', '[{"key":"A","text":"手动复制粘贴所有文档内容","correct":false},{"key":"B","text":"使用OCR技术识别并提取图片中的文字","correct":true},{"key":"C","text":"强制用户只上传纯文本","correct":false},{"key":"D","text":"使用DashScopeParse等工具,对PDF/Word进行结构化解析","correct":true}]', 'BD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 278, 'multi', '你和同事在设计一个知识库答疑机器人,他提出了以下路线,哪两个是合理的?', '[{"key":"A","text":"大模型能力很强,我们把所有知识文件的内容丢给大模型让它总结。","correct":false},{"key":"B","text":"我们可以通过人工与大模型对公司的知识文件生成很多问答对,再使用问答对微调大模型,使大 模型了解我们公司的知识。","correct":true},{"key":"C","text":"相信大模型的能力,无需外部知识库支持,因为大模型已经预训练了海量数据。","correct":false},{"key":"D","text":"大模型最大输入长度有限,应该使用RAG,先召回最相关的文本段,将文本段与输入问题进行拼 接后输入大模型。","correct":true}]', 'BD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 279, 'multi', '在评测机制里,你发现自动化评分一直偏高,但实际用户反馈一般。以下哪三项有可能提高评 测的可信度?', '[{"key":"A","text":"基于现有的评测集,增加自动化评测的频次","correct":false},{"key":"B","text":"在构建测试集时,增加业务专家的打分环节","correct":true},{"key":"C","text":"根据线上用户问题类型的分布,修正测试样本集的问题分布","correct":true},{"key":"D","text":"调整自动化评测工程的提示词及阈值,让其更接近真实用户判断标准","correct":true}]', 'BCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 280, 'multi', '你发现检索到的切片里常常遗漏上下文,导致回答片段化。下列哪些是有效且合理的改进措 施?', '[{"key":"A","text":"改用“句子窗口切片”或“滑动窗口检索”","correct":true},{"key":"B","text":"增大chunk_overlap","correct":true},{"key":"C","text":"避免切片,将文档完整的拼接到提示词中","correct":false},{"key":"D","text":"适当调大召回文档切片数量(例如从Top3调整为Top5)","correct":true}]', 'ABD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 281, 'multi', '以下哪些含码片段可以有效地对用户输入进行清洗和预处理,以提高大模型应用的安全性?', '[{"key":"A","text":"将用户输入中的emoji表情符号替换为文本描述。","correct":true},{"key":"B","text":"将用户输入转换为小写。","correct":false},{"key":"C","text":"限制用户输入的长度。","correct":false},{"key":"D","text":"去除用户输入中的HTML标签。","correct":true},{"key":"E","text":"将用户输入中的URL替换为特殊的占位符。","correct":true},{"key":"F","text":"先把英文全部翻译为中文。","correct":false}]', 'ADE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 282, 'multi', '以下选项中属于使用分隔符的主要目的有哪些?', '[{"key":"A","text":"规范化文档格式","correct":true},{"key":"B","text":"明确提示词各要素之间的界限","correct":true},{"key":"C","text":"使文档看起来更复杂","correct":false},{"key":"D","text":"增加文字数量","correct":false},{"key":"E","text":"随意分割文本","correct":false},{"key":"F","text":"提高模型的运行速度","correct":false}]', 'AB') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 283, 'multi', '大语言模型微调相比预训练的优势有哪些?', '[{"key":"A","text":"更容易发现和修正模型偏差","correct":false},{"key":"B","text":"无需考虑模型的泛化能力","correct":false},{"key":"C","text":"减少了对大量无标注数据的依赖","correct":true},{"key":"D","text":"提高了模型在特定领域的准确性","correct":true},{"key":"E","text":"减少了计算资源的需求","correct":false},{"key":"F","text":"加快了模型收敛速度","correct":true}]', 'CDF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 284, 'multi', '下列含码片段中,哪些涉及模型训练过程中的正则化或优化策略?', '[{"key":"A","text":"weight_decay = 0.001","correct":true},{"key":"B","text":"criterion = nn.CrossEntropyLoss()","correct":false},{"key":"C","text":"optimizer = SGD(model.parameters(), lr=0.01, momentum=0.9)","correct":true},{"key":"D","text":"scheduler = StepLR(optimizer, step_size=10, gamma=0.1)","correct":true},{"key":"E","text":"model = nn.Dropout(p=0.2)","correct":true}]', 'ACDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 285, 'multi', '某公司正在开发一款智能客服系统,用于为用户提供多语言支持。在处理用户问题时,系统需 要准确翻译并解释一些内部非公开的领域术语。为了确保翻译和解释的高准确性,以下哪两个方案 能有效解决这一问题?', '[{"key":"A","text":"手动整理所有术语及其翻译,并作为提示词提供给模型","correct":true},{"key":"B","text":"要求模型在遇到未知术语时直接跳过,避免错误翻译","correct":false},{"key":"C","text":"提供3条术语的翻译示例,依赖模型自行推断其余术语的含义","correct":false},{"key":"D","text":"通过RAG技术接入该领域术语数据库,动态检索并翻译术语","correct":true}]', 'AD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 286, 'multi', '一家金融公司基于RAG系统搭建自研交易模型查询功能,出现检索结果常返回通用文档、而非 知识库中交易模型的高级解决方案,想系统性解决此问题,架构师应优先选择哪两项措施?', '[{"key":"A","text":"实施混合检索融合模型(如BM25模型)与向量搜索","correct":true},{"key":"B","text":"引入Cross-Encoder模型进行检索结果重排序","correct":true},{"key":"C","text":"调整分块重叠分块大小优化文本切片效果","correct":false},{"key":"D","text":"建立“查询-理想文档”的“黄金标准”评测集","correct":false}]', 'AB') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 287, 'multi', '一家航空公司搭建AI服务系统,该系统在响应用户针对业务手册的查询需求时,频繁返回宽泛 的手册章节内容,无法精准定位到用户所需的具体条款或关键信息。若想系统性解决这一问题,应 优先采取哪两项策略?', '[{"key":"A","text":"优化查询意图识别模型,结合航空业务场景(如订票、改签、行李托运)的语义特征,精准拆解 用户查询的核心诉求","correct":true},{"key":"B","text":"构建航空业务专属的知识图谱,关联手册章节、具体条款、业务场景、常见问题等信息,强化内 容间的逻辑关联","correct":true},{"key":"C","text":"简化AI服务系统的返回机制,减少冗余章节的展示,仅提取与用户查询高度匹配的关键句子片段","correct":false},{"key":"D","text":"在用户输入查询时,引导用户补充精确的手册章节编号或核心关键词,缩小检索范围","correct":false}]', 'AB') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 288, 'multi', '一家AI应用可以辅助有关部门制作案情推演材料,通过融合文档片段与证物照片来生成图文并 茂的案情摘要。为确保交付给客户的产出是专业且负责任的,以下哪些流程是强制性的?', '[{"key":"A","text":"将AI生成的内容提交给另一个知名的开源通用大模型进行事实核查。","correct":false},{"key":"B","text":"对模型训练的案情资料进行彻底的、不可逆的匿名化和脱敏处理。","correct":true},{"key":"C","text":"所有AI生成的摘要在交付前,需交由人类法律专家进行审核确认。","correct":true},{"key":"D","text":"为AI生成的每一项关键事实建立可溯源机制,明确链接原始证物。","correct":true}]', 'BCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 289, 'multi', '某顶尖医院计划开发一个“多模态肺癌风险筛查辅助系统”,目标是高精度地识别潜在的早期病 灶,并对医生报告中可能存在的描述与影像不符之处进行高亮提示。准确性、可解释性和安全性是 最高优先级。为了构建一个在临床上高度可靠、值得信赖的系统,你会采用哪些关键技术或设计?', '[{"key":"A","text":"为了快速提升模型泛化能力,参考ImageNet,需要大量获取互联网上公开的肺部影像数据集,与 医院内部数据集直接合并进行训练。","correct":false},{"key":"B","text":"采用多模态模型,输入丰富的各类医疗检测数据,端到端一次性输出风险评分和修正报告。","correct":false},{"key":"C","text":"设计一个基于多智能体的“审核”流程:一个Vision Agent分析影像,一个TextAgent分析报告,一 个Clinical Agent参照权威医学知识库(如UMLS)对前两者的发现进行交叉验证。","correct":true},{"key":"D","text":"图像理解模型在输出“是否存在病灶”的结论时,可以同步生成注意力图(Attention Map),在 CT影像上标示出判断依据的区域。","correct":true}]', 'CD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 290, 'multi', '一家智能家居公司重新设计空调控制面板,需优化老年人使用体验。下列哪些改进符合交互设 计原则?', '[{"key":"A","text":"模式切换时,联机播放防寒保暖的保健品广告或夏季登山潜水旅游好去处","correct":false},{"key":"B","text":"待机界面显示放大版时钟,右上角固定显示空气质量指数,超过警戒值自动弹出红色警示框","correct":true},{"key":"C","text":"将温度调节按钮放大,每次操作伴随“嘀”声反馈,持续按住按钮时数值变化速度逐渐加快","correct":true},{"key":"D","text":"增加语音唤醒词,识别成功时面板呼吸灯闪烁","correct":true}]', 'BCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 291, 'multi', '打造一款面向故宫等大型历史文化景区的“沉浸式AI导游”,允许游客使用手机或专用设备实时 理解游客眼前的景象(如某个宫殿、文物),并结合游客的语音提问,提供流畅、低延迟、富有情 感的语音讲解。一个关键的现实约束是:景区内人流密集,移动网络信号可能非常不稳定或时断时 续。以下哪些架构设计和技术选型组合最为关键和高效?', '[{"key":"A","text":"建立高清视频通道,将语音识别、视觉分析、LLM推理、语音合成全部放在云端服务器执行,以 确保最高质量的回答。","correct":false},{"key":"B","text":"部署一个能完美覆盖、无缝漫游且能承载数万并发用户高质量连接的Wi-Fi网络,要求用户必须连 接到景区提供的专用Wi-Fi,通过服务质量(QoS)保障,强制所有数据流通过该稳定信道进行传 输。","correct":false},{"key":"C","text":"在设备端预置高质量的TTS(文本转语音)语音包和核心景点的多媒体资料,由LLM在云端生成 讲解文本后,指令设备端进行本地合成与播放。","correct":true},{"key":"D","text":"优先在设备端部署轻量级视觉模型进行快速目标识别,并将识别出的实体ID(如“太和殿”)而非 原始图像帧上传,以降低网络负载。","correct":true}]', 'CD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 292, 'multi', '一家律所计划构建一个AI助手,辅助律师基于内部案件数据库(用于RAG)起草法律文书。为 从技术架构层面有效缓解客户信息泄露风险,应集成哪些设计?', '[{"key":"A","text":"部署端到端加密存储方案,对案件数据库中的客户隐私信息(如身份信息、涉案细节)进行加密 处理,仅授权进程可解密调用","correct":true},{"key":"B","text":"构建精细化RBAC权限体系,按律师所属业务线、案件参与权限划分数据访问范围,禁止跨案 件、跨权限查询客户敏感数据","correct":true},{"key":"C","text":"集成数据脱敏引擎,在RAG检索、大模型生成法律文书的过程中,自动屏蔽客户身份证号、手机 号、住址等敏感字段(如用“***”替换关键字符)","correct":true},{"key":"D","text":"新增操作审计日志模块,记录AI助手的所有数据访问、文书生成操作,包含访问人、访问时间、 数据范围等信息,支持异常行为追溯","correct":true}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 293, 'multi', '你正在对大模型进行LORA微调,但在训练过程中发现模型开始过拟合,可采取的优化措施包 括?', '[{"key":"A","text":"使用早停法及时终止训练","correct":true},{"key":"B","text":"增加训练数据的多样性和数量","correct":true},{"key":"C","text":"适当增大batch size","correct":true},{"key":"D","text":"适当增大lora_rank值","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 294, 'multi', '以下哪些方法,有助于降低大模型使用成本?', '[{"key":"A","text":"精简输入提示词篇幅,同时要求大模型输出精简的内容","correct":true},{"key":"B","text":"根据任务复杂度,选择参数量合适的大模型","correct":true},{"key":"C","text":"对于任何任务,始终选择参数量较大的模型","correct":false},{"key":"D","text":"对于可以通过预定义逻辑、固定模板或经典算法高效完成的任务,不使用大模型处理","correct":true}]', 'ABD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 295, 'multi', '如果你需要自行部署大模型用于在线推理服务,以下哪些方案有助于提升推理速度?', '[{"key":"A","text":"对于长文本生成场景,启用KVCache","correct":true},{"key":"B","text":"使用CPU集群替代GPU,利用多线程并行处理请求","correct":false},{"key":"C","text":"使用经过量化的模型,并且评测确认量化后的模型效果符合业务需求","correct":true},{"key":"D","text":"任何场景,始终优先使用大参数量模型","correct":false}]', 'AC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 296, 'multi', '某教育类AI产品出现以下现象,哪些属于“幻觉”风险?', '[{"key":"A","text":"将“牛顿三大定律”解释为四条定律","correct":true},{"key":"B","text":"回答“泰坦尼克号唯一幸存者”时虚构人物","correct":true},{"key":"C","text":"将古代文言文翻译成现代白话文","correct":false},{"key":"D","text":"理解作文题意,自动生成800字高考作文","correct":false}]', 'AB') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 297, 'multi', '以下哪三种场景更需要防范AI模型“幻觉”的风险?', '[{"key":"A","text":"医疗诊断报告生成系统","correct":true},{"key":"B","text":"社交媒体趋势话题预测系统","correct":false},{"key":"C","text":"法律合同条款自动生成器","correct":true},{"key":"D","text":"教育领域历史知识问答系统","correct":true}]', 'ACD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 298, 'multi', '一家航空公司的AI维修服务,在查询特定零件扭矩值时,检索模块总是返回宽泛的概述性章节 而非精确的技术参数表。为系统性解决此问题,应采取哪两项措施?', '[{"key":"A","text":"增大分块尺寸(chunk_size),确保向量包含更完整的上下文信息","correct":false},{"key":"B","text":"为文档块添加\\"章节类型\\"元数据,并提升\\"参数表\\"类型的检索权重","correct":true},{"key":"C","text":"建立一个包含标准问题和精确答案位置的评测集以量化检索性能","correct":true},{"key":"D","text":"切换生成环节的基模,采用更强的模型从宽泛章节中找到精确答案","correct":false}]', 'BC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 299, 'multi', '关于文档处理系统工作流模式的选择,以下哪些描述正确?', '[{"key":"A","text":"任务之间存在数据依赖(如后续步骤需前序结果)应该并行执行","correct":false},{"key":"B","text":"步骤有依赖关系(如先翻译再排版)应该用流水线模式","correct":true},{"key":"C","text":"根据文档类型走不同逻辑(如合同和论文)应该用分支选择","correct":true},{"key":"D","text":"任务相互独立(如语法检查和格式检查)应该并行执行","correct":true}]', 'BCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 300, 'multi', '固定工作流Agent升级为能主动推荐替代选项的智能Agent,需要具备哪些能力?', '[{"key":"A","text":"理解用户真正想要的是\\"订到合适的机票\\"而非执行固定步骤","correct":true},{"key":"B","text":"在执行过程中根据实际情况灵活调整下一步","correct":true},{"key":"C","text":"当某个API调不通时能想办法用其他方式获取信息","correct":true},{"key":"D","text":"收集更多的用户反馈,将所有可能出现的分支情况都补充进预设规则库中","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 301, 'multi', '您负责一个新上线的AI语音助手。在一次市场推广活动中,流量瞬间飙升500%,导致大量用户 反馈语音请求后收到“服务无法理解您的请求”的错误。事后排查,系统瓶颈在于语音转文本(ASR)模 型服务无法承载瞬时洪峰流量。为了保障未来能优雅地应对此类流量洪峰,同时兼顾日常运营成 本,以下哪些架构优化措施组合最为关键?', '[{"key":"A","text":"在客户端实现一个重试机制,一旦应答质量不佳或出现错误,立即自动重新发起整个语音请求","correct":false},{"key":"B","text":"引入消息队列(如Kafka/Pulsar)实现请求的削峰填谷","correct":true},{"key":"C","text":"部署一个轻量级的“看门人”模型,前置于核心ASR模型,用于快速过滤无效或格式错误的音频","correct":true},{"key":"D","text":"为所有内部服务间调用强制启用mTLS(双向认证)确保通信链路的绝对安全","correct":false}]', 'BC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 302, 'multi', '你为跨境电商平台开发了新功能:用户上传商品图片后系统应自动生成多语言商品描述。但上 线后出现以下现象:1.图片能正常在OSS控制台查看 2.前端始终显示"描述生成中" 3.函数计算FC监控 显示无调用记录。你可以检查的技术要点是?', '[{"key":"A","text":"百炼模型服务的API配额余额是否用尽","correct":false},{"key":"B","text":"OSS存储桶是否配置FC触发器的事件通知","correct":true},{"key":"C","text":"OSS存储桶与FC函数是否部署在不同地域","correct":false},{"key":"D","text":"函数计算FC的执行角色是否有OSS读取权限","correct":true}]', 'BD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 303, 'multi', '为了提升知识索引的性能,可以采用以下哪些技术手段?', '[{"key":"A","text":"句子滑窗技术来增加索引的覆盖范围","correct":true},{"key":"B","text":"自动合并检索结果以减少冗余","correct":true},{"key":"C","text":"引入TF-IDF模型优化关键词匹配","correct":true},{"key":"D","text":"利用BGE等新型嵌入模型提高语义相似度计算精度","correct":true}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 304, 'multi', '一家教育科技公司想开发人工智能教学产品。哪些方案能利用AI实现个性化、智能化和普惠教 育?', '[{"key":"A","text":"方言识别系统辅助少数民族学生练习普通话","correct":true},{"key":"B","text":"根据学习进度和学生兴趣生成课后实验,如电路故障排查等","correct":true},{"key":"C","text":"考试时在线抽取选择题,实时自动判卷,对每个人的错误选项提供标准解析","correct":true},{"key":"D","text":"自适应学习平台根据学生水平动态调整题库","correct":true}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 305, 'multi', '你为跨境电商平台开发了新功能:用户上传商品照片后,系统可以自动找到商品并向用户介绍 商品特点。但上线后出现以下现象:1. 图片能正常在文件存储控制台查看 2. 前端始终显示描述"生成 中" 3. 模型服务监控显示无调用记录。你可以检查的技术要点是?', '[{"key":"A","text":"解码器的自注意力权重分布是否异常","correct":false},{"key":"B","text":"完成图片上传后,后端是否正确调用图像理解的API接口","correct":true},{"key":"C","text":"模型服务监控的日志接口是否正确绑定","correct":true},{"key":"D","text":"多模态特征融合的门控机制激活阈值是否过高","correct":false}]', 'BC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 306, 'multi', '你要给多个未归档的Keynote文档创建索引,这些文档中包括表格、流程图等复杂内容。在"文档', '[{"key":"A","text":"开发能解析Keynote的自定义Reader","correct":true},{"key":"B","text":"先将Keynote转成PDF,再用DashScopeParse处理","correct":true},{"key":"C","text":"调大RAG应用召回chunk的数量","correct":false},{"key":"D","text":"无需任何特殊处理,直接传Keynote路径","correct":false}]', 'AB') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 307, 'multi', '用户上传了一个包含复杂表格的Markdown文档,使用默认的RAG流程进行问答。用户提问关于 表格中特定单元格含义的问题时,大模型经常给出错误或不相关的回答。请问以下哪些方案可以尝 试解决这个问题?', '[{"key":"A","text":"对用户提问进行预处理,提取表格相关的关键词","correct":true},{"key":"B","text":"在文档切片时,将表格的行列信息添加到每个单元格的Chunk中","correct":true},{"key":"C","text":"将表格转换成JSON格式,然后使用JSONLoader加载数据","correct":true},{"key":"D","text":"使用OCR技术识别表格中的文字,并将识别结果添加到文本中","correct":false},{"key":"E","text":"使用更强大的Embedding模型","correct":true},{"key":"F","text":"增加训练数据,让大模型更好地理解表格内容","correct":false}]', 'ABCE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 308, 'multi', '场景:开发一个教育领域的智能辅导系统,需要适应不同学生的学习水平和进度。以下哪些功 能设计是值得推荐的?', '[{"key":"A","text":"动态调整问题难度基于学生表现","correct":true},{"key":"B","text":"提供个性化的学习路径建议","correct":true},{"key":"C","text":"生成针对性的练习和解析","correct":true},{"key":"D","text":"支持多轮互动和追问机制","correct":true},{"key":"E","text":"记录学习进度和薄弱环节","correct":true}]', 'ABCDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 309, 'multi', '场景:某公司要开发一个智能法律咨询助手,需要处理复杂的法律条文和案例。以下哪些技术 方案是合理的?', '[{"key":"A","text":"采用RAG架构,接入法律条文库和案例库","correct":true},{"key":"B","text":"对通用大模型进行法律领域的微调","correct":true},{"key":"C","text":"在提示词中明确要求模型引用具体法律条文","correct":true},{"key":"D","text":"设置免责声明,说明模型输出仅供参考","correct":true},{"key":"E","text":"建立人工审核机制,对重要建议进行复核","correct":true}]', 'ABCDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 310, 'multi', '场景:一个电商客服机器人需要处理退货、换货、投诉等多种业务场景。以下哪些设计考虑是 合理的?', '[{"key":"A","text":"为不同场景设计专门的提示词模板","correct":true},{"key":"B","text":"建立知识库,包含详细的退换货政策","correct":true},{"key":"C","text":"设置情绪识别和安抚机制","correct":true},{"key":"D","text":"提供转接人工客服的顺畅通道","correct":true},{"key":"E","text":"记录对话历史以便后续跟进","correct":true}]', 'ABCDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 311, 'multi', '某电商平台计划开发大模型智能客服系统,需实现“用户咨询商品售后政策→模型精准回答+推 荐相关售后流程文档”的功能。以下哪些技术方案可支撑该需求?', '[{"key":"A","text":"使用RAG技术,将平台售后政策文档存入向量数据库,用户提问时检索相关文档片段","correct":true},{"key":"B","text":"采用思维链提示,引导模型分步解析用户问题(如“用户问的是‘7天无理由退货’→需明确退货条 件、流程、注意事项”)","correct":true},{"key":"C","text":"直接使用通用大模型,不结合任何外部数据或提示优化","correct":false},{"key":"D","text":"调用阿里云语音识别API,将用户语音咨询转为文本后,再输入大模型处理","correct":true}]', 'ABD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 312, 'multi', '某电商平台计划使用大模型优化商品推荐系统,希望实现以下目标:个性化推荐、推荐理由生 成、多轮对话交互。以下哪些技术方案是合适的?', '[{"key":"A","text":"基于用户历史行为构建用户画像,用于个性化提示词","correct":true},{"key":"B","text":"使用协同过滤算法生成推荐,模型仅用于生成推荐理由","correct":true},{"key":"C","text":"完全依赖模型的推荐能力,不使用传统推荐算法","correct":false},{"key":"D","text":"实现对话状态跟踪,维护推荐上下文","correct":true},{"key":"E","text":"为不同商品类别设计专门的推荐策略","correct":true}]', 'ABDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 313, 'multi', '某电商平台开发大模型商品推荐系统,要求“根据用户浏览历史、购买记录、收藏列表推荐个性 化商品”。以下哪些技术组件是必要的?', '[{"key":"A","text":"向量数据库:存储用户行为向量(如浏览商品的向量)和商品向量(如商品属性向量)","correct":true},{"key":"B","text":"大模型Embedding接口:将用户行为(如“浏览手机”)和商品属性(如“品牌=苹果,类型=智能手 机”)转换为向量","correct":true},{"key":"C","text":"推荐算法模块:结合向量相似度(如用户行为向量与商品向量的余弦相似度)和业务规则(如避 免推荐已购买商品)生成推荐列表","correct":true},{"key":"D","text":"通用大模型API:直接让模型生成推荐商品名称,不依赖用户行为数据","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 314, 'multi', '某电商平台使用大模型优化商品推荐,要求“结合用户历史订单、实时浏览、商品库存”生成推荐 列表。以下哪些技术组件需集成?', '[{"key":"A","text":"向量数据库(存储商品特征与用户行为向量)","correct":true},{"key":"B","text":"大模型(生成个性化推荐理由与列表)","correct":true},{"key":"C","text":"库存管理系统API(获取实时商品库存状态)","correct":true},{"key":"D","text":"用户行为分析工具(提取历史订单与实时浏览数据)","correct":true}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 315, 'multi', '某公司开发大模型多轮对话客服系统,需解决“模型遗忘前文信息、对话逻辑不连贯”的问题。以 下哪些优化措施有效?', '[{"key":"A","text":"每次对话时,将历史对话记录与当前问题一起传入模型","correct":true},{"key":"B","text":"对历史对话进行摘要压缩,保留核心信息(如用户需求、已解决问题)","correct":true},{"key":"C","text":"限制对话轮次,超过10轮后强制结束对话","correct":false},{"key":"D","text":"使用会话状态管理工具,存储用户画像与对话关键实体","correct":true}]', 'ABD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 316, 'multi', '某公司开发大模型多轮对话应用时,出现“模型遗忘前文对话信息”的问题(如用户先问“推荐手 机”,再问“它的价格”,模型无法理解“它”指代手机)。以下哪些解决方案有效?', '[{"key":"A","text":"将历史对话记录与当前问题一起作为输入传递给模型(如“历史:用户问推荐手机;当前:它的价 格是多少?”)","correct":true},{"key":"B","text":"采用实体标注提示,在历史对话中标记核心实体(如“[实体:推荐的手机,品牌:华为,型号: Mate 60]”)","correct":true},{"key":"C","text":"增加模型的上下文窗口大小(如从4096Token扩展到8192Token),确保历史对话能被完整输入","correct":true},{"key":"D","text":"每轮对话后让模型总结前文要点,将总结结果作为下一轮输入的一部分","correct":true}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 317, 'multi', '某公司开发大模型智能办公助手,要求实现“会议录音转文字→生成会议纪要→提取待办事项”的 功能。以下哪些技术组合可支撑该需求?', '[{"key":"A","text":"语音识别API(如阿里云语音识别):将会议录音转为文本","correct":true},{"key":"B","text":"大模型文本总结接口:基于会议文本生成结构化纪要(如“会议主题、参会人、讨论内容”)","correct":true},{"key":"C","text":"信息抽取工具:从会议纪要中提取待办事项(如“负责人:张三,任务:提交报告,截止时间:周 五”)","correct":true},{"key":"D","text":"向量数据库:存储会议纪要文本,支持后续检索","correct":true},{"key":"E","text":"纯文本编辑器:仅手动输入会议内容,不支持录音转文字","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 318, 'multi', '开发者部署大模型应用时,需监控应用的运行状态。以下哪些指标属于核心监控指标?', '[{"key":"A","text":"推理延迟:从请求发出到接收响应的时间","correct":true},{"key":"B","text":"并发量(QPS):单位时间内的请求次数","correct":true},{"key":"C","text":"准确率:模型回答与正确结果的匹配程度","correct":true},{"key":"D","text":"显存占用:模型运行时消耗的GPU显存大小","correct":true}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 319, 'multi', '开发者部署开源大模型时,遇到"GPU显存不足"的问题。以下哪些解决方案有效?', '[{"key":"A","text":"使用模型量化技术(如将FP32量化为INT8或INT4),降低显存占用","correct":true},{"key":"B","text":"采用模型并行策略,将模型拆分到多块GPU上运行(如将Transformer层拆分到2块GPU)","correct":true},{"key":"C","text":"启用模型蒸馏,生成参数更少的小模型(如将13B模型蒸馏为3B模型)","correct":true},{"key":"D","text":"增加CPU内存容量,替代GPU显存运行模型","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 320, 'multi', '开发者在调用阿里云大模型API时,需控制调用成本。以下哪些措施有效?', '[{"key":"A","text":"合理设置max_tokens参数,限制输出文本长度(如生成商品标题时设为50Token以内)","correct":true},{"key":"B","text":"选择与任务匹配的轻量模型(如文本分类任务选择通义千问-轻量版,而非旗舰版)","correct":true},{"key":"C","text":"对输入文本进行精简,去除冗余内容(如调用模型总结文档时,先提取文档核心段落再输入)","correct":true},{"key":"D","text":"提高API调用并发量,增加单位时间内的调用次数","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 321, 'multi', '开发者调用大模型API时,需提升响应速度。以下哪些措施有效?', '[{"key":"A","text":"启用流式输出(Streaming),按Token分段返回结果","correct":true},{"key":"B","text":"选择轻量模型(如通义千问-1.8B)替代大参数模型(如通义千问-70B)","correct":true},{"key":"C","text":"对输入文本进行精简,去除冗余内容(如删除与问题无关的背景描述)","correct":true},{"key":"D","text":"增加API调用的超时时间(如从3秒延长至10秒)","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 322, 'multi', '开发者优化RAG应用时,发现"检索到的文本段与用户问题相关性低"(精度低)。以下哪些措施 可有效提升检索精度?', '[{"key":"A","text":"提高检索的相似度阈值(如从0.6升至0.8)","correct":true},{"key":"B","text":"优化文本分块策略,按语义逻辑分块(如将\\"大模型微调\\"相关内容归为同一分块)","correct":true},{"key":"C","text":"对输入问题进行语义增强(如补充\\"领域:电商,任务:售后\\"等上下文)","correct":true},{"key":"D","text":"减少向量数据库中的文档数量,删除无关文档","correct":true}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 323, 'multi', '以下哪些技术或方法可以用于视频合规检测的不同阶段?', '[{"key":"A","text":"使用MD5算法进行视频完整性校验","correct":true},{"key":"B","text":"使用FFmpeg进行视频格式转换和分段","correct":true},{"key":"C","text":"使用YOLOv5检测视频帧中的敏感物体","correct":true},{"key":"D","text":"使用Librosa分析视频中的音频特征","correct":true},{"key":"E","text":"使用深度学习模型对视频内容进行分类,例如识别暴力内容","correct":true},{"key":"F","text":"使用Tesseract进行OCR识别视频中的文字","correct":true}]', 'ABCDEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 324, 'multi', '下列代码片段中,哪些涉及模型训练过程中的正则化或优化策略?', '[{"key":"A","text":"weight_decay = 0.001","correct":true},{"key":"B","text":"scheduler = StepLR(optimizer, step_size=10, gamma=0.1)","correct":true},{"key":"C","text":"optimizer = SGD(model.parameters(), lr=0.01, momentum=0.9)","correct":true},{"key":"D","text":"loss = cross_entropy(with_logits=True) (outputs, labels)","correct":false},{"key":"E","text":"model = nn.Dropout(p=0.2)","correct":true},{"key":"F","text":"criterion = nn.CrossEntropyLoss()","correct":false}]', 'ABCE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 325, 'multi', '用户上传了一个包含多个图片的Markdown文档,使用默认的SimpleDirectoryReader和 VectorStoreIndex.from_documents构建索引。用户提问与图片相关的问题时,大模型无法给出正确的 答案。请问可能的原因有哪些?', '[{"key":"A","text":"大模型无法理解图片的含义。","correct":true},{"key":"B","text":"Chunks分割丢失了图片和文本之间的关联信息。","correct":false},{"key":"C","text":"SimpleDirectoryReader只能读取文本内容,无法解析图片信息。","correct":true},{"key":"D","text":"SimpleDirectoryReader无法读取图片文件。","correct":false},{"key":"E","text":"VectorStoreIndex.from_documents无法处理图片数据。","correct":true},{"key":"F","text":"用户提问的方式不正确。","correct":false}]', 'ACE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 326, 'multi', '对于输出格式的要求,下面哪些描述是合理的?', '[{"key":"A","text":"限制输出的范围","correct":true},{"key":"B","text":"增加不相关的内容","correct":false},{"key":"C","text":"结合样例来明确输出的方法","correct":true},{"key":"D","text":"包含额外的说明性文字","correct":false},{"key":"E","text":"定义输出的类型","correct":true},{"key":"F","text":"明确指定输出的格式","correct":true}]', 'ACEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 327, 'multi', '为了有效监控过拟合和欠拟合,可采取的措施包括:', '[{"key":"A","text":"增加数据增强以丰富训练集多样性","correct":true},{"key":"B","text":"不断增加模型复杂度直到验证性能最佳","correct":false},{"key":"C","text":"使用dropout层增加模型的泛化能力","correct":true},{"key":"D","text":"仅在大规模数据集上训练模型","correct":false},{"key":"E","text":"监视训练和验证损失的趋势","correct":true},{"key":"F","text":"提前终止训练(early stopping)","correct":true}]', 'ACEF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 328, 'multi', '以下哪些现象表明文档切片方法需要优化?', '[{"key":"A","text":"大模型对文档中一段文本内容的理解过于笼统,无法获取更详细的信息。","correct":true},{"key":"B","text":"大模型的检索速度非常慢,影响用户体验。","correct":false},{"key":"C","text":"大模型无法理解文档中图片所表达的信息。","correct":false},{"key":"D","text":"大模型无法理解文档中的表格数据含义,例如无法比较不同单元格的大小。","correct":true},{"key":"E","text":"大模型能够准确回答所有用户提问。","correct":false},{"key":"F","text":"大模型返回的结果与用户提问无关。","correct":true}]', 'ADF') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 329, 'multi', '以下哪些选项体现了提示词要素中的"任务目标(Object)"?', '[{"key":"A","text":"请你翻译以下英文文本。","correct":true},{"key":"B","text":"请你根据以下材料,生成一篇新闻稿。","correct":true},{"key":"C","text":"输出格式为HTML。","correct":false},{"key":"D","text":"请你分析一下这个产品的优缺点。","correct":true},{"key":"E","text":"假设你是一个专业的厨师。","correct":false},{"key":"F","text":"目标用户是青少年群体。","correct":false}]', 'ABD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 330, 'multi', '通过LlamaIndex创建RAG应用时,rerank的使用方法包括?', '[{"key":"A","text":"先直接召回较多数量的文本段,再使用rerank得到更精确的top_n的文本段","correct":true},{"key":"B","text":"对用户的提问进行改写","correct":false},{"key":"C","text":"放在后处理模块中","correct":true},{"key":"D","text":"根据用户的输入去向量数据库进行检索","correct":false}]', 'AC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 331, 'multi', '以下哪种形式可以用作提示词的分隔符?', '[{"key":"A","text":"XML标签","correct":true},{"key":"B","text":"<<","correct":true},{"key":"C","text":"**","correct":false},{"key":"D","text":"---","correct":true},{"key":"E","text":">","correct":true}]', 'ABDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 332, 'multi', '某医疗科技公司开发大模型辅助诊断助手,要求"输入患者症状→推荐可能病症→引用医学指南 依据"。以下哪些措施可确保应用的可靠性?', '[{"key":"A","text":"使用RAG技术接入权威医学指南数据库(如《临床诊疗指南》)","correct":true},{"key":"B","text":"在提示词中明确要求\\"仅基于指南回答,不编造医学建议\\"","correct":true},{"key":"C","text":"采用少样本提示,提供\\"症状→病症→指南依据\\"示例","correct":true},{"key":"D","text":"限制模型输出内容,标注\\"仅供参考,不替代医生诊断\\"","correct":true},{"key":"E","text":"直接让模型基于通用知识生成回答,无需接入医学指南","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 333, 'multi', '某企业使用大模型处理客户反馈,要求"从反馈中提取问题类型、客户满意度、联系方式,并生 成统计报表"。以下哪些任务类型需组合实现?', '[{"key":"A","text":"命名实体识别(提取联系方式)","correct":true},{"key":"B","text":"文本分类(判断问题类型、客户满意度)","correct":true},{"key":"C","text":"文本摘要(生成统计报表)","correct":false},{"key":"D","text":"信息抽取(提取问题类型、满意度标签)","correct":true}]', 'ABD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 334, 'multi', '某企业开发大模型文档问答系统,要求"支持PDF、Word、TXT多种格式文档,且能精准定位回 答来源页码"。以下哪些技术方案需实现?', '[{"key":"A","text":"使用文档解析工具(如PyPDF2、python-docx)提取不同格式文档的文本与页码","correct":true},{"key":"B","text":"对提取的文本按\\"段落+页码\\"进行分块,保留页码元数据","correct":true},{"key":"C","text":"将分块文本转换为向量,存入向量数据库","correct":true},{"key":"D","text":"检索时返回匹配向量对应的页码信息","correct":true},{"key":"E","text":"让模型直接读取原始文档格式,无需解析","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 335, 'multi', '某企业开发大模型文档问答系统,要求"支持PDF、Word、Excel多种格式文档的上传与问答"。 以下哪些技术工具需集成?', '[{"key":"A","text":"PDF解析工具(如PyPDF2、PDFMiner):提取PDF中的文本、表格内容","correct":true},{"key":"B","text":"Word解析工具(如python-docx):提取Word文档中的文本、图片描述","correct":true},{"key":"C","text":"Excel解析工具(如Pandas、openpyxl):提取Excel表格中的结构化数据","correct":true},{"key":"D","text":"OCR工具(如阿里云OCR):提取文档中图片包含的文本","correct":true}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 336, 'multi', '某企业开发大模型驱动的智能运维系统,需实现"实时分析服务器日志、识别异常故障、生成解 决方案"的功能。以下哪些技术方案是必要组成部分?', '[{"key":"A","text":"使用日志解析工具提取结构化日志数据(如时间、错误类型、服务器IP)","correct":true},{"key":"B","text":"采用文本分类模型识别日志中的\\"异常故障\\"类别","correct":true},{"key":"C","text":"调用大模型生成针对不同故障类型的解决方案","correct":true},{"key":"D","text":"使用向量数据库存储历史故障案例,供模型参考","correct":true}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 337, 'multi', '某企业开发大模型多模态应用,要求"用户上传产品图片→模型识别产品特征→生成推广文案"。 以下哪些技术组件需集成?', '[{"key":"A","text":"图像识别API(如阿里云视觉智能开放平台):提取产品特征(如\\"颜色:红色,类型:连衣 裙\\")","correct":true},{"key":"B","text":"大模型文本生成接口:基于特征生成文案(如\\"红色连衣裙,简约设计,适合夏季穿搭\\")","correct":true},{"key":"C","text":"少样本提示:提供\\"特征列表→文案\\"示例(如\\"特征:白色运动鞋→文案:''百搭小白鞋,轻盈舒 适''\\")","correct":true},{"key":"D","text":"向量数据库:存储产品特征向量,支持相似产品文案复用","correct":true},{"key":"E","text":"纯文本输入框:仅接收文字描述,不支持图片上传","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 338, 'multi', '某企业计划基于阿里云大模型开发内部培训助手,要求实现"上传培训课件→模型生成练习题 +解答思路"的功能。以下哪些技术组合是必要的?', '[{"key":"A","text":"使用PDF解析工具(如PyPDF2)提取课件文本内容","correct":true},{"key":"B","text":"采用少样本提示,提供\\"课件片段→练习题→解答思路\\"的示例","correct":true},{"key":"C","text":"调用阿里云大模型API生成练习题,限制输出格式(如\\"单选题+选项+正确答案+解答思路\\")","correct":true},{"key":"D","text":"使用RAG技术,将课件内容存入向量数据库,生成题目时检索相关知识点","correct":true},{"key":"E","text":"直接让模型生成与课件无关的通用练习题,无需关联课件内容","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 339, 'multi', '某企业计划构建大模型应用开发平台,支持"模型训练、部署、监控"全流程。以下哪些阿里云产 品可作为核心组件?', '[{"key":"A","text":"阿里云PAI平台:提供模型训练、微调、部署服务","correct":true},{"key":"B","text":"阿里云向量数据库:存储RAG应用的文档向量","correct":true},{"key":"C","text":"阿里云OSS:存储训练数据、模型权重文件","correct":true},{"key":"D","text":"阿里云ARMS:监控应用的QPS、延迟等指标","correct":true},{"key":"E","text":"阿里云通义千问API:仅提供文本生成能力,不支持全流程","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 340, 'multi', '某内容审核系统需要处理多种类型的有害内容。以下哪些技术组合最有效?', '[{"key":"A","text":"多层级内容过滤管道","correct":true},{"key":"B","text":"基于规则和模型的混合系统","correct":true},{"key":"C","text":"实时内容毒性检测","correct":true},{"key":"D","text":"人工审核所有内容","correct":false},{"key":"E","text":"仅依赖单一检测模型","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 341, 'multi', '某内容创作平台使用大模型生成文章,需要避免版权侵权和内容重复问题。以下哪些方法是有 效的?', '[{"key":"A","text":"在训练数据中去除版权内容","correct":false},{"key":"B","text":"使用抄袭检测工具检查生成内容","correct":true},{"key":"C","text":"要求模型进行原创性写作","correct":true},{"key":"D","text":"基于多个来源进行综合创作","correct":true},{"key":"E","text":"仅生成事实性内容,避免创造性内容","correct":false}]', 'BCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 342, 'multi', '某零售企业开发大模型智能导购应用,要求"根据用户实时咨询(如:推荐防水运动鞋)→生成 推荐列表+搭配建议"。以下哪些技术方案可支撑该需求?', '[{"key":"A","text":"调用大模型Embedding接口,将用户咨询转为向量","correct":true},{"key":"B","text":"向量数据库存储商品特征向量(如\\"功能:防水,品类:运动鞋\\")","correct":true},{"key":"C","text":"采用少样本提示,提供\\"咨询→推荐→搭配\\"示例","correct":true},{"key":"D","text":"集成商品库存API,确保推荐商品有货","correct":true},{"key":"E","text":"直接让模型生成推荐列表,不依赖实时库存数据","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 343, 'multi', '某开发者使用阿里云PAI平台部署大模型应用,要求支持"高并发请求、低延迟响应、资源弹性扩 展"。以下哪些PAI平台功能需重点配置?', '[{"key":"A","text":"PAI-EAS(弹性计算服务)的容器化部署","correct":true},{"key":"B","text":"PAI-EAS的自动扩缩容功能","correct":true},{"key":"C","text":"PAI-Studio的模型微调功能","correct":false},{"key":"D","text":"PAI-EAS的性能监控与告警功能","correct":true}]', 'ABD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 344, 'multi', '某开发者使用阿里云PAI平台部署大模型,要求实现"高并发支持+低延迟响应"。以下哪些部署配 置符合需求?', '[{"key":"A","text":"使用PAI-EAS弹性计算服务,配置自动扩缩容(如QPS超过100时自动增加实例数)","correct":true},{"key":"B","text":"选择GPU实例(如A10)部署模型,启用模型量化(INT8),降低推理延迟","correct":true},{"key":"C","text":"采用动态批处理(Dynamic Batching)策略,提升GPU利用率","correct":true},{"key":"D","text":"将模型部署在单台CPU实例上,减少资源成本","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 345, 'multi', '某开发者开发大模型文本生成应用,要求"生成的文本符合特定风格(如正式商务、活泼口语),且无语法错误"。以下哪些提示优化措施有效?', '[{"key":"A","text":"在提示词中明确风格要求(如\\"生成正式商务风格的邮件\\")","correct":true},{"key":"B","text":"提供该风格的文本示例,让模型学习","correct":true},{"key":"C","text":"要求模型\\"生成后检查语法错误,修正后输出\\"","correct":true},{"key":"D","text":"使用结构化提示,限定文本结构(如\\"邮件主题-正文-落款\\")","correct":true},{"key":"E","text":"不做任何提示优化,依赖模型自动判断风格","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 346, 'multi', '某开发者调用阿里云大模型API时,遇到"API调用失败"的问题。以下哪些排查方向是合理的?', '[{"key":"A","text":"检查API密钥是否正确,是否存在过期或权限不足","correct":true},{"key":"B","text":"检查请求参数是否符合要求(如Token数量、格式)","correct":true},{"key":"C","text":"检查网络连接是否正常,是否能访问阿里云API服务地址","correct":true},{"key":"D","text":"检查模型是否处于维护状态,是否有服务中断通知","correct":true}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 347, 'multi', '某金融机构需要开发风险报告分析系统,要求确保分析结果的准确性和可解释性。以下哪些措 施是重要的?', '[{"key":"A","text":"使用思维链提示,要求模型展示分析过程","correct":true},{"key":"B","text":"基于权威风险数据库构建RAG系统","correct":true},{"key":"C","text":"设置结果验证机制,交叉检查关键数据","correct":true},{"key":"D","text":"要求模型提供数据来源引用","correct":true},{"key":"E","text":"仅使用模型的最终结论,不关心中间过程","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 348, 'multi', '某金融机构基于阿里云大模型开发智能风控系统,要求"分析客户征信文本→识别风险关键词→ 生成风险评估报告",且需符合数据安全合规要求。以下哪些措施是必要的?', '[{"key":"A","text":"对客户征信文本进行数据脱敏(如隐藏身份证号、银行卡号)","correct":true},{"key":"B","text":"采用私有化部署大模型,避免敏感数据传输至公有云","correct":true},{"key":"C","text":"使用RAG技术接入金融风险关键词库,确保识别准确性","correct":true},{"key":"D","text":"调用大模型API生成报告时,限制输出内容(仅包含风险等级、关键词列表)","correct":true},{"key":"E","text":"直接将原始征信文本上传至公有云大模型,无需任何处理","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 349, 'multi', '某教育科技公司开发大模型学习助手,要求实现"学生上传错题→模型分析错误原因→推荐同类 练习题"的功能。以下哪些技术组合适配该需求?', '[{"key":"A","text":"使用OCR工具提取错题中的题目文本、学生答案","correct":true},{"key":"B","text":"采用思维链提示,引导模型分步分析错误(如\\"第一步:判断知识点→第二步:对比正确步骤与学 生答案\\")","correct":true},{"key":"C","text":"调用教育大模型API生成同类练习题,要求包含解析","correct":true},{"key":"D","text":"使用RAG技术接入学科知识点库,确保推荐题目的关联性","correct":true},{"key":"E","text":"直接让模型生成任意练习题,无需关联错题知识点","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 350, 'multi', '某公司正在构建智能客服系统,需要处理多种类型的用户查询,包括产品咨询、技术支持、投 诉建议等。为确保系统在不同场景下都能提供优质服务,以下哪些措施是有效的?', '[{"key":"A","text":"为每种查询类型设计专门的提示词模板","correct":true},{"key":"B","text":"使用统一的通用提示词处理所有查询","correct":false},{"key":"C","text":"构建查询分类器,根据类型动态选择处理策略","correct":true},{"key":"D","text":"为复杂查询设置人工转接机制","correct":true},{"key":"E","text":"仅依赖模型的通用能力,不进行特殊优化","correct":false}]', 'ACD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 351, 'multi', '某公司使用大模型生成技术文档,需要确保术语的一致性和准确性。以下哪些方法组合最有 效?', '[{"key":"A","text":"构建术语库并在生成过程中强制使用","correct":true},{"key":"B","text":"使用统一的文档模板","correct":true},{"key":"C","text":"事后人工检查所有术语","correct":false},{"key":"D","text":"实现术语一致性检查工具","correct":true},{"key":"E","text":"依赖模型的术语管理能力","correct":false}]', 'ABD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 352, 'multi', '某公司使用大模型进行代码审查,希望识别以下问题:安全漏洞、性能问题、代码规范违反。 以下哪些提示词设计是有效的?', '[{"key":"A","text":"\\"检查这段代码的质量\\"","correct":false},{"key":"B","text":"\\"作为资深开发工程师,从安全性、性能和规范性三方面审查代码\\"","correct":true},{"key":"C","text":"\\"识别代码中的安全漏洞,特别是注入漏洞和权限问题\\"","correct":true},{"key":"D","text":"\\"检查代码是否符合PEP8规范\\"","correct":true},{"key":"E","text":"\\"随便看看这段代码\\"","correct":false}]', 'BCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 353, 'multi', '关于提示工程,以下哪些描述是正确的?', '[{"key":"A","text":"思维链提示可以提升模型在复杂推理任务上的表现","correct":true},{"key":"B","text":"角色扮演提示可以引导模型以特定身份或风格进行回应","correct":true},{"key":"C","text":"零样本学习不需要提供任何任务示例","correct":true},{"key":"D","text":"少样本学习的效果总是优于零样本学习","correct":false},{"key":"E","text":"清晰的指令和约束条件对模型输出质量至关重要","correct":true}]', 'ABCE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 354, 'multi', '关于大模型的伦理治理,以下哪些做法是推荐的?', '[{"key":"A","text":"建立多学科参与的伦理审查委员会","correct":true},{"key":"B","text":"开展针对模型偏见和公平性的评估","correct":true},{"key":"C","text":"制定明确的内容安全红线策略","correct":true},{"key":"D","text":"对模型能力进行过度宣传以获取投资","correct":false},{"key":"E","text":"建立透明的用户告知和同意机制","correct":true}]', 'ABCE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 355, 'multi', '关于大模型的局限性,以下哪些认识是正确的?', '[{"key":"A","text":"可能产生看似合理但实际错误的内容","correct":true},{"key":"B","text":"知识受限于训练数据截止时间","correct":true},{"key":"C","text":"对输入提示的微小变化可能敏感","correct":true},{"key":"D","text":"缺乏真正的理解和常识","correct":true},{"key":"E","text":"无法保证长期对话的完全一致性","correct":true}]', 'ABCDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 356, 'multi', '关于大模型的安全防护,以下哪些措施是有效的?', '[{"key":"A","text":"输入输出内容过滤","correct":true},{"key":"B","text":"对抗性攻击检测","correct":true},{"key":"C","text":"安全对齐训练","correct":true},{"key":"D","text":"红队测试","correct":true},{"key":"E","text":"权限控制和访问管理","correct":true}]', 'ABCDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 357, 'multi', '关于大模型"微调"与"提示工程"的区别,以下哪些描述正确?', '[{"key":"A","text":"微调需修改模型参数,提示工程无需修改模型参数","correct":true},{"key":"B","text":"微调对数据量要求较高,提示工程可适配小数据场景","correct":true},{"key":"C","text":"微调后模型长期保留领域知识,提示工程需每次输入相关信息","correct":true},{"key":"D","text":"微调的计算资源消耗低于提示工程","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 358, 'multi', '关于大模型"推理速度优化",以下哪些措施是有效的?', '[{"key":"A","text":"使用轻量化模型(如3B参数模型替代13B模型)","correct":true},{"key":"B","text":"对模型进行量化(如FP16转为INT8)","correct":true},{"key":"C","text":"采用模型并行或数据并行技术","correct":true},{"key":"D","text":"减少上下文窗口大小(在满足需求的前提下)","correct":true},{"key":"E","text":"增加模型的迭代次数","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 359, 'multi', '关于大模型"幻觉"现象的规避措施,以下哪些做法有效?', '[{"key":"A","text":"在提示词中明确要求模型\\"基于事实回答,不确定时说明''无法确定'',不编造信息\\"","correct":true},{"key":"B","text":"使用RAG技术,让模型基于检索到的真实文档生成回答,减少虚构内容","correct":true},{"key":"C","text":"对模型生成的回答进行事实校验(如调用知识库API验证关键信息)","correct":true},{"key":"D","text":"采用少样本提示,提供\\"问题→正确回答→错误回答(幻觉)→原因分析\\"的示例,引导模型规避 幻觉","correct":true},{"key":"E","text":"选择参数更大的模型,认为参数越大幻觉率越低","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 360, 'multi', '关于大模型"函数调用"能力的应用场景,以下哪些属于典型场景?', '[{"key":"A","text":"根据用户提供的地址,调用地图API查询周边餐厅信息","correct":true},{"key":"B","text":"接收用户的Excel表格数据,调用数据分析函数(如求和、平均值)生成统计结果","correct":true},{"key":"C","text":"生成产品推广文案,无需调用外部工具","correct":false},{"key":"D","text":"接收用户的航班查询请求,调用航司API获取实时航班动态(如起飞时间、延误情况)","correct":true}]', 'ABD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 361, 'multi', '关于大模型"泛化能力",以下哪些描述是正确的?', '[{"key":"A","text":"泛化能力指模型在未见过的数据/任务上的表现","correct":true},{"key":"B","text":"预训练数据的多样性越高,模型泛化能力通常越强","correct":true},{"key":"C","text":"微调时使用过多特定场景数据,可能降低模型泛化能力(过拟合)","correct":true},{"key":"D","text":"模型参数数量越大,泛化能力一定越强","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 362, 'multi', '关于大模型"安全性与合规性",以下哪些措施能保障应用符合企业要求?', '[{"key":"A","text":"对用户输入内容进行敏感信息过滤(如手机号、身份证号脱敏)","correct":true},{"key":"B","text":"限制模型生成内容,禁止生成违法、违规信息","correct":true},{"key":"C","text":"采用私有化部署,避免企业数据外泄","correct":true},{"key":"D","text":"对模型生成的回答进行合规性审核","correct":true},{"key":"E","text":"不限制用户输入,完全依赖模型自身的安全机制","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 363, 'multi', '关于阿里云大模型API的"参数调优",以下哪些参数调整可影响模型的输出效果?', '[{"key":"A","text":"max_tokens:控制模型生成文本的最大长度","correct":true},{"key":"B","text":"temperature:控制生成内容的随机性(创新性)","correct":true},{"key":"C","text":"top_p:控制生成时选择词汇的范围(如top_p=0.9表示仅从概率前90%的词汇中选择)","correct":true},{"key":"D","text":"stop:设置生成终止词(如遇到\\"END\\"时停止生成)","correct":true}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 364, 'multi', '关于阿里云PAI平台的核心功能,以下哪些描述正确?', '[{"key":"A","text":"支持模型训练:可基于自有数据微调通义千问等基础模型","correct":true},{"key":"B","text":"提供模型部署服务:可将训练后的模型封装为API供应用调用","correct":true},{"key":"C","text":"集成数据处理工具:支持对文本、图像等数据进行清洗、标注","correct":true},{"key":"D","text":"仅支持阿里云自研模型,不兼容开源模型(如Llama3)","correct":false}]', 'ABC') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 365, 'multi', '关于RAG技术在大模型应用中的优势,以下描述正确的有?', '[{"key":"A","text":"扩展大模型的知识边界,支持最新/领域特定数据","correct":true},{"key":"B","text":"减少模型幻觉,基于真实检索数据生成回答","correct":true},{"key":"C","text":"降低模型微调成本,无需通过微调更新知识","correct":true},{"key":"D","text":"提升回答的可解释性,可追溯回答来源(如引用的文档)","correct":true},{"key":"E","text":"加快模型推理速度,减少模型计算量","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 366, 'multi', '当发现大模型在某个任务上表现不佳时,以下哪些属于有效的优化方向?', '[{"key":"A","text":"改进提示词工程,提供更清晰的指令和示例","correct":true},{"key":"B","text":"收集相关数据对模型进行微调","correct":true},{"key":"C","text":"检查输入数据是否存在噪音或偏差","correct":true},{"key":"D","text":"尝试使用不同架构或规模的模型","correct":true},{"key":"E","text":"放弃该任务,认为大模型无法胜任","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 367, 'multi', '当发现大模型生成的内容存在事实性错误时,以下哪些方法可以有效改善这一问题?', '[{"key":"A","text":"采用RAG架构,引入外部知识源","correct":true},{"key":"B","text":"在提示词中要求模型注明信息来源","correct":true},{"key":"C","text":"使用思维链(CoT)提示,让模型展示推理过程","correct":true},{"key":"D","text":"对模型进行领域相关的微调","correct":true},{"key":"E","text":"完全依赖模型的内置知识,不进行任何干预","correct":false}]', 'ABCD') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 368, 'multi', '当大模型应用需要处理实时流式数据时,以下哪些技术考虑是重要的?', '[{"key":"A","text":"支持流式响应,逐步输出结果","correct":true},{"key":"B","text":"处理长时间运行的对话会话","correct":true},{"key":"C","text":"管理上下文窗口,避免历史信息过多","correct":true},{"key":"D","text":"实现低延迟的推理优化","correct":true},{"key":"E","text":"保证会话状态的一致性","correct":true}]', 'ABCDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 369, 'multi', '当大模型应用需要处理多模态信息(如图文结合)时,以下哪些方案是可行的?', '[{"key":"A","text":"使用支持多模态的大模型(如GPT-4V)","correct":true},{"key":"B","text":"分别处理不同模态的信息,然后进行融合","correct":true},{"key":"C","text":"将非文本信息转换为文本描述,再输入文本模型","correct":true},{"key":"D","text":"忽略非文本信息,只处理文本部分","correct":false},{"key":"E","text":"训练专门的多模态融合模型","correct":true}]', 'ABCE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
INSERT INTO acp_questions (source_key, question_no, section, body, options_json, answer) VALUES ('pdf-multi', 370, 'multi', '当大模型生成的内容风格不符合预期时,以下哪些方法可以尝试调整?', '[{"key":"A","text":"在提示词中更详细地描述期望的风格","correct":true},{"key":"B","text":"提供符合期望风格的示例(Few-Shot)","correct":true},{"key":"C","text":"调整温度(Temperature)参数","correct":true},{"key":"D","text":"使用角色扮演(Role-Playing)提示","correct":true},{"key":"E","text":"对模型进行特定风格的微调","correct":true}]', 'ABCDE') ON DUPLICATE KEY UPDATE body=VALUES(body), options_json=VALUES(options_json), answer=VALUES(answer);
